// 用語集（3）― docs/DATA_SPEC.md 14
window.GLOSSARY = (window.GLOSSARY || []).concat([
  {term: "ユダヤ教",yomi: "ゆだやきょう",def: "ヘブライ人（ユダヤ人）の一神教。唯一神ヤハウェを信じ、選民思想と救世主（メシア）待望を特色とする。バビロン捕囚後に教団として確立し、『旧約聖書』を聖典とする。キリスト教・イスラーム教の母体となった。",year: -538,region: "west",cat: "思想・宗教",rank: 3,course: ["tankyu"],related: ["ヘブライ人","バビロン捕囚","キリスト教","一神教"]},
  {term: "ユトレヒト同盟",yomi: "ゆとれひとどうめい",def: "1579年、スペイン支配に抵抗するネーデルラント北部7州が結んだ同盟。オラニエ公ウィレムを指導者に独立戦争を続け、1581年に独立を宣言してネーデルラント連邦共和国（オランダ）の母体となった。",year: 1579,region: "europe",cat: "組織・運動",rank: 2,course: ["tankyu"],related: ["オランダ独立戦争","フェリペ2世","ネーデルラント連邦共和国"]},
  {term: "ユリウス暦",yomi: "ゆりうすれき",def: "カエサルがエジプトの太陽暦をもとに前46年に制定した暦。1年を365日とし、4年に1度うるう年をおいた。のちにずれが生じ、1582年に教皇グレゴリウス13世がグレゴリウス暦に改めた。",year: -46,region: "europe",cat: "文化・学問",rank: 2,course: ["tankyu"],related: ["カエサル","太陽暦","グレゴリウス暦"]},
  {term: "ユンカー",yomi: "ゆんかー",def: "エルベ川以東のプロイセンの地主貴族。農奴を使う農場領主制（グーツヘルシャフト）で穀物を西欧に輸出し、官僚・将校の多くを出してプロイセン国家を支えた。ビスマルクもユンカー出身である。",region: "europe",cat: "経済・社会",rank: 3,course: ["tankyu"],related: ["プロイセン","農場領主制","ビスマルク","グーツヘルシャフト"]},
  {term: "ユーグ=カペー",yomi: "ゆーぐ=かぺー",def: "パリ伯で、987年にカロリング家が断絶した西フランク王国の王に選ばれ、カペー朝を開いた人物。当初の王権は弱く、パリ周辺を支配するにすぎなかったが、カペー朝は14世紀まで続いた。",year: 987,region: "europe",cat: "人物",rank: 2,course: ["tankyu"],related: ["カペー朝","西フランク王国","パリ伯"]},
  {term: "ユーゴスラヴィア",yomi: "ゆーごすらゔぃあ",def: "第一次世界大戦後に成立したセルブ=クロアート=スロヴェーン王国を起源とし、1929年に改称した南スラヴ人の国家。第二次世界大戦後はティトーの指導で独自の社会主義を進めたが、冷戦後に解体した。",year: 1918,end: 2003,region: "europe",cat: "国家・王朝",rank: 3,course: ["sogo","tankyu"],related: ["ティトー","南スラヴ人","ユーゴスラヴィア紛争","非同盟諸国"]},
  {term: "ユーゴスラヴィア紛争",yomi: "ゆーごすらゔぃあふんそう",def: "冷戦終結後、ユーゴスラヴィア連邦の解体にともなって起こった一連の民族紛争。スロヴェニア・クロアティアの独立、ボスニア=ヘルツェゴヴィナ内戦、コソヴォ紛争などで多くの犠牲者と難民が出た。",year: 1991,end: 2001,region: "europe",cat: "事件・戦争",rank: 3,course: ["sogo","tankyu"],related: ["ユーゴスラヴィア解体","ボスニア紛争","コソヴォ紛争","民族紛争"]},
  {term: "ユーゴスラヴィア解体",yomi: "ゆーごすらゔぃあかいたい",def: "1991年のスロヴェニア・クロアティアの独立宣言から始まったユーゴスラヴィア連邦の分裂。マケドニア・ボスニア=ヘルツェゴヴィナもつづき、2006年にはモンテネグロがセルビアから分離した。",year: 1991,end: 2006,region: "europe",cat: "事件・戦争",rank: 2,course: ["sogo","tankyu"],related: ["ユーゴスラヴィア","ユーゴスラヴィア紛争","冷戦の終結"]},
  {term: "ユーロ",yomi: "ゆーろ",def: "ヨーロッパ連合（EU）の共通通貨。マーストリヒト条約にもとづき1999年に決済用として導入され、2002年から紙幣・硬貨の流通が始まった。欧州中央銀行が金融政策を担う。",year: 1999,region: "europe",cat: "経済・社会",rank: 3,course: ["sogo"],related: ["ヨーロッパ連合（EU）","マーストリヒト条約","ヨーロッパ統合"]},
  {term: "ヨルダン川西岸",yomi: "よるだんがわせいがん",def: "ヨルダン川の西側の地域。第1次中東戦争後にヨルダンが併合したが、1967年の第3次中東戦争でイスラエルが占領した。オスロ合意後にパレスチナ自治区となったが、ユダヤ人入植地の拡大が問題となっている。",year: 1967,region: "west",cat: "地名・地域",rank: 2,course: ["sogo","tankyu"],related: ["中東戦争","パレスチナ問題","パレスチナ暫定自治協定"]},
  {term: "ヨークタウン",yomi: "よーくたうん",def: "アメリカ合衆国ヴァージニア州の港町。1781年、ワシントンの率いる植民地軍とフランス軍がここでイギリス軍を降伏させ、アメリカ独立戦争の勝敗を事実上決めた。",year: 1781,region: "america",cat: "地名・地域",rank: 1,course: ["sogo","tankyu"],related: ["ヨークタウンの戦い","アメリカ独立戦争","ヴァージニア"]},
  {term: "ヨークタウンの戦い",yomi: "よーくたうんのたたかい",def: "1781年、アメリカ独立戦争でワシントンの植民地軍とフランス軍がイギリス軍を包囲し降伏させた戦い。これで独立戦争の大勢が決まり、1783年のパリ条約でイギリスはアメリカの独立を承認した。",year: 1781,region: "america",cat: "事件・戦争",rank: 2,course: ["sogo","tankyu"],related: ["アメリカ独立戦争","ワシントン","パリ条約（1783）"]},
  {term: "ヨーゼフ2世",yomi: "よーぜふにせい",def: "オーストリアの神聖ローマ皇帝で、マリア=テレジアの子。啓蒙専制君主として宗教寛容令や農奴解放令を出し、中央集権的な改革を進めたが、貴族や諸地域の反発で多くは挫折した。",year: 1765,end: 1790,region: "europe",cat: "人物",rank: 3,course: ["tankyu"],related: ["啓蒙専制君主","マリア=テレジア","宗教寛容令","農奴解放令"]},
  {term: "ヨーロッパ統合",yomi: "よーろっぱとうごう",def: "第二次世界大戦後、西ヨーロッパ諸国が経済協力から進めた統合の動き。1952年のヨーロッパ石炭鉄鋼共同体に始まり、EEC・EC を経て、1993年のヨーロッパ連合（EU）発足へと発展した。",year: 1952,region: "europe",cat: "経済・社会",rank: 3,course: ["sogo","tankyu"],related: ["ヨーロッパ連合（EU）","ヨーロッパ石炭鉄鋼共同体","ヨーロッパ共同体（EC）"]},
  {term: "ヨーロッパ連合（EU）",yomi: "よーろっぱれんごう",def: "1992年調印のマーストリヒト条約にもとづき、1993年に EC を発展させて発足した地域統合組織。共通通貨ユーロの導入や共通外交・安全保障政策を進め、冷戦後には東ヨーロッパ諸国も加盟した。",year: 1993,region: "europe",cat: "組織・運動",rank: 3,course: ["sogo","tankyu"],related: ["マーストリヒト条約","ユーロ","ヨーロッパ統合"]},
  {term: "ヨーロッパ遠征",yomi: "よーろっぱえんせい",def: "チンギス=カンの孫バトゥが率いたモンゴル軍の西方遠征。ルーシ諸国を征服し、1241年にワールシュタットの戦いでドイツ・ポーランド連合軍を破った。のちキプチャク=ハン国が建てられた。",year: 1236,end: 1242,region: "inner",cat: "事件・戦争",rank: 2,course: ["tankyu"],related: ["バトゥ","ワールシュタットの戦い","キプチャク=ハン国"]},
  {term: "ライプニッツ",yomi: "らいぷにっつ",def: "17〜18世紀のドイツの哲学者・数学者。ニュートンとは別に微分積分法を考案した。哲学では合理論の立場に立ち、世界は無数の単子（モナド）からなるとする単子論をとなえた。",year: 1646,end: 1716,region: "europe",cat: "人物",rank: 2,course: ["tankyu"],related: ["微分積分","ニュートン","合理論"]},
  {term: "ライン同盟",yomi: "らいんどうめい",def: "1806年、ナポレオンの保護のもとで西南ドイツ諸邦が結成した同盟。これにより神聖ローマ帝国は名実ともに消滅した。ナポレオンのロシア遠征失敗後の1813年に解体した。",year: 1806,end: 1813,region: "europe",cat: "組織・運動",rank: 3,course: ["tankyu"],related: ["ナポレオン","神聖ローマ帝国","ナポレオン戦争"]},
  {term: "ラオ人",yomi: "らおじん",def: "東南アジアのメコン川中流域に住む、タイ系の民族。14世紀にランサン王国を建て、上座部仏教を受けいれた。現在のラオスの主要民族である。",region: "sea",cat: "地名・地域",rank: 1,course: ["tankyu"],related: ["ランサン王国","タイ人","上座部仏教"]},
  {term: "ラクスマン",yomi: "らくすまん",def: "ロシアの軍人。1792年、エカチェリーナ2世の命で漂流民の大黒屋光太夫らを送りとどけるため根室に来航し、日本に通商を求めた。幕府は長崎への入港許可証をあたえて退去させた。",year: 1792,region: "europe",cat: "人物",rank: 2,course: ["sogo","tankyu"],related: ["エカチェリーナ2世","大黒屋光太夫","根室"]},
  {term: "ラサ",yomi: "らさ",def: "チベットの中心都市。7世紀に吐蕃のソンツェン=ガンポが都とし、のちチベット仏教の聖地としてダライ=ラマの宮殿ポタラ宮が建てられた。",region: "inner",cat: "地名・地域",rank: 1,course: ["tankyu"],related: ["吐蕃","チベット仏教","ダライ=ラマ"]},
  {term: "ラシード=アッディーン",yomi: "らしーど=あっでぃーん",def: "イル=ハン国のイラン人宰相。ガザン=ハンに仕えて税制改革などをおこなった。ペルシア語でモンゴル帝国を中心とした世界史『集史』を編纂した。",year: 1247,end: 1318,region: "west",cat: "人物",rank: 2,course: ["tankyu"],related: ["イル=ハン国","ガザン=ハン","集史"]},
  {term: "ラタナコーシン朝",yomi: "らたなこーしんちょう",def: "1782年にラーマ1世がバンコクを都として開いたタイの王朝（チャクリ朝）。19世紀にはラーマ5世（チュラロンコン）の近代化政策と英仏間の緩衝地帯という立場により、東南アジアで唯一独立を保った。",year: 1782,region: "sea",cat: "国家・王朝",rank: 3,course: ["sogo","tankyu"],related: ["ラーマ1世","チャクリ改革","バンコク"]},
  {term: "ラッフルズ",yomi: "らっふるず",def: "イギリス東インド会社の植民地行政官。ナポレオン戦争中にジャワを統治し、1819年にシンガポールを買収して自由港とした。シンガポールはのちに海峡植民地の中心となった。",year: 1819,region: "sea",cat: "人物",rank: 2,course: ["tankyu"],related: ["シンガポール","海峡植民地","イギリス東インド会社"]},
  {term: "ラテラノ条約",yomi: "らてらのじょうやく",def: "1929年、ムッソリーニ政権とローマ教皇庁が結んだ条約。ヴァチカン市国の独立を認め、イタリア統一以来の国家と教皇庁の対立（ローマ問題）を解決した。",year: 1929,region: "europe",cat: "条約・宣言",rank: 2,course: ["tankyu"],related: ["ムッソリーニ","ヴァチカン","ローマ教皇"]},
  {term: "ラテンアメリカの独立",yomi: "らてんあめりかのどくりつ",def: "19世紀前半、フランス革命やナポレオン戦争の影響を受けて中南米諸国が独立した動き。ハイチに続き、クリオーリョを中心にボリバルらの指導で多くのスペイン植民地が独立し、ブラジルもポルトガルから独立した。",year: 1804,end: 1830,region: "america",cat: "事件・戦争",rank: 3,course: ["sogo","tankyu"],related: ["シモン=ボリバル","クリオーリョ","ハイチ革命","モンロー教書"]},
  {term: "ラプラタ",yomi: "らぷらた",def: "南アメリカ南東部、ラプラタ川流域の地域。スペインのラプラタ副王領が置かれ、1816年にラプラタ連合州として独立を宣言した。これがのちのアルゼンチンとなり、ウルグアイ・パラグアイも分かれた。",year: 1816,region: "america",cat: "地名・地域",rank: 1,course: ["tankyu"],related: ["アルゼンチン","ラテンアメリカの独立","サン=マルティン"]},
  {term: "ラメセス2世",yomi: "らめせすにせい",def: "エジプト新王国第19王朝の王。シリアをめぐってヒッタイトとカデシュで戦い、のち和平を結んだ。アブ=シンベル神殿など多くの巨大建造物を残した。",year: -1279,end: -1213,region: "west",cat: "人物",rank: 2,course: ["tankyu"],related: ["新王国","ヒッタイト","カデシュの戦い"]},
  {term: "ランジート=シング",yomi: "らんじーと=しんぐ",def: "19世紀初めにパンジャーブ地方でシク王国を建てた王。ラホールを都に強力な軍を築いたが、彼の死後、王国はシク戦争に敗れてイギリスに併合された。",year: 1799,end: 1839,region: "south",cat: "人物",rank: 1,course: ["tankyu"],related: ["シク教","シク王国","シク戦争"]},
  {term: "ランス",yomi: "らんす",def: "フランス北東部の都市。歴代フランス王の戴冠式が行われた大聖堂がある。百年戦争中の1429年、ジャンヌ=ダルクに助けられたシャルル7世がここで戴冠した。",year: 1429,region: "europe",cat: "地名・地域",rank: 1,course: ["tankyu"],related: ["ジャンヌ=ダルク","シャルル7世","百年戦争"]},
  {term: "ラヴェンナ",yomi: "らゔぇんな",def: "イタリア北東部の都市。西ローマ帝国末期や東ゴート王国の都となり、のちビザンツ帝国の総督府が置かれた。ランゴバルド人から奪ったこの地方をピピンが教皇に寄進し、教皇領の起源となった。",region: "europe",cat: "地名・地域",rank: 2,course: ["tankyu"],related: ["西ローマ帝国","東ゴート王国","ラヴェンナ地方","ピピンの寄進"]},
  {term: "ラージプート",yomi: "らーじぷーと",def: "北インドのヒンドゥー教徒の戦士集団。8〜13世紀に諸王国を建て、この時代はラージプート時代とよばれる。ムガル帝国のアクバルは彼らと婚姻関係を結んで支配に取りこんだ。",region: "south",cat: "組織・運動",rank: 2,course: ["tankyu"],related: ["ラージプート時代","ムガル帝国","アクバル","ヒンドゥー教"]},
  {term: "ラーマ1世",yomi: "らーまいっせい",def: "1782年にバンコクを都としてラタナコーシン朝（チャクリ朝）を開いたタイの王。ビルマ（コンバウン朝）の侵攻を防ぎ、王朝の基礎を築いた。",year: 1782,end: 1809,region: "sea",cat: "人物",rank: 1,course: ["tankyu"],related: ["ラタナコーシン朝","バンコク"]},
  {term: "ラームカムヘーン王",yomi: "らーむかむへーんおう",def: "13世紀後半のタイのスコータイ朝の王。周辺に領土を広げ、スリランカから伝わった上座部仏教を保護した。タイ文字を制定したと伝えられ、その事績を刻んだ碑文が残る。",year: 1279,region: "sea",cat: "人物",rank: 1,course: ["tankyu"],related: ["スコータイ朝","タイ文字","上座部仏教"]},
  {term: "リスボン",yomi: "りすぼん",def: "ポルトガルの首都。大航海時代にはアジア貿易の拠点として繁栄し、香辛料の取引でにぎわった。ヴァスコ=ダ=ガマはここからインドへ向けて出航した。",region: "europe",cat: "地名・地域",rank: 1,course: ["tankyu"],related: ["ポルトガル","ヴァスコ=ダ=ガマ","大航海時代"]},
  {term: "リチャード1世",yomi: "りちゃーどいっせい",def: "イングランドのプランタジネット朝の王で「獅子心王」とよばれた。第3回十字軍に参加してサラーフ=アッディーンと戦ったが、イェルサレムは奪回できず講和した。",year: 1189,end: 1199,region: "europe",cat: "人物",rank: 2,course: ["tankyu"],related: ["第3回十字軍","サラーフ=アッディーン","プランタジネット朝"]},
  {term: "リットン調査団",yomi: "りっとんちょうさだん",def: "満州事変について国際連盟が派遣した調査団。1932年に報告書を出し、日本の軍事行動を自衛と認めず満州国も否定した。これにもとづく勧告に反発し、日本は1933年に国際連盟を脱退した。",year: 1932,region: "east",cat: "組織・運動",rank: 3,course: ["sogo","tankyu"],related: ["満州事変","満州国","国際連盟脱退"]},
  {term: "リディア",yomi: "りでぃあ",def: "小アジア西部にあった王国。前7世紀ごろ、世界で最初の金属貨幣をつくったとされる。前6世紀にアケメネス朝のキュロス2世に滅ぼされた。",year: -546,region: "west",cat: "国家・王朝",rank: 2,course: ["tankyu"],related: ["金属貨幣","アケメネス朝","キュロス2世"]},
  {term: "リマ",yomi: "りま",def: "ペルーの首都。インカ帝国を征服したピサロが1535年に建設し、スペインのペルー副王領の首府として南米支配の中心となった。",year: 1535,region: "america",cat: "地名・地域",rank: 1,course: ["tankyu"],related: ["ピサロ","インカ帝国","ペルー副王領"]},
  {term: "リュクルゴスの制",yomi: "りゅくるごすのせい",def: "伝説的な立法者リュクルゴスが定めたとされるスパルタの国制。市民の厳しい軍事的教育と共同生活、貴金属貨幣の禁止などを特色とし、多数の隷属民（ヘイロータイ）を支配した。",region: "europe",cat: "制度・政策",rank: 1,course: ["tankyu"],related: ["スパルタ","ヘイロータイ","ポリス"]},
  {term: "リュケイオン",yomi: "りゅけいおん",def: "アリストテレスが前335年ごろアテネに開いた学園。歩きながら講義したことから、学派は逍遙学派（ペリパトス派）とよばれた。",year: -335,region: "europe",cat: "文化・学問",rank: 1,course: ["tankyu"],related: ["アリストテレス","アカデメイア"]},
  {term: "リヴァプール",yomi: "りゔぁぷーる",def: "イギリス北西部の港市。18世紀に奴隷貿易を含む大西洋三角貿易で栄えた。1830年にマンチェスターとの間に鉄道が開通し、綿工業の原料・製品の輸出入港となった。",region: "europe",cat: "地名・地域",rank: 2,course: ["tankyu"],related: ["大西洋三角貿易","産業革命","マンチェスター"]},
  {term: "リヴィングストン",yomi: "りゔぃんぐすとん",def: "イギリスの宣教師・探検家。アフリカ南部・中部を探検し、ヴィクトリア滝を「発見」した。消息を絶ったのち、スタンリーに発見されたことでも知られる。",year: 1813,end: 1873,region: "africa",cat: "人物",rank: 2,course: ["tankyu"],related: ["スタンリー","ヴィクトリア滝","アフリカ分割"]},
  {term: "リーマン=ショック",yomi: "りーまん=しょっく",def: "2008年、アメリカの大手投資銀行リーマン=ブラザーズが経営破綻したことをきっかけに広がった世界的な金融危機。住宅ローン（サブプライムローン）問題が背景にあり、世界同時不況をまねいた。",year: 2008,region: "america",cat: "事件・戦争",rank: 2,course: ["sogo"],related: ["世界金融危機","グローバル化","ユーロ"]},
  {term: "ルアンダ",yomi: "るあんだ",def: "アフリカ南西部、現在のアンゴラの首都。1576年にポルトガルが建設し、ブラジルなどアメリカ大陸への奴隷貿易の拠点として栄えた。",year: 1576,region: "africa",cat: "地名・地域",rank: 1,course: ["tankyu"],related: ["アンゴラ","奴隷貿易","ポルトガル"]},
  {term: "ルイ14世",yomi: "るいじゅうよんせい",def: "ブルボン朝のフランス王で「太陽王」とよばれた。王権神授説をかかげて絶対王政の全盛期を築き、コルベールに重商主義政策を進めさせた。ヴェルサイユ宮殿を造営し、たびたび侵略戦争をおこなった。",year: 1643,end: 1715,region: "europe",cat: "人物",rank: 3,course: ["tankyu"],related: ["絶対王政","ヴェルサイユ宮殿","コルベール","ナントの王令の廃止"]},
  {term: "ルイジアナ",yomi: "るいじあな",def: "ミシシッピ川流域の広大な地域。17世紀末にフランスが領有し、ルイ14世にちなんで名づけた。七年戦争後に東部はイギリス、西部はスペイン領となり、のちフランスをへてアメリカが買収した。",year: 1682,region: "america",cat: "地名・地域",rank: 2,course: ["tankyu"],related: ["ルイジアナ買収","ヌーヴェル=フランス","フレンチ=インディアン戦争"]},
  {term: "ルイジアナ買収",yomi: "るいじあなばいしゅう",def: "1803年、ジェファソン大統領がナポレオンからミシシッピ川以西のルイジアナを買収したこと。アメリカの領土はほぼ倍増し、西部への拡大が進んだ。",year: 1803,region: "america",cat: "事件・戦争",rank: 2,course: ["tankyu"],related: ["ジェファソン","ナポレオン","西部開拓"]},
  {term: "ルター",yomi: "るたー",def: "ドイツの宗教改革者。1517年に九十五か条の論題を発表して贖宥状の販売を批判し、宗教改革を始めた。信仰によってのみ救われると説き、聖書をドイツ語に翻訳した。",year: 1483,end: 1546,region: "europe",cat: "人物",rank: 3,course: ["sogo","tankyu"],related: ["宗教改革","九十五か条の論題","信仰義認","ヴォルムス帝国議会"]},
  {term: "ルネサンス",yomi: "るねさんす",def: "14〜16世紀にイタリアから西ヨーロッパに広がった文化運動。ギリシア・ローマの古典文化を手本に、人間性を重んじる人文主義を基礎として、美術・文学・科学などで新しい文化を生んだ。",year: 1300,end: 1600,region: "europe",cat: "文化・学問",rank: 3,course: ["sogo","tankyu"],related: ["人文主義","フィレンツェ","メディチ家","レオナルド=ダ=ヴィンチ"]},
  {term: "ルビコン川",yomi: "るびこんがわ",def: "イタリア本土と属州ガリアの境界をなした川。前49年、カエサルは「賽は投げられた」と言ってこの川を軍とともに渡り、ポンペイウスと元老院派との内戦を始めた。",year: -49,region: "europe",cat: "地名・地域",rank: 1,course: ["tankyu"],related: ["カエサル","ポンペイウス","元老院"]},
  {term: "ルムンバ",yomi: "るむんば",def: "コンゴの独立運動指導者。1960年、ベルギー領コンゴが独立すると初代首相となったが、独立直後に起こったコンゴ動乱のなかで失脚し、1961年に殺害された。",year: 1960,region: "africa",cat: "人物",rank: 2,course: ["tankyu"],related: ["コンゴ動乱","アフリカの年","コンゴ民主共和国"]},
  {term: "ルワンダ内戦",yomi: "るわんだないせん",def: "1990年代、ルワンダでフツ人中心の政府とツチ人中心の勢力が争った内戦。1994年には多数のツチ人などが殺害される大量虐殺（ジェノサイド）が起こった。",year: 1990,end: 1994,region: "africa",cat: "事件・戦争",rank: 2,course: ["tankyu"],related: ["民族紛争","フツ人","ツチ人"]},
  {term: "ルーシ",yomi: "るーし",def: "東スラヴ人の地に進出したノルマン人の一派、およびその国家と住民をさす呼び名。9世紀にノヴゴロド国、ついでキエフ公国を建て、のちスラヴ人に同化した。ロシアの名の由来となった。",region: "europe",cat: "国家・王朝",rank: 2,course: ["tankyu"],related: ["ノルマン人","キエフ公国","ノヴゴロド国"]},
  {term: "ルール占領",yomi: "るーるせんりょう",def: "1923年、ドイツの賠償支払いの遅れを理由に、フランスとベルギーがドイツの工業地帯ルール地方を占領したこと。ドイツは消極的抵抗で対抗し、激しいインフレーションが起こった。ドーズ案成立後に撤退した。",year: 1923,end: 1925,region: "europe",cat: "事件・戦争",rank: 3,course: ["sogo","tankyu"],related: ["賠償問題","ドーズ案","インフレーション"]},
  {term: "レオポルド2世",yomi: "れおぽるどにせい",def: "ベルギー国王。スタンリーの探検を援助してコンゴを手に入れ、ベルリン会議で私有地としてのコンゴ自由国を認めさせた。現地住民への苛酷な搾取が国際的に批判され、1908年にベルギー領とされた。",year: 1865,end: 1909,region: "europe",cat: "人物",rank: 2,course: ["tankyu"],related: ["コンゴ自由国","ベルリン会議（1884〜85）","スタンリー","アフリカ分割"]},
  {term: "レコンキスタ",yomi: "れこんきすた",def: "イベリア半島でキリスト教徒がイスラーム勢力から領土を奪回した運動（国土回復運動）。カスティリャ・アラゴンなどが南下し、1492年にナスル朝の都グラナダを陥落させて完了した。",year: 718,end: 1492,region: "europe",cat: "事件・戦争",rank: 3,course: ["tankyu"],related: ["ナスル朝","グラナダ","カスティリャ王国","アラゴン王国"]},
  {term: "レザー=ハーン",yomi: "れざー=はーん",def: "イランの軍人。1921年にクーデタで実権をにぎり、1925年にガージャール朝を廃してパフレヴィー朝を開いた（レザー=シャー）。国号をイランと改め、近代化を進めた。",year: 1925,region: "west",cat: "人物",rank: 2,course: ["tankyu"],related: ["パフレヴィー朝","ガージャール朝","イラン"]},
  {term: "レジスタンス",yomi: "れじすたんす",def: "第二次世界大戦中、ドイツの占領や支配に対して各地で行われた抵抗運動。フランスではロンドンのド=ゴールの自由フランス政府の呼びかけなどにより、国内でも武装抵抗が展開された。",year: 1940,end: 1945,region: "europe",cat: "組織・運動",rank: 2,course: ["sogo","tankyu"],related: ["ド=ゴール","ヴィシー政府","第二次世界大戦"]},
  {term: "レバノン内戦",yomi: "ればのんないせん",def: "1975年から90年まで続いたレバノンの内戦。キリスト教徒とイスラーム教徒など宗派間の対立に、パレスチナ勢力やシリア・イスラエルの介入が加わり長期化した。",year: 1975,end: 1990,region: "west",cat: "事件・戦争",rank: 1,course: ["tankyu"],related: ["宗派","中東戦争","パレスチナ解放機構（PLO）"]},
  {term: "レパントの海戦",yomi: "れぱんとのかいせん",def: "1571年、スペイン・ヴェネツィア・ローマ教皇の連合艦隊がオスマン帝国海軍をギリシア西岸のレパント沖で破った海戦。ただしオスマン帝国の地中海での優位はすぐには崩れなかった。",year: 1571,region: "europe",cat: "事件・戦争",rank: 3,course: ["tankyu"],related: ["フェリペ2世","オスマン帝国","プレヴェザの海戦"]},
  {term: "レヒフェルトの戦い",yomi: "れひふぇるとのたたかい",def: "955年、東フランク王オットー1世が南ドイツのレヒフェルトでマジャール人を破った戦い。この功績などにより、オットーは962年に教皇から皇帝の冠を受けた。",year: 955,region: "europe",cat: "事件・戦争",rank: 2,course: ["tankyu"],related: ["オットー1世","マジャール人","神聖ローマ帝国"]},
  {term: "レーニン",yomi: "れーにん",def: "ロシアの革命家で、ボリシェヴィキの指導者。1917年の十月革命でソヴィエト政権を樹立し、「平和に関する布告」「土地に関する布告」を出した。戦時共産主義やネップを進め、ソ連を成立させた。",year: 1870,end: 1924,region: "europe",cat: "人物",rank: 3,course: ["sogo","tankyu"],related: ["ロシア革命","ボリシェヴィキ","十月革命","平和に関する布告"]},
  {term: "ロシア=トルコ戦争",yomi: "ろしあ=とるこせんそう",def: "1877〜78年、ロシアがスラヴ系民族の保護を口実にオスマン帝国と戦った戦争（露土戦争）。勝利したロシアはサン=ステファノ条約で勢力を広げたが、ベルリン会議で修正された。ルーマニアなどの独立が認められた。",year: 1877,end: 1878,region: "europe",cat: "事件・戦争",rank: 3,course: ["tankyu"],related: ["サン=ステファノ条約","ベルリン会議（1878）","南下政策"]},
  {term: "ロシアの併合",yomi: "ろしあのへいごう",def: "19世紀後半、ロシアが中央アジアに進出し、ウズベク人の国家を支配下においたこと。1876年にはコーカンド=ハン国を滅ぼして併合した。",year: 1876,region: "inner",cat: "事件・戦争",rank: 1,course: ["tankyu"],related: ["コーカンド=ハン国","南下政策","ロシアの進出"]},
  {term: "ロシアの保護国",yomi: "ろしあのほごこく",def: "19世紀後半、ロシアの中央アジア進出により、ブハラ=ハン国（1868年）とヒヴァ=ハン国（1873年）が外交権を失ってロシアの保護国とされたこと。",year: 1868,region: "inner",cat: "制度・政策",rank: 1,course: ["tankyu"],related: ["ブハラ=ハン国","ヒヴァ=ハン国","保護国"]},
  {term: "ロシアの進出",yomi: "ろしあのしんしゅつ",def: "18〜19世紀に進んだロシアの中央アジア・カザフ草原への勢力拡大。カザフ人の諸集団は18世紀以降ロシアに服属し、19世紀にはウズベク人の3ハン国も支配下に入った。",region: "inner",cat: "事件・戦争",rank: 1,course: ["tankyu"],related: ["南下政策","カザフ","ロシアの併合"]},
  {term: "ロシア遠征",yomi: "ろしあえんせい",def: "1812年、大陸封鎖令に従わずイギリスと通商したロシアに対し、ナポレオンが大軍で攻めこんだ遠征。モスクワを占領したものの冬の寒さと補給難で大敗し、ナポレオン没落のきっかけとなった。",year: 1812,region: "europe",cat: "事件・戦争",rank: 3,course: ["sogo","tankyu"],related: ["ナポレオン","大陸封鎖令","諸国民戦争"]},
  {term: "ロシア革命",yomi: "ろしあかくめい",def: "1917年、第一次世界大戦中のロシアで起こった革命。二月革命でロマノフ朝が倒れ、十月革命でレーニンらボリシェヴィキが臨時政府を倒し、世界初の社会主義政権を樹立した。",year: 1917,region: "europe",cat: "事件・戦争",rank: 3,course: ["sogo","tankyu"],related: ["二月革命","十月革命","レーニン","ソヴィエト"]},
  {term: "ロタール",yomi: "ろたーる",def: "カール大帝の孫で、ルートヴィヒ1世の長子。843年のヴェルダン条約で皇帝位と中部フランクを得たが、彼の死後その領土は分割された。",year: 840,end: 855,region: "europe",cat: "人物",rank: 1,course: ["tankyu"],related: ["ヴェルダン条約","フランク王国","中部フランク"]},
  {term: "ロベン島",yomi: "ろべんとう",def: "南アフリカのケープタウン沖にある島。アパルトヘイト時代には政治犯の刑務所が置かれ、反アパルトヘイト運動の指導者マンデラが長く投獄された。",region: "africa",cat: "地名・地域",rank: 1,course: ["sogo","tankyu"],related: ["マンデラ","アパルトヘイト"]},
  {term: "ロマノフ朝",yomi: "ろまのふちょう",def: "1613年にミハイル=ロマノフが開いたロシアの王朝。ピョートル1世やエカチェリーナ2世のもとで大国化したが、1917年の二月革命でニコライ2世が退位して滅んだ。",year: 1613,end: 1917,region: "europe",cat: "国家・王朝",rank: 3,course: ["sogo","tankyu"],related: ["ミハイル=ロマノフ","ピョートル1世","エカチェリーナ2世","ロシア革命"]},
  {term: "ロンドン会議",yomi: "ろんどんかいぎ",def: "1830年、イギリス・フランス・ロシアがロンドンで開いた会議。ギリシアのオスマン帝国からの独立を国際的に承認した。なお1840年にもエジプト問題をめぐるロンドン会議が開かれた。",year: 1830,region: "europe",cat: "事件・戦争",rank: 1,course: ["tankyu"],related: ["ギリシア独立戦争","ムハンマド=アリー"]},
  {term: "ロンバルディア同盟",yomi: "ろんばるでぃあどうめい",def: "1167年、ミラノを中心とする北イタリア諸都市が結んだ都市同盟。神聖ローマ皇帝フリードリヒ1世のイタリア政策に対抗し、1176年にレニャーノの戦いで皇帝軍を破った。",year: 1167,region: "europe",cat: "組織・運動",rank: 2,course: ["tankyu"],related: ["ミラノ","神聖ローマ帝国","イタリア政策"]},
  {term: "ローザ=パークス",yomi: "ろーざ=ぱーくす",def: "アメリカの黒人女性。1955年、アラバマ州モントゴメリーでバスの白人席を譲らなかったため逮捕された。これに抗議するバス=ボイコット運動がキング牧師の指導で起こり、公民権運動が広がった。",year: 1955,region: "america",cat: "人物",rank: 1,course: ["sogo","tankyu"],related: ["キング牧師","公民権運動","バス=ボイコット運動"]},
  {term: "ローザンヌ条約",yomi: "ろーざんぬじょうやく",def: "1923年、トルコとギリシア・連合国との間で結ばれた条約。セーヴル条約にかわり、トルコはイズミルなどの領土を回復し、治外法権の撤廃など主権を回復した。トルコ共和国成立の基礎となった。",year: 1923,region: "west",cat: "条約・宣言",rank: 3,course: ["sogo","tankyu"],related: ["ムスタファ=ケマル","セーヴル条約","トルコ共和国"]},
  {term: "ローザンヌ条約（1912）",yomi: "ろーざんぬじょうやく",def: "1912年、イタリア=トルコ戦争の講和条約。オスマン帝国はリビア（トリポリ・キレナイカ）をイタリアに譲った。ウーシー条約ともよばれる。",year: 1912,region: "africa",cat: "条約・宣言",rank: 1,course: ["tankyu"],related: ["イタリア=トルコ戦争","リビア","オスマン帝国"]},
  {term: "ローデシア",yomi: "ろーでしあ",def: "アフリカ南部の地域。セシル=ローズのイギリス南アフリカ会社が支配し、彼の名をとって名づけられた。南ローデシアは1965年に白人政権が一方的独立を宣言し、1980年にジンバブエとして独立した。",year: 1895,region: "africa",cat: "地名・地域",rank: 2,course: ["tankyu"],related: ["セシル=ローズ","一方的独立宣言","ジンバブエ"]},
  {term: "ローマとの交易",yomi: "ろーまとのこうえき",def: "1〜3世紀ごろ、南インドとローマ帝国の間で季節風を利用して行われた海上交易。インドからは胡椒などの香辛料が運ばれ、南インドからはローマの金貨が多く出土している。",region: "south",cat: "経済・社会",rank: 1,course: ["tankyu"],related: ["季節風貿易","サータヴァーハナ朝","エリュトゥラー海案内記"]},
  {term: "ローマの属州アシア",yomi: "ろーまのぞくしゅうあしあ",def: "前133年、ペルガモン王国の最後の王がローマに国を遺贈したことで成立したローマの属州。小アジア西部を領域とし、豊かな徴税地となった。",year: -133,region: "west",cat: "地名・地域",rank: 1,course: ["tankyu"],related: ["ペルガモン王国","属州"]},
  {term: "ローマの平和",yomi: "ろーまのへいわ",def: "アウグストゥスの即位から五賢帝時代の終わりまで、約200年続いたローマ帝国の繁栄と平和の時代（パクス=ロマーナ）。帝国内の交通・商業が発達し、都市が繁栄した。",year: -27,end: 180,region: "europe",cat: "制度・政策",rank: 3,course: ["tankyu"],related: ["パクス=ロマーナ","アウグストゥス","五賢帝"]},
  {term: "ローマ帝国の東西分裂",yomi: "ろーまていこくのとうざいぶんれつ",def: "395年、テオドシウス帝の死後、ローマ帝国がその2子に分けられ東西に分かれたこと。西ローマ帝国は476年に滅んだが、東ローマ（ビザンツ）帝国は1453年まで続いた。",year: 395,region: "europe",cat: "事件・戦争",rank: 3,course: ["tankyu"],related: ["テオドシウス帝","西ローマ帝国","ビザンツ帝国"]},
  {term: "ローマ教皇",yomi: "ろーまきょうこう",def: "ローマ司教で、ローマ=カトリック教会の最高指導者。ペテロの後継者として首位権を主張し、11〜13世紀には叙任権闘争などを経て、インノケンティウス3世のもとで最盛期をむかえた。",region: "europe",cat: "組織・運動",rank: 3,course: ["tankyu"],related: ["叙任権闘争","カノッサの屈辱","インノケンティウス3世","ローマ=カトリック教会"]},
  {term: "ローマ法",yomi: "ろーまほう",def: "古代ローマで発達した法。十二表法に始まり、市民法から帝国内のすべての人に適用される万民法へと発展した。ユスティニアヌス帝の『ローマ法大全』に集大成され、近代ヨーロッパ法の基礎となった。",region: "europe",cat: "文化・学問",rank: 2,course: ["tankyu"],related: ["十二表法","ローマ法大全","万民法"]},
  {term: "ローマ法大全",yomi: "ろーまほうたいぜん",def: "ビザンツ皇帝ユスティニアヌスが法学者トリボニアヌスらに命じて編纂させた法典。古代ローマ法を集大成したもので、のちのヨーロッパの法学に大きな影響をあたえた。",year: 534,region: "europe",cat: "文化・学問",rank: 3,course: ["tankyu"],related: ["ユスティニアヌス帝","トリボニアヌス","ローマ法"]},
  {term: "ローマ進軍",yomi: "ろーましんぐん",def: "1922年、ムッソリーニがファシスト党員を率いてローマに向かって示威行動をおこなったこと。国王は彼を首相に任命し、ファシスト政権が成立した。",year: 1922,region: "europe",cat: "事件・戦争",rank: 3,course: ["sogo","tankyu"],related: ["ムッソリーニ","ファシスト党","ファシズム"]},
  {term: "ワイタンギ条約",yomi: "わいたんぎじょうやく",def: "1840年、イギリスとニュージーランドの先住民マオリ人の首長たちが結んだ条約。これによりニュージーランドはイギリスの植民地となったが、土地をめぐる解釈の違いがのちの戦争の原因となった。",year: 1840,region: "oceania",cat: "条約・宣言",rank: 2,course: ["tankyu"],related: ["マオリ人","ニュージーランド","イギリス"]},
  {term: "ワイマール共和国",yomi: "わいまーるきょうわこく",def: "ドイツ革命で帝政が倒れた後、1919年に成立したドイツの共和国。民主的なヴァイマル憲法を制定したが、賠償問題や世界恐慌による混乱のなか、1933年にヒトラー政権が成立して事実上消滅した。",year: 1919,end: 1933,region: "europe",cat: "国家・王朝",rank: 3,course: ["sogo","tankyu"],related: ["ヴァイマル憲法","ドイツ革命","ヒトラー"]},
  {term: "ワグナー法",yomi: "わぐなーほう",def: "1935年、ニューディール政策の一環として制定されたアメリカの法律。労働者の団結権と団体交渉権を認め、労働組合の活動を保護した。",year: 1935,region: "america",cat: "制度・政策",rank: 2,course: ["sogo","tankyu"],related: ["ニューディール","フランクリン=ローズヴェルト","産業別組織会議"]},
  {term: "ワシントン会議",yomi: "わしんとんかいぎ",def: "1921〜22年、アメリカの提唱で開かれた国際会議。海軍軍備制限条約・四か国条約・九か国条約が結ばれ、東アジア・太平洋の国際秩序（ワシントン体制）がつくられた。日英同盟は解消された。",year: 1921,end: 1922,region: "america",cat: "事件・戦争",rank: 3,course: ["sogo","tankyu"],related: ["四か国条約","九か国条約","ワシントン海軍軍備制限条約"]},
  {term: "ワシントン大行進",yomi: "わしんとんだいこうしん",def: "1963年、人種差別撤廃を求めて約20万人がワシントンに集まった大規模なデモ。キング牧師が「私には夢がある」と演説し、翌1964年の公民権法成立をうながした。",year: 1963,region: "america",cat: "事件・戦争",rank: 2,course: ["sogo","tankyu"],related: ["キング牧師","公民権運動","公民権法"]},
  {term: "ワット",yomi: "わっと",def: "イギリスの技術者。1769年、ニューコメンの蒸気機関を改良し、効率の高い蒸気機関を開発した。蒸気機関は紡績機などの動力となり、産業革命を大きく進めた。",year: 1736,end: 1819,region: "europe",cat: "人物",rank: 3,course: ["sogo","tankyu"],related: ["蒸気機関","産業革命","ニューコメン"]},
  {term: "ワッハーブ派",yomi: "わっはーぶは",def: "18世紀半ば、イブン=アブドゥル=ワッハーブがアラビア半島で始めたイスラームの改革運動。ムハンマドの時代の純粋なイスラームへの回帰を説き、サウード家と結んでワッハーブ王国を建てた。",year: 1744,region: "west",cat: "思想・宗教",rank: 3,course: ["tankyu"],related: ["イブン=アブドゥル=ワッハーブ","サウード家","ワッハーブ王国","サウジアラビア"]},
  {term: "ワフド党",yomi: "わふどとう",def: "第一次世界大戦後、エジプトの完全独立をめざして結成された民族主義政党。1919年の反英運動を主導し、1922年にエジプトは王国として独立したが、イギリスはスエズ運河地帯の駐兵権などを保持した。",year: 1919,region: "west",cat: "組織・運動",rank: 2,course: ["sogo","tankyu"],related: ["エジプト革命","エジプト王国","民族運動"]},
  {term: "ワルシャワ条約機構",yomi: "わるしゃわじょうやくきこう",def: "1955年、西ドイツの NATO 加盟に対抗して、ソ連と東ヨーロッパ諸国が結成した軍事同盟。冷戦終結後の1991年に解体した。",year: 1955,end: 1991,region: "europe",cat: "組織・運動",rank: 3,course: ["sogo","tankyu"],related: ["北大西洋条約機構（NATO）","冷戦","東ドイツ"]},
  {term: "ワレサ",yomi: "われさ",def: "ポーランドの労働運動指導者。1980年に自主管理労組「連帯」を結成して議長となった。1989年の東欧革命の流れのなかで、1990年に大統領に就任した。",year: 1980,region: "europe",cat: "人物",rank: 2,course: ["sogo","tankyu"],related: ["連帯","ポーランド","東欧革命"]},
  {term: "ワーテルローの戦い",yomi: "わーてるろーのたたかい",def: "1815年、エルバ島を脱出して皇帝に復位したナポレオンが、ベルギーのワーテルローでイギリス・プロイセン連合軍に敗れた戦い。百日天下は終わり、ナポレオンはセントヘレナ島に流された。",year: 1815,region: "europe",cat: "事件・戦争",rank: 3,course: ["sogo","tankyu"],related: ["ナポレオン","百日天下","ウィーン会議"]},
  {term: "ワールシュタットの戦い",yomi: "わーるしゅたっとのたたかい",def: "1241年、バトゥ率いるモンゴル軍がシュレジエンのワールシュタット（リーグニッツ）でドイツ・ポーランド連合軍を破った戦い。ヨーロッパに大きな衝撃をあたえた。",year: 1241,region: "europe",cat: "事件・戦争",rank: 3,course: ["tankyu"],related: ["バトゥ","ヨーロッパ遠征","モンゴル帝国"]},
  {term: "ヴァイキング",yomi: "ゔぁいきんぐ",def: "8〜11世紀にスカンディナヴィアなどからヨーロッパ各地に進出したノルマン人の呼び名。交易と略奪をおこない、ノルマンディー公国・ノヴゴロド国などを建てた。",year: 800,end: 1100,region: "europe",cat: "組織・運動",rank: 2,course: ["tankyu"],related: ["ノルマン人","ノルマンディー公国","ルーシ"]},
  {term: "ヴァイマル憲法",yomi: "ゔぁいまるけんぽう",def: "1919年、ドイツのヴァイマルで開かれた国民議会で制定された憲法。男女普通選挙と生存権などの社会権を保障し、当時もっとも民主的な憲法とされたが、大統領緊急令の規定がナチスに利用された。",year: 1919,region: "europe",cat: "条約・宣言",rank: 3,course: ["sogo","tankyu"],related: ["ワイマール共和国","社会権","男女普通選挙"]},
  {term: "ヴァスコ=ダ=ガマ",yomi: "ゔぁすこ=だ=がま",def: "ポルトガルの航海者。1497年にリスボンを出航し、喜望峰を回って1498年にインド西岸のカリカットに到達した。ヨーロッパからアジアへ直接向かうインド航路を開いた。",year: 1498,region: "europe",cat: "人物",rank: 3,course: ["sogo","tankyu"],related: ["喜望峰","カリカット","インド航路","大航海時代"]},
  {term: "ヴァチカン",yomi: "ゔぁちかん",def: "ローマ市内にあるローマ教皇の居住地。1929年のラテラノ条約でヴァチカン市国として独立が認められた。世界最小の国家で、カトリック教会の中心である。",year: 1929,region: "europe",cat: "地名・地域",rank: 1,course: ["tankyu"],related: ["ローマ教皇","ラテラノ条約","サン=ピエトロ大聖堂"]},
  {term: "ヴァルガス",yomi: "ゔぁるがす",def: "ブラジルの政治家。世界恐慌後の1930年に革命で政権をにぎり、独裁的な「新国家」体制のもとで工業化と労働者保護を進めた。",year: 1930,end: 1954,region: "america",cat: "人物",rank: 1,course: ["tankyu"],related: ["ブラジル","ポピュリズム","世界恐慌"]},
  {term: "ヴァルダナ朝",yomi: "ゔぁるだなちょう",def: "7世紀前半、ハルシャ=ヴァルダナが北インドに建てた王朝。仏教を保護し、玄奘が訪れてナーランダー僧院で学んだ。王の死後まもなく分裂した。",year: 606,end: 647,region: "south",cat: "国家・王朝",rank: 3,course: ["tankyu"],related: ["ハルシャ=ヴァルダナ","玄奘","ナーランダー僧院"]},
  {term: "ヴァルナ制",yomi: "ゔぁるなせい",def: "アーリヤ人がつくった身分制度。バラモン（司祭）・クシャトリヤ（武士）・ヴァイシャ（農民・商人）・シュードラ（隷属民）の4つの身分からなる。のちジャーティと結びついてカースト制度となった。",year: -1000,region: "south",cat: "制度・政策",rank: 3,course: ["tankyu"],related: ["バラモン","クシャトリヤ","カースト制度","アーリヤ人"]},
  {term: "ヴァルナ制の否定",yomi: "ゔぁるなせいのひてい",def: "前5世紀ごろ、仏教を開いたガウタマ=シッダールタやジャイナ教のヴァルダマーナが、バラモンの権威とヴァルナによる差別を否定したこと。クシャトリヤやヴァイシャの支持を得た。",region: "south",cat: "思想・宗教",rank: 1,course: ["tankyu"],related: ["ガウタマ=シッダールタ","仏教","ジャイナ教"]},
  {term: "ヴァレンヌ逃亡事件",yomi: "ゔぁれんぬとうぼうじけん",def: "1791年、ルイ16世と王妃マリ=アントワネットが王妃の実家オーストリアへの逃亡をはかり、国境近くのヴァレンヌで捕らえられた事件。国王への信頼は失われ、共和政を求める声が強まった。",year: 1791,region: "europe",cat: "事件・戦争",rank: 3,course: ["sogo","tankyu"],related: ["ルイ16世","フランス革命","立法議会"]},
  {term: "ヴァンダル王国",yomi: "ゔぁんだるおうこく",def: "ゲルマン人のヴァンダル人が北アフリカのカルタゴの故地に建てた王国。ローマを略奪したこともあったが、534年にビザンツ皇帝ユスティニアヌスに滅ぼされた。",year: 429,end: 534,region: "africa",cat: "国家・王朝",rank: 2,course: ["tankyu"],related: ["ゲルマン人の大移動","ユスティニアヌス帝","カルタゴ"]},
  {term: "ヴァージニア",yomi: "ゔぁーじにあ",def: "1607年、ジェームズタウン建設に始まる北アメリカ最初のイギリス植民地。黒人奴隷を使ったタバコのプランテーションで栄え、1619年には植民地議会が開かれた。13植民地のひとつ。",year: 1607,region: "america",cat: "地名・地域",rank: 2,course: ["sogo","tankyu"],related: ["13植民地","ジェームズタウン","タバコ"]},
  {term: "ヴィクトリア女王",yomi: "ゔぃくとりあじょおう",def: "イギリスの女王。在位中にイギリスは「世界の工場」として繁栄し、二大政党による議会政治が発達した。1877年にはインド皇帝を兼ね、大英帝国の最盛期を象徴する君主となった。",year: 1837,end: 1901,region: "europe",cat: "人物",rank: 3,course: ["sogo","tankyu"],related: ["ヴィクトリア時代","大英帝国","インド帝国","万国博覧会"]},
  {term: "ヴィクトリア時代",yomi: "ゔぃくとりあじだい",def: "ヴィクトリア女王が在位した1837〜1901年の時代。イギリスは工業力と海軍力で世界に君臨し（パクス=ブリタニカ）、自由主義的改革や二大政党制が進んだ。",year: 1837,end: 1901,region: "europe",cat: "経済・社会",rank: 2,course: ["sogo","tankyu"],related: ["ヴィクトリア女王","世界の工場","パクス=ブリタニカ"]},
  {term: "ヴィクトリア滝",yomi: "ゔぃくとりあたき",def: "アフリカ南部、ザンベジ川にある大きな滝。1855年、ヨーロッパ人としてはじめてリヴィングストンが到達し、ヴィクトリア女王にちなんで名づけた。",year: 1855,region: "africa",cat: "地名・地域",rank: 1,course: ["tankyu"],related: ["リヴィングストン","ザンベジ川"]},
  {term: "ヴィシー政府",yomi: "ゔぃしーせいふ",def: "1940年、フランスがドイツに降伏した後、ペタンを首班としてフランス中部のヴィシーに成立した政府。ドイツに協力的で、1944年の連合軍によるパリ解放で崩壊した。",year: 1940,end: 1944,region: "europe",cat: "国家・王朝",rank: 2,course: ["sogo","tankyu"],related: ["ペタン","ド=ゴール","レジスタンス"]},
  {term: "ヴィジャヤナガル王国",yomi: "ゔぃじゃやながるおうこく",def: "14世紀前半、南インドに成立したヒンドゥー教国。北のイスラーム勢力と争いながら、インド洋交易で栄えた。1565年にデカンのイスラーム諸国連合に大敗し、衰退した。",year: 1336,end: 1649,region: "south",cat: "国家・王朝",rank: 2,course: ["tankyu"],related: ["バフマニー朝","ヒンドゥー教","南インド"]},
  {term: "ヴィットーリオ=エマヌエーレ2世",yomi: "ゔぃっとーりお=えまぬえーれにせい",def: "サルデーニャ国王。首相カヴールのもとでイタリア統一を進め、ガリバルディから南イタリアを献上されて、1861年にイタリア王国の初代国王となった。",year: 1849,end: 1878,region: "europe",cat: "人物",rank: 3,course: ["sogo","tankyu"],related: ["サルデーニャ王国","カヴール","ガリバルディ","イタリア王国"]},
  {term: "ヴィルヘルム1世",yomi: "ゔぃるへるむいっせい",def: "プロイセン王。ビスマルクを首相に起用して鉄血政策を進めた。プロイセン=フランス戦争中の1871年、ヴェルサイユ宮殿でドイツ皇帝に即位し、ドイツ帝国が成立した。",year: 1861,end: 1888,region: "europe",cat: "人物",rank: 3,course: ["sogo","tankyu"],related: ["ビスマルク","ドイツ帝国","プロイセン=フランス戦争"]},
  {term: "ヴィルヘルム2世",yomi: "ゔぃるへるむにせい",def: "ドイツ皇帝。1890年にビスマルクを辞職させ、「世界政策」をかかげて海軍の大拡張や植民地拡大を進め、英・仏・露との対立を深めた。第一次世界大戦末期のドイツ革命で退位し、オランダに亡命した。",year: 1888,end: 1918,region: "europe",cat: "人物",rank: 3,course: ["sogo","tankyu"],related: ["世界政策","ビスマルク","第一次世界大戦","3B政策"]},
  {term: "ヴェネツィア",yomi: "ゔぇねつぃあ",def: "北イタリアの港市・都市共和国。東方貿易（レヴァント貿易）で繁栄し、第4回十字軍を利用してコンスタンティノープルを占領させ、商業上の利益を得た。ルネサンス文化も栄えた。",region: "europe",cat: "地名・地域",rank: 3,course: ["tankyu"],related: ["東方貿易","第4回十字軍","北イタリア都市","ルネサンス"]},
  {term: "ヴェルサイユ宮殿",yomi: "ゔぇるさいゆきゅうでん",def: "ルイ14世がパリ郊外に造営した宮殿。バロック様式の代表的建築で、絶対王政の権威を示した。1871年にドイツ帝国成立の宣言、1919年にヴェルサイユ条約の調印がここで行われた。",year: 1682,region: "europe",cat: "文化・学問",rank: 3,course: ["tankyu"],related: ["ルイ14世","バロック様式","絶対王政"]},
  {term: "ヴェルサイユ条約",yomi: "ゔぇるさいゆじょうやく",def: "1919年、パリ講和会議の結果、連合国とドイツが結んだ講和条約。ドイツはすべての海外植民地を失い、アルザス・ロレーヌの返還、軍備制限、巨額の賠償を課された。国際連盟の設立も定めた。",year: 1919,region: "europe",cat: "条約・宣言",rank: 3,course: ["sogo","tankyu"],related: ["パリ講和会議","ヴェルサイユ体制","国際連盟","委任統治"]},
  {term: "ヴェルダン条約",yomi: "ゔぇるだんじょうやく",def: "843年、ルートヴィヒ1世の死後、3人の子がフランク王国を3分した条約。東フランク・西フランク・中部フランクに分かれ、870年のメルセン条約と合わせて、ドイツ・フランス・イタリアの原形ができた。",year: 843,region: "europe",cat: "条約・宣言",rank: 3,course: ["tankyu"],related: ["フランク王国","メルセン条約","ロタール"]},
  {term: "ヴォルムス帝国議会",yomi: "ゔぉるむすていこくぎかい",def: "1521年、神聖ローマ皇帝カール5世がヴォルムスで開いた帝国議会。ルターを召喚して自説の撤回を求めたが、ルターは拒否したため帝国追放処分となった。ザクセン選帝侯がルターを保護した。",year: 1521,region: "europe",cat: "事件・戦争",rank: 2,course: ["tankyu"],related: ["ルター","カール5世","宗教改革"]},
  {term: "一世一元の制",yomi: "いっせいいちげんのせい",def: "皇帝一代の間に元号を一つだけ用いる制度。明の洪武帝が始め、清にも受けつがれた。このため明・清の皇帝は元号で「洪武帝」のようによばれる。日本でも明治維新の際に採用された。",year: 1368,region: "east",cat: "制度・政策",rank: 2,course: ["tankyu"],related: ["洪武帝","明","元号"]},
  {term: "一党独裁",yomi: "いっとうどくさい",def: "ひとつの政党が国家権力を独占し、他の政党を認めない政治体制。イタリアのファシスト党、ドイツのナチ党、ソ連の共産党などがその例で、言論・結社の自由はきびしく制限された。",region: "europe",cat: "制度・政策",rank: 2,course: ["sogo","tankyu"],related: ["ファシズム","ムッソリーニ","ナチス","全体主義"]},
  {term: "一国二制度",yomi: "いっこくにせいど",def: "鄧小平が示した、一つの国家のなかで社会主義と資本主義の二つの制度の共存を認める方式。1997年の香港返還、1999年のマカオ返還の際に適用され、高度な自治が約束された。",year: 1997,region: "east",cat: "制度・政策",rank: 3,course: ["sogo","tankyu"],related: ["鄧小平","香港返還","マカオ"]},
  {term: "一国社会主義",yomi: "いっこくしゃかいしゅぎ",def: "ソ連一国だけでも社会主義の建設は可能であるとする考え方。スターリンがとなえ、世界革命論のトロツキーと対立した。スターリンが勝利し、五か年計画による工業化が進められた。",year: 1924,region: "europe",cat: "思想・宗教",rank: 2,course: ["tankyu"],related: ["スターリン","トロツキー","世界革命論","五か年計画"]},
  {term: "一国社会主義論",yomi: "いっこくしゃかいしゅぎろん",def: "ソ連一国で社会主義建設が可能であるとするスターリンの理論。トロツキーの世界革命論と対立し、レーニン死後の権力闘争でスターリンが勝利する根拠となった。",year: 1924,region: "europe",cat: "思想・宗教",rank: 1,course: ["tankyu"],related: ["スターリン","一国社会主義","世界革命論"]},
  {term: "一方的独立宣言",yomi: "いっぽうてきどくりつせんげん",def: "1965年、南ローデシアの白人少数派政権がイギリスの同意なしに独立を宣言したこと。国際的な経済制裁や黒人勢力の武装闘争を受け、1980年に黒人多数支配のジンバブエとして独立した。",year: 1965,region: "africa",cat: "事件・戦争",rank: 1,course: ["tankyu"],related: ["ローデシア","白人政権","ジンバブエ"]},
  {term: "一条鞭法",yomi: "いちじょうべんぽう",def: "明代後半に普及した税制。土地税や丁税（人頭税）などの諸税・徭役を一本化して銀で納めさせた。日本銀やメキシコ銀の流入が背景にあり、清代の地丁銀制に受けつがれた。",year: 1581,region: "east",cat: "制度・政策",rank: 3,course: ["tankyu"],related: ["明","地丁銀制","銀"]},
  {term: "一次資料",yomi: "いちじしりょう",def: "調べようとする出来事の当事者や同時代の人が残した資料。日記・手紙・公文書・新聞などをさす。歴史を考えるときには、だれが何のために作ったかを考えて読みとる必要がある。",region: "europe",cat: "文化・学問",rank: 1,course: ["sogo"],related: ["二次資料","史料批判"]},
  {term: "一般意志",yomi: "いっぱんいし",def: "ルソーが『社会契約論』で説いた、社会全体の共通の利益をめざす意志。個人の利益の総和とは区別され、主権はこの一般意志に存するとして人民主権を主張した。",year: 1762,region: "europe",cat: "思想・宗教",rank: 2,course: ["tankyu"],related: ["ルソー","社会契約論","人民主権"]},
  {term: "丁朝",yomi: "ていちょう",def: "10世紀後半、丁部領がベトナム北部に建てた王朝。国号を大瞿越とし、中国からの自立を確かなものにした。短命に終わり、前黎朝にかわられた。",year: 968,end: 980,region: "sea",cat: "国家・王朝",rank: 1,course: ["tankyu"],related: ["大越","中国からの独立","李朝"]},
  {term: "七年戦争",yomi: "しちねんせんそう",def: "1756〜63年、シュレジエンの奪回をはかるオーストリアがフランス・ロシアと結んでプロイセンと戦った戦争。イギリスはプロイセンを支援し、北アメリカやインドでもフランスと戦って勝利した。",year: 1756,end: 1763,region: "europe",cat: "事件・戦争",rank: 3,course: ["tankyu"],related: ["外交革命","フリードリヒ2世","マリア=テレジア","フレンチ=インディアン戦争"]},
  {term: "七月革命",yomi: "しちがつかくめい",def: "1830年、フランスでシャルル10世の反動政治に対しパリ民衆が蜂起した革命。ブルボン朝は倒れ、ルイ=フィリップが王となって七月王政が成立した。影響でベルギーが独立した。",year: 1830,region: "europe",cat: "事件・戦争",rank: 3,course: ["tankyu"],related: ["シャルル10世","ルイ=フィリップ","七月王政","ベルギー独立"]},
  {term: "万国博覧会",yomi: "ばんこくはくらんかい",def: "各国の産業・技術・文化の成果を展示する国際博覧会。1851年、ヴィクトリア時代のロンドンで第1回が開かれ、水晶宮（クリスタル=パレス）でイギリスの工業力を示した。",year: 1851,region: "europe",cat: "文化・学問",rank: 2,course: ["sogo","tankyu"],related: ["ヴィクトリア女王","世界の工場","水晶宮"]},
  {term: "万学の祖",yomi: "ばんがくのそ",def: "古代ギリシアの哲学者アリストテレスの呼び名。哲学・論理学・政治学・自然科学など幅広い学問を体系化したことからこうよばれる。",region: "europe",cat: "人物",rank: 1,course: ["tankyu"],related: ["アリストテレス","リュケイオン"]},
  {term: "万有引力の法則",yomi: "ばんゆういんりょくのほうそく",def: "ニュートンが著書『プリンキピア』で発表した、すべての物体は互いに引き合うという法則。天体の運動と地上の物体の運動を統一的に説明し、近代物理学の基礎となった。",year: 1687,region: "europe",cat: "文化・学問",rank: 3,course: ["tankyu"],related: ["ニュートン","プリンキピア","科学革命"]},
  {term: "万能の人",yomi: "ばんのうのひと",def: "ルネサンス期の理想的人間像。絵画・建築・科学・技術など多くの分野にすぐれた人をさし、レオナルド=ダ=ヴィンチがその代表とされる。",region: "europe",cat: "文化・学問",rank: 1,course: ["tankyu"],related: ["レオナルド=ダ=ヴィンチ","ルネサンス","万能人"]},
  {term: "万能人",yomi: "ばんのうじん",def: "ルネサンス期に理想とされた、多方面にすぐれた才能をもつ人。絵画・建築・解剖学・工学などに業績を残したレオナルド=ダ=ヴィンチやアルベルティが代表とされる。",region: "europe",cat: "文化・学問",rank: 1,course: ["tankyu"],related: ["レオナルド=ダ=ヴィンチ","ルネサンス","万能の人"]},
  {term: "万里の長城",yomi: "ばんりのちょうじょう",def: "北方の遊牧民の侵入を防ぐために築かれた長大な城壁。戦国諸国の長城を秦の始皇帝が修築・連結して匈奴に備えた。現在残るものの多くは明代に築かれた。",year: -214,region: "east",cat: "文化・学問",rank: 3,course: ["sogo","tankyu"],related: ["始皇帝","匈奴","明"]},
  {term: "三・一独立運動",yomi: "さん・いちどくりつうんどう",def: "1919年3月1日、ソウルで「独立万歳」を叫んで始まった朝鮮の独立運動。民族自決の風潮を背景に朝鮮全土に広がったが、日本は軍隊などで鎮圧した。その後、朝鮮総督府は「文化政治」に転換した。",year: 1919,region: "east",cat: "事件・戦争",rank: 3,course: ["sogo","tankyu"],related: ["民族自決","五・四運動","朝鮮総督府"]},
  {term: "三位一体説",yomi: "さんみいったいせつ",def: "父なる神・子なるイエス・聖霊は一体であるとするキリスト教の教義。ニケーア公会議でアタナシウス派の説が正統とされ、のちに三位一体説として確立した。",year: 325,region: "europe",cat: "思想・宗教",rank: 3,course: ["tankyu"],related: ["ニケーア公会議","アタナシウス派","アリウス派"]},
  {term: "三十年戦争",yomi: "さんじゅうねんせんそう",def: "1618〜48年、ベーメンの新教徒の反乱から始まったドイツの宗教戦争。デンマーク・スウェーデン・フランスなどが介入して国際戦争となり、ウェストファリア条約で終結した。ドイツは荒廃した。",year: 1618,end: 1648,region: "europe",cat: "事件・戦争",rank: 3,course: ["tankyu"],related: ["ウェストファリア条約","ベーメン","グスタフ=アドルフ","主権国家"]},
  {term: "三国協商",yomi: "さんごくきょうしょう",def: "露仏同盟・英仏協商・英露協商によって成立したイギリス・フランス・ロシアの協力関係。ドイツ中心の三国同盟と対立し、第一次世界大戦の対立構図となった。",year: 1907,region: "europe",cat: "条約・宣言",rank: 3,course: ["sogo","tankyu"],related: ["露仏同盟","英仏協商","英露協商","三国同盟"]},
  {term: "三国同盟",yomi: "さんごくどうめい",def: "1882年、ビスマルクの外交によって結ばれたドイツ・オーストリア・イタリアの同盟。三国協商と対立したが、イタリアは未回収地をめぐりオーストリアと対立し、第一次世界大戦では協商国側で参戦した。",year: 1882,region: "europe",cat: "条約・宣言",rank: 3,course: ["sogo","tankyu"],related: ["ビスマルク","三国協商","第一次世界大戦"]},
  {term: "三国干渉",yomi: "さんごくかんしょう",def: "1895年、下関条約で日本が得た遼東半島について、ロシア・ドイツ・フランスが清への返還を要求したこと。日本はこれを受けいれ、のちロシアとの対立を深めた。",year: 1895,region: "east",cat: "事件・戦争",rank: 3,course: ["sogo","tankyu"],related: ["下関条約","遼東半島","日清戦争"]},
  {term: "三国時代",yomi: "さんごくじだい",def: "後漢滅亡後、中国が魏・蜀・呉の3国に分かれて争った時代。華北の魏、四川の蜀、江南の呉が並びたったが、263年に魏が蜀を滅ぼし、280年に晋（西晋）が呉を滅ぼして統一した。",year: 220,end: 280,region: "east",cat: "国家・王朝",rank: 3,course: ["tankyu"],related: ["魏","蜀","呉","赤壁の戦い"]},
  {term: "三国時代（朝鮮）",yomi: "さんごくじだい",def: "4世紀から7世紀後半まで、朝鮮半島で高句麗・百済・新羅の3国が争った時代。新羅が唐と結んで百済・高句麗を滅ぼし、676年に半島を統一した。",year: 313,end: 676,region: "east",cat: "国家・王朝",rank: 2,course: ["tankyu"],related: ["高句麗","百済","新羅"]},
  {term: "三月革命",yomi: "さんがつかくめい",def: "1848年、フランスの二月革命の影響を受けてウィーンとベルリンで起こった革命。ウィーンではメッテルニヒが失脚し、ウィーン体制は崩壊した。ドイツではフランクフルト国民議会が開かれた。",year: 1848,region: "europe",cat: "事件・戦争",rank: 3,course: ["tankyu"],related: ["二月革命","メッテルニヒ","フランクフルト国民議会","諸国民の春"]},
  {term: "三権分立",yomi: "さんけんぶんりつ",def: "国家権力を立法・行政・司法の3つに分け、互いに抑制させて権力の濫用を防ぐ考え方。モンテスキューが『法の精神』でとなえ、アメリカ合衆国憲法などに取りいれられた。",year: 1748,region: "europe",cat: "思想・宗教",rank: 3,course: ["sogo","tankyu"],related: ["モンテスキュー","法の精神","合衆国憲法"]},
  {term: "三民主義",yomi: "さんみんしゅぎ",def: "孫文がとなえた中国革命の基本理念。民族の独立、民権の伸長、民生の安定の三つからなる。中国同盟会の綱領となり、のち中国国民党に受けつがれた。",year: 1905,region: "east",cat: "思想・宗教",rank: 3,course: ["sogo","tankyu"],related: ["孫文","中国同盟会","辛亥革命"]},
  {term: "三省六部",yomi: "さんしょうりくぶ",def: "唐の中央官制。詔勅を起草する中書省、審議する門下省、執行する尚書省の三省と、尚書省のもとで行政を分担する吏・戸・礼・兵・刑・工の六部からなる。",region: "east",cat: "制度・政策",rank: 2,course: ["tankyu"],related: ["唐","律令","中書省","門下省"]},
  {term: "三藩の乱",yomi: "さんぱんのらん",def: "1673年、清の康熙帝による藩の廃止に反発して、呉三桂ら漢人の3藩王が起こした反乱。康熙帝はこれを鎮圧し、さらに1683年に台湾の鄭氏を降して中国統一を完成させた。",year: 1673,end: 1681,region: "east",cat: "事件・戦争",rank: 3,course: ["tankyu"],related: ["康熙帝","呉三桂","台湾"]},
  {term: "三角貿易",yomi: "さんかくぼうえき",def: "19世紀にイギリスがおこなった、イギリス・インド・清を結ぶ貿易。イギリスの綿製品をインドへ、インド産アヘンを清へ、清の茶をイギリスへ運んだ。清から銀が流出し、アヘン戦争の原因となった。",region: "east",cat: "経済・社会",rank: 3,course: ["sogo","tankyu"],related: ["アヘン","アヘン戦争","イギリス東インド会社"]},
  {term: "三部会",yomi: "さんぶかい",def: "フランスの身分制議会。聖職者・貴族・平民の代表からなり、1302年にフィリップ4世が教皇との対立に際して招集した。1615年以後中断し、1789年にルイ16世が再招集したことが革命の発端となった。",year: 1302,region: "europe",cat: "組織・運動",rank: 3,course: ["tankyu"],related: ["フィリップ4世","ルイ16世","国民議会"]},
  {term: "上京竜泉府",yomi: "じょうけいりゅうせんふ",def: "渤海の都。現在の中国黒竜江省にあり、唐の長安にならった碁盤目状の都市計画でつくられた。唐の文化を取りいれて栄えた渤海は「海東の盛国」とよばれた。",region: "east",cat: "地名・地域",rank: 1,course: ["tankyu"],related: ["渤海","長安"]},
  {term: "上帝会",yomi: "じょうていかい",def: "洪秀全がキリスト教の影響を受けて組織した宗教結社（拝上帝会）。広西省で信者を集め、1851年に太平天国を建てて清に対して挙兵した。",year: 1843,region: "east",cat: "組織・運動",rank: 2,course: ["tankyu"],related: ["洪秀全","太平天国","キリスト教"]},
  {term: "上座部仏教",yomi: "じょうざぶぶっきょう",def: "出家者自身の修行による救済を重んじる仏教。スリランカから東南アジアに伝わり、ビルマ・タイ・カンボジアなどで広く信仰された。大乗仏教側からは小乗仏教とよばれた。",region: "south",cat: "思想・宗教",rank: 3,course: ["tankyu"],related: ["大乗仏教","スリランカ","パガン朝","タイ"]},
  {term: "上海クーデタ",yomi: "しゃんはいくーでた",def: "1927年、北伐中の蔣介石が上海で共産党員や労働者を弾圧した事件。これにより第1次国共合作は崩壊し、蔣介石は南京に国民政府を建てた。",year: 1927,region: "east",cat: "事件・戦争",rank: 3,course: ["sogo","tankyu"],related: ["蔣介石","国共合作","北伐","南京国民政府"]},
  {term: "下関条約",yomi: "しものせきじょうやく",def: "1895年、日清戦争の講和条約。清は朝鮮の独立を認め、遼東半島・台湾・澎湖諸島を日本に割譲し、賠償金を支払った。遼東半島は三国干渉により返還された。",year: 1895,region: "east",cat: "条約・宣言",rank: 3,course: ["sogo","tankyu"],related: ["日清戦争","三国干渉","台湾総督府","伊藤博文"]},
  {term: "不平等条約",yomi: "ふびょうどうじょうやく",def: "欧米諸国がアジア諸国に結ばせた、相手国に不利な内容の条約。領事裁判権の承認や関税自主権の喪失、片務的最恵国待遇などをふくむ。清の南京条約や日本の安政の五か国条約などがある。",region: "east",cat: "条約・宣言",rank: 3,course: ["sogo","tankyu"],related: ["南京条約","日米修好通商条約","領事裁判権","関税自主権"]},
  {term: "不戦条約",yomi: "ふせんじょうやく",def: "1928年、アメリカのケロッグ国務長官とフランスのブリアン外相の提唱で結ばれた条約。国際紛争を解決する手段として戦争を放棄することを約束したが、違反への制裁規定はなかった。",year: 1928,region: "europe",cat: "条約・宣言",rank: 3,course: ["sogo","tankyu"],related: ["ケロッグ","ブリアン","国際協調","国際連盟"]},
  {term: "世界の半分",yomi: "せかいのはんぶん",def: "サファヴィー朝のアッバース1世が都としたイスファハーンの繁栄をたたえたことば。「イスファハーンは世界の半分」とよばれ、イマームのモスクなどが建てられた。",year: 1598,region: "west",cat: "地名・地域",rank: 1,course: ["tankyu"],related: ["アッバース1世","イスファハーン","サファヴィー朝"]},
  {term: "世界の工場",yomi: "せかいのこうじょう",def: "産業革命をいち早く達成し、19世紀に工業製品を世界中に供給したイギリスの呼び名。19世紀後半にはアメリカ・ドイツが急速に追い上げた。",region: "europe",cat: "経済・社会",rank: 3,course: ["sogo","tankyu"],related: ["産業革命","ヴィクトリア時代","パクス=ブリタニカ"]},
  {term: "世界の記述（東方見聞録）",yomi: "せかいのきじゅつ",def: "ヴェネツィア商人マルコ=ポーロが、元のクビライに仕えた体験などを口述した旅行記。中国を「黄金の国ジパング」を含めてヨーロッパに紹介し、のちの大航海時代の関心を高めた。",year: 1298,region: "east",cat: "文化・学問",rank: 3,course: ["tankyu"],related: ["マルコ=ポーロ","クビライ","大都"]},
  {term: "世界人権宣言",yomi: "せかいじんけんせんげん",def: "1948年、国際連合総会で採択された宣言。すべての人の基本的人権と自由を国際的に尊重すべき基準として示した。法的拘束力はなく、のちに国際人権規約として条約化された。",year: 1948,region: "europe",cat: "条約・宣言",rank: 3,course: ["sogo","tankyu"],related: ["国際連合","人権宣言","国際人権規約"]},
  {term: "世界周航",yomi: "せかいしゅうこう",def: "1519〜22年、マゼランの率いるスペイン艦隊が成し遂げた初の世界一周航海。マゼランはフィリピンで戦死したが、部下がスペインに帰還し、地球が丸いことを実証した。",year: 1519,end: 1522,region: "europe",cat: "事件・戦争",rank: 3,course: ["sogo","tankyu"],related: ["マゼラン","大航海時代","太平洋"]},
  {term: "世界市場",yomi: "せかいしじょう",def: "世界各地が商品・資本の取引で結ばれた市場。大航海時代以降に形成が進み、産業革命後には工業国と原料・食料供給地域との国際分業による世界経済が成立した。",region: "europe",cat: "経済・社会",rank: 2,course: ["tankyu"],related: ["大西洋三角貿易","国際分業","産業革命"]},
  {term: "世界恐慌",yomi: "せかいきょうこう",def: "1929年、ニューヨークのウォール街での株価暴落から始まり、世界中に広がった大不況。企業倒産と大量の失業が生じ、アメリカのニューディール、英仏のブロック経済、ドイツのナチス台頭などをまねいた。",year: 1929,region: "america",cat: "事件・戦争",rank: 3,course: ["sogo","tankyu"],related: ["ニューディール","ブロック経済","ファシズム"]},
  {term: "世界政策",yomi: "せかいせいさく",def: "1890年代以降、ドイツ皇帝ヴィルヘルム2世が進めた帝国主義的な対外膨張政策。海軍の大拡張や3B政策などでイギリスとの対立を深め、三国協商の形成をまねいた。",year: 1890,region: "europe",cat: "制度・政策",rank: 3,course: ["tankyu"],related: ["ヴィルヘルム2世","3B政策","建艦競争"]},
  {term: "世界革命論",yomi: "せかいかくめいろん",def: "社会主義革命はロシア一国では完成せず、先進国の革命と結びつけて世界的に進める必要があるとするトロツキーの考え（永続革命論）。スターリンの一国社会主義論と対立して敗れた。",region: "europe",cat: "思想・宗教",rank: 1,course: ["tankyu"],related: ["トロツキー","一国社会主義","スターリン"]},
  {term: "両シチリア王国",yomi: "りょうしちりあおうこく",def: "南イタリアとシチリア島を領域とした王国。ブルボン家が支配したが、1860年にガリバルディの千人隊に征服され、サルデーニャ王に献上されてイタリア王国に合流した。",year: 1816,end: 1861,region: "europe",cat: "国家・王朝",rank: 2,course: ["tankyu"],related: ["ガリバルディ","千人隊","イタリア統一"]},
  {term: "両班",yomi: "やんばん",def: "高麗・朝鮮王朝の支配階層。もとは文班・武班の官僚をさしたが、朝鮮王朝では科挙を通じて官職を独占する特権的身分となり、朱子学を学んで社会を指導した。",region: "east",cat: "経済・社会",rank: 3,course: ["tankyu"],related: ["朝鮮王朝","科挙","高麗","朱子学"]},
  {term: "両税法",yomi: "りょうぜいほう",def: "780年、唐の宰相楊炎の提案で施行された税制。均田制・租調庸制の崩壊を受け、土地所有を認めたうえで、資産に応じて夏と秋の2回に課税した。以後、明の一条鞭法まで税制の基本となった。",year: 780,region: "east",cat: "制度・政策",rank: 3,course: ["tankyu"],related: ["楊炎","租調庸制","均田制","唐"]},
  {term: "両聖都の保護",yomi: "りょうせいとのほご",def: "1517年、セリム1世がマムルーク朝を滅ぼしたことで、オスマン帝国がイスラームの聖地メッカとメディナの保護権を得たこと。オスマン帝国はスンナ派イスラーム世界の盟主となった。",year: 1517,region: "west",cat: "制度・政策",rank: 1,course: ["tankyu"],related: ["セリム1世","マムルーク朝","メッカ","メディナ"]},
  {term: "中ソ対立",yomi: "ちゅうそたいりつ",def: "1950年代後半から表面化した中国とソ連の対立。スターリン批判や平和共存路線をめぐるイデオロギー論争に始まり、1960年にソ連が技術者を引きあげ、1969年には国境で武力衝突が起こった。",year: 1956,region: "east",cat: "事件・戦争",rank: 3,course: ["tankyu"],related: ["フルシチョフ","スターリン批判","平和共存","毛沢東"]},
  {term: "中体西用",yomi: "ちゅうたいせいよう",def: "中国の伝統的な政治制度や儒教道徳を基本（体）とし、西洋の技術を手段（用）として利用するという考え方。洋務運動の基本理念で、政治体制の改革には及ばなかった。",region: "east",cat: "思想・宗教",rank: 2,course: ["tankyu"],related: ["洋務運動","李鴻章","曾国藩"]},
  {term: "中国からの独立",yomi: "ちゅうごくからのどくりつ",def: "10世紀、唐の滅亡後の混乱のなかでベトナムが中国の支配から独立したこと。939年に呉権が呉朝を建て、のち丁朝・李朝へと受けつがれた。",year: 939,region: "sea",cat: "事件・戦争",rank: 1,course: ["tankyu"],related: ["呉朝","丁朝","大越"]},
  {term: "中国共産党",yomi: "ちゅうごくきょうさんとう",def: "1921年、陳独秀らによって上海で結成された政党。国民党と国共合作と内戦をくり返し、毛沢東の指導のもとで勢力を広げた。1949年に中華人民共和国を建国し、政権党となった。",year: 1921,region: "east",cat: "組織・運動",rank: 3,course: ["sogo","tankyu"],related: ["陳独秀","毛沢東","国共合作","中華人民共和国"]},
  {term: "中国分割",yomi: "ちゅうごくぶんかつ",def: "日清戦争後、列強が清から租借地や鉄道敷設権を獲得し、勢力範囲を設定したこと。ドイツは膠州湾、ロシアは遼東半島南部、イギリスは威海衛・九竜半島、フランスは広州湾を租借した。",year: 1898,region: "east",cat: "事件・戦争",rank: 3,course: ["sogo","tankyu"],related: ["日清戦争","租借地","勢力範囲","門戸開放宣言"]},
  {term: "中国同盟会",yomi: "ちゅうごくどうめいかい",def: "1905年、孫文が東京で革命諸団体を結集して結成した組織。三民主義を綱領とし、清朝打倒と共和国建設をめざした。辛亥革命の中心となり、のち国民党に発展した。",year: 1905,region: "east",cat: "組織・運動",rank: 3,course: ["sogo","tankyu"],related: ["孫文","三民主義","辛亥革命"]},
  {term: "中国国民党",yomi: "ちゅうごくこくみんとう",def: "1919年、孫文が中華革命党を改組して結成した政党。国共合作をへて、孫文の死後は蔣介石が指導して北伐を進め、南京国民政府を樹立した。国共内戦に敗れ台湾に移った。",year: 1919,region: "east",cat: "組織・運動",rank: 3,course: ["sogo","tankyu"],related: ["孫文","蔣介石","国共合作","国民党"]},
  {term: "中央アメリカ",yomi: "ちゅうおうあめりか",def: "北アメリカと南アメリカを結ぶ地峡地帯。古くはマヤ文明が栄え、のちスペインの植民地となった。19世紀に独立し、グアテマラ・ホンジュラスなどの国々が成立した。",region: "america",cat: "地名・地域",rank: 1,course: ["tankyu"],related: ["中央アメリカ連邦","マヤ文明","ラテンアメリカの独立"]},
  {term: "中央アメリカ連邦",yomi: "ちゅうおうあめりかれんぽう",def: "1823年、スペインから独立した中央アメリカ諸地域が結成した連邦国家。内部対立により1839年ごろに解体し、グアテマラ・エルサルバドル・ホンジュラス・ニカラグア・コスタリカに分かれた。",year: 1823,end: 1839,region: "america",cat: "国家・王朝",rank: 1,course: ["tankyu"],related: ["ラテンアメリカの独立","グアテマラ","中央アメリカ"]},
  {term: "中東戦争",yomi: "ちゅうとうせんそう",def: "イスラエルとアラブ諸国との間で4回にわたり起こった戦争。1948年のイスラエル建国から始まり、第3次ではイスラエルが占領地を拡大し、第4次はアラブ産油国の石油戦略による石油危機をまねいた。",year: 1948,end: 1973,region: "west",cat: "事件・戦争",rank: 3,course: ["sogo","tankyu"],related: ["パレスチナ問題","イスラエル","スエズ戦争","石油危機"]},
  {term: "中立",yomi: "ちゅうりつ",def: "戦争や紛争の際に、どちらの陣営にも加わらない立場。スイスはウィーン会議で永世中立が認められ、第二次世界大戦ではスウェーデンなども中立を守った。",region: "europe",cat: "制度・政策",rank: 1,course: ["sogo","tankyu"],related: ["永世中立","スイス","スウェーデン"]},
  {term: "中継貿易",yomi: "ちゅうけいぼうえき",def: "ある地域から輸入した商品をそのまま他地域へ輸出する貿易。15世紀の琉球王国やマラッカ、アユタヤ朝などは、東アジアと東南アジアを結ぶ中継貿易で繁栄した。",region: "sea",cat: "経済・社会",rank: 2,course: ["tankyu"],related: ["琉球","アユタヤ朝","マラッカ王国"]},
  {term: "中華人民共和国",yomi: "ちゅうかじんみんきょうわこく",def: "国共内戦で勝利した中国共産党が、1949年10月に北京で建国を宣言した国家。毛沢東が国家主席、周恩来が首相となった。1971年に国連の中国代表権を得た。",year: 1949,region: "east",cat: "国家・王朝",rank: 3,course: ["sogo","tankyu"],related: ["毛沢東","周恩来","中国共産党","国共内戦"]},
  {term: "中華民国",yomi: "ちゅうかみんこく",def: "辛亥革命の結果、1912年に南京で成立したアジア初の共和国。孫文が臨時大総統となったが、まもなく袁世凱に実権が移った。国共内戦に敗れた国民党政府は1949年に台湾に移った。",year: 1912,region: "east",cat: "国家・王朝",rank: 3,course: ["sogo","tankyu"],related: ["辛亥革命","孫文","袁世凱","南京国民政府"]},
  {term: "主戦派",yomi: "しゅせんは",def: "南宋で金との和平に反対し、抗戦して華北の奪回を主張した人々。武将の岳飛がその代表で、和平派の宰相秦檜と対立し、無実の罪で処刑された。",region: "east",cat: "組織・運動",rank: 1,course: ["tankyu"],related: ["岳飛","秦檜","南宋","金"]},
  {term: "主権国家",yomi: "しゅけんこっか",def: "明確な国境と、他国の干渉を受けない最高の権力（主権）をもつ国家。16〜17世紀のヨーロッパで形成され、ウェストファリア条約後、対等な主権国家が並び立つ主権国家体制が確立した。",region: "europe",cat: "制度・政策",rank: 3,course: ["sogo","tankyu"],related: ["ウェストファリア条約","三十年戦争","主権国家体制"]},
  {term: "九か国条約",yomi: "きゅうかこくじょうやく",def: "1922年、ワシントン会議で結ばれた条約。米・英・日・仏・伊・中国など9か国が、中国の主権尊重・領土保全と門戸開放・機会均等を約束した。日本は山東の旧ドイツ権益を中国に返還した。",year: 1922,region: "east",cat: "条約・宣言",rank: 3,course: ["sogo","tankyu"],related: ["ワシントン会議","門戸開放","四か国条約"]},
  {term: "九・三〇事件",yomi: "きゅう・さんぜろじけん",def: "1965年、インドネシアで起こったクーデタ未遂事件。軍のスハルトが鎮圧し、共産党は徹底的に弾圧された。これを機にスカルノは失脚し、スハルトが実権をにぎった。",year: 1965,region: "sea",cat: "事件・戦争",rank: 2,course: ["tankyu"],related: ["スカルノ","スハルト","インドネシア共産党"]},
  {term: "九十五か条の論題",yomi: "きゅうじゅうごかじょうのろんだい",def: "1517年、ルターが教皇の贖宥状（免罪符）販売を批判して発表した文書。活版印刷によってたちまちドイツ各地に広まり、宗教改革のきっかけとなった。",year: 1517,region: "europe",cat: "条約・宣言",rank: 3,course: ["tankyu"],related: ["ルター","贖宥状","宗教改革"]},
  {term: "九品中正",yomi: "きゅうひんちゅうせい",def: "魏の曹丕（文帝）が始めた官吏登用制度。地方の中正官が人物を九段階に評価して推薦したが、有力豪族の子弟が上位を独占し、門閥貴族を生んだ。隋の科挙で廃止された。",year: 220,region: "east",cat: "制度・政策",rank: 3,course: ["tankyu"],related: ["魏","門閥貴族","科挙"]},
  {term: "乾隆帝",yomi: "けんりゅうてい",def: "清の第6代皇帝。ジュンガルを滅ぼし東トルキスタンを新疆として、清の最大領域を実現した。『四庫全書』を編纂させた。ヨーロッパ船の来航を広州一港に限り、イギリスのマカートニーの要求をしりぞけた。",year: 1735,end: 1795,region: "east",cat: "人物",rank: 3,course: ["sogo","tankyu"],related: ["清","ジュンガル","四庫全書","マカートニー"]},
  {term: "亀甲船",yomi: "きっこうせん",def: "朝鮮の李舜臣が用いた軍船。屋根状の甲板でおおわれており、豊臣秀吉の朝鮮出兵（壬辰・丁酉倭乱）で日本水軍を破るのに活躍した。",year: 1592,region: "east",cat: "文化・学問",rank: 1,course: ["tankyu"],related: ["李舜臣","壬辰・丁酉倭乱"]},
  {term: "予定説",yomi: "よていせつ",def: "カルヴァンが説いた、だれが救われるかはあらかじめ神によって決められているとする教え。勤労と禁欲による職業の成功を救いの確証とみなし、商工業者に広く受けいれられた。",year: 1536,region: "europe",cat: "思想・宗教",rank: 3,course: ["tankyu"],related: ["カルヴァン","宗教改革","プロテスタント"]},
  {term: "二十一か条の要求",yomi: "にじゅういっかじょうのようきゅう",def: "1915年、第一次世界大戦中に日本が袁世凱政府に突きつけた要求。山東省の旧ドイツ権益の継承や南満州の権益延長などを求め、大部分を承認させた。中国の反日感情を強めた。",year: 1915,region: "east",cat: "条約・宣言",rank: 3,course: ["sogo","tankyu"],related: ["袁世凱","五・四運動","第一次世界大戦","山東"]},
  {term: "二十一カ条の要求",yomi: "にじゅういっかじょうのようきゅう",def: "二十一か条の要求の別表記。1915年、日本が袁世凱政府に山東省のドイツ権益継承などを求めたもの。中国では受諾の日が「国恥記念日」とされ、反日運動の原因となった。",year: 1915,region: "east",cat: "条約・宣言",rank: 3,course: ["sogo"],related: ["二十一か条の要求","袁世凱","五・四運動"]},
  {term: "二十進法",yomi: "にじっしんほう",def: "20を単位として数を数える方法。中米のマヤ文明で用いられ、ゼロの概念とともに精密な暦の計算や天体観測に役立った。点と棒で数を表した。",region: "america",cat: "文化・学問",rank: 1,course: ["tankyu"],related: ["マヤ文明","ゼロの概念","マヤ文字"]},
  {term: "二月革命",yomi: "にがつかくめい",def: "1848年、フランスで選挙権拡大を求める運動を政府が弾圧したことから起こった革命。七月王政が倒れ第二共和政が成立し、ヨーロッパ各地に革命が広がった。なお1917年のロシアの革命もこうよぶ。",year: 1848,region: "europe",cat: "事件・戦争",rank: 3,course: ["sogo","tankyu"],related: ["七月王政","第二共和政","三月革命","ロシア革命"]},
  {term: "二次資料",yomi: "にじしりょう",def: "一次資料をもとに、後の時代の人がまとめたり解釈したりした資料。歴史書・研究書・教科書などがあたる。もとにした一次資料や書き手の立場を確かめて利用する必要がある。",region: "europe",cat: "文化・学問",rank: 1,course: ["sogo"],related: ["一次資料","史料批判"]},
  {term: "二重帝国",yomi: "にじゅうていこく",def: "1867年、オーストリアがハンガリーの自治を認めて成立したオーストリア=ハンガリー帝国の呼び名。皇帝が両国の君主をかねたが、内政はそれぞれ別の政府がおこなった。",year: 1867,end: 1918,region: "europe",cat: "国家・王朝",rank: 2,course: ["tankyu"],related: ["オーストリア=ハンガリー帝国","アウスグライヒ","マジャール人"]},
  {term: "二重統治体制",yomi: "にじゅうとうちたいせい",def: "遼が実施した統治方式。遊牧民の契丹人などには部族制にもとづく北面官、農耕民の漢人には州県制にもとづく南面官によって、それぞれ別の制度で支配した。",region: "inner",cat: "制度・政策",rank: 3,course: ["tankyu"],related: ["遼","耶律阿保機","契丹","北面官・南面官"]},
  {term: "五か年計画",yomi: "ごかねんけいかく",def: "1928年からスターリンが始めたソ連の計画経済。重工業の発展と農業の集団化（コルホーズ・ソフホーズ）を進め、世界恐慌の影響を受けずに工業大国となったが、農民の犠牲は大きかった。",year: 1928,region: "europe",cat: "制度・政策",rank: 3,course: ["sogo","tankyu"],related: ["スターリン","一国社会主義","世界恐慌","農業集団化"]},
  {term: "五・一五事件",yomi: "ご・いちごじけん",def: "1932年5月15日、海軍青年将校らが首相官邸をおそい、犬養毅首相を暗殺した事件。これにより政党内閣の時代は終わり、軍部の影響力が強まった。",year: 1932,region: "east",cat: "事件・戦争",rank: 3,course: ["sogo"],related: ["政党内閣","犬養毅","満州事変"]},
  {term: "五・四運動",yomi: "ご・しうんどう",def: "1919年5月4日、パリ講和会議で山東省の旧ドイツ権益返還が認められなかったことに抗議し、北京の学生から始まった反日・反帝国主義運動。全国に広がり、中国政府はヴェルサイユ条約の調印を拒否した。",year: 1919,region: "east",cat: "事件・戦争",rank: 3,course: ["sogo","tankyu"],related: ["パリ講和会議","二十一か条の要求","三・一独立運動"]},
  {term: "五代十国",yomi: "ごだいじっこく",def: "唐の滅亡から宋の統一までの分裂時代。華北では後梁・後唐・後晋・後漢・後周の5王朝が交代し、華南などでは10余りの国が興亡した。武人が実権をにぎり、旧来の門閥貴族は没落した。",year: 907,end: 979,region: "east",cat: "国家・王朝",rank: 3,course: ["tankyu"],related: ["節度使","宋","唐"]},
  {term: "五月危機",yomi: "ごがつきき",def: "1968年5月、フランスで学生運動から始まり、労働者のゼネストに広がった社会運動（五月革命）。ド=ゴール政権は動揺し、ド=ゴールは翌1969年に退陣した。",year: 1968,region: "europe",cat: "事件・戦争",rank: 1,course: ["tankyu"],related: ["ド=ゴール","学生運動","第五共和政"]},
  {term: "五箇条の誓文",yomi: "ごかじょうのせいもん",def: "1868年、明治天皇が神々に誓う形で示した新政府の基本方針。広く会議を興し公論で決すること、知識を世界に求めることなどを掲げた。",year: 1868,region: "east",cat: "条約・宣言",rank: 2,course: ["sogo"],related: ["明治維新","明治天皇","大政奉還"]},
  {term: "五経博士",yomi: "ごきょうはかせ",def: "前漢の武帝が董仲舒の献策で置いた、五経（易・書・詩・礼・春秋）を教授する官職。儒学の官学化を進め、儒学は国家の正統な学問となった。",year: -136,region: "east",cat: "制度・政策",rank: 2,course: ["tankyu"],related: ["武帝","董仲舒","儒学の官学化"]},
  {term: "五胡",yomi: "ごこ",def: "4世紀に華北に進出した5つの遊牧系民族。匈奴・羯・鮮卑・氐・羌をさす。八王の乱に乗じて勢力をのばし、西晋を滅ぼして華北に多くの国を建てた。",region: "inner",cat: "組織・運動",rank: 3,course: ["tankyu"],related: ["五胡十六国","匈奴","鮮卑","八王の乱"]},
  {term: "五胡十六国",yomi: "ごこじゅうろっこく",def: "4世紀初めから439年の北魏による華北統一まで、五胡や漢人が華北に建てた諸国の興亡の時代。前秦が一時華北を統一したが、淝水の戦いで東晋に敗れて崩壊した。",year: 304,end: 439,region: "east",cat: "国家・王朝",rank: 3,course: ["tankyu"],related: ["五胡","北魏","永嘉の乱"]},
  {term: "五賢帝",yomi: "ごけんてい",def: "1〜2世紀のローマ帝国の5人のすぐれた皇帝。ネルウァ・トラヤヌス・ハドリアヌス・アントニヌス=ピウス・マルクス=アウレリウス=アントニヌスで、この時代に帝国は最盛期をむかえた。",year: 96,end: 180,region: "europe",cat: "人物",rank: 3,course: ["tankyu"],related: ["ローマの平和","トラヤヌス","マルクス=アウレリウス=アントニヌス"]},
  {term: "交通革命",yomi: "こうつうかくめい",def: "19世紀、蒸気機関車や蒸気船の実用化によって交通と輸送が大きく変化したこと。1825年にスティーヴンソンの蒸気機関車が走り、鉄道網が広がって人や物の移動が速く安価になった。",year: 1825,region: "europe",cat: "経済・社会",rank: 3,course: ["sogo","tankyu"],related: ["スティーヴンソン","蒸気機関車","蒸気船","産業革命"]},
  {term: "交鈔",yomi: "こうしょう",def: "金や元で発行された紙幣。元では銀との交換を保証された紙幣として広く流通したが、のちに乱発によって価値が下がり、経済の混乱をまねいた。",region: "east",cat: "経済・社会",rank: 3,course: ["tankyu"],related: ["元","クビライ","交子","金"]},
  {term: "京都議定書",yomi: "きょうとぎていしょ",def: "1997年、京都で開かれた気候変動枠組条約の締約国会議で採択された議定書。先進国に温室効果ガスの削減目標を義務づけたが、アメリカは離脱した。",year: 1997,region: "east",cat: "条約・宣言",rank: 3,course: ["sogo","tankyu"],related: ["地球温暖化","地球サミット","パリ協定"]},
  {term: "人と資本の移動",yomi: "ひととしほんのいどう",def: "国境を越えて人や資本が移動すること。19世紀には大量の移民が新大陸へ渡り、イギリスなどの資本が世界に投資された。20世紀後半以降はグローバル化でさらに活発になった。",region: "europe",cat: "経済・社会",rank: 1,course: ["sogo"],related: ["グローバル化","移民","世界市場"]},
  {term: "人工知能（AI）",yomi: "じんこうちのう",def: "人間の知的な働きをコンピュータで実現しようとする技術。20世紀半ばに研究が始まり、21世紀には大量のデータを用いた機械学習で急速に発達し、社会への影響が議論されている。",year: 1956,region: "america",cat: "文化・学問",rank: 1,course: ["sogo","tankyu"],related: ["情報通信技術","グローバル化"]},
  {term: "人文主義",yomi: "じんぶんしゅぎ",def: "ギリシア・ローマの古典を研究し、人間性を尊重する思想（ヒューマニズム）。ルネサンスの基礎となり、ペトラルカやエラスムスらが代表的な人文主義者である。",region: "europe",cat: "思想・宗教",rank: 3,course: ["tankyu"],related: ["ルネサンス","エラスムス","ペトラルカ"]},
  {term: "人権宣言",yomi: "じんけんせんげん",def: "1789年、フランスの国民議会が採択した「人間および市民の権利の宣言」。ラ=ファイエットらが起草し、自由・平等、国民主権、私有財産の不可侵などを掲げ、近代市民社会の原理を示した。",year: 1789,region: "europe",cat: "条約・宣言",rank: 3,course: ["sogo","tankyu"],related: ["フランス革命","国民議会","ラ=ファイエット","国民主権"]},
  {term: "人民主権",yomi: "じんみんしゅけん",def: "国家の最高権力は人民にあるとする考え方。ルソーが『社会契約論』で主張し、人民の一般意志にもとづく政治を説いて、フランス革命に大きな影響をあたえた。",region: "europe",cat: "思想・宗教",rank: 2,course: ["sogo","tankyu"],related: ["ルソー","社会契約論","一般意志","国民主権"]},
  {term: "人民公社",yomi: "じんみんこうしゃ",def: "1958年、大躍進政策のもとで中国の農村に設けられた組織。農業の集団化に加え、行政・工業・教育・軍事などを一体化したが、生産意欲の低下をまねき、1980年代に解体された。",year: 1958,end: 1985,region: "east",cat: "制度・政策",rank: 3,course: ["tankyu"],related: ["大躍進","毛沢東","人民公社の解体"]},
  {term: "人民公社の解体",yomi: "じんみんこうしゃのかいたい",def: "1980年代、鄧小平の改革・開放政策のもとで人民公社が解体されたこと。農家ごとに生産を請け負う生産責任制が導入され、農業生産が増大した。",year: 1985,region: "east",cat: "制度・政策",rank: 1,course: ["tankyu"],related: ["鄧小平","改革・開放政策","生産責任制"]},
  {term: "人民戦線",yomi: "じんみんせんせん",def: "ファシズムに対抗するため、共産党・社会党・自由主義者などが結んだ協力体制。1935年にコミンテルンが提唱し、フランスではブルム内閣、スペインでも人民戦線政府が成立した。",year: 1935,region: "europe",cat: "組織・運動",rank: 3,course: ["tankyu"],related: ["コミンテルン","ブルム","スペイン内戦","ファシズム"]},
  {term: "人種隔離",yomi: "じんしゅかくり",def: "人種によって住む場所や学校・交通機関などを分ける差別的な制度。南アフリカのアパルトヘイトやアメリカ南部の黒人差別がその例で、1990年代にアパルトヘイトは撤廃された。",region: "africa",cat: "制度・政策",rank: 2,course: ["sogo","tankyu"],related: ["アパルトヘイト","マンデラ","公民権運動"]},
  {term: "人身供犠",yomi: "じんしんくぎ",def: "人間を神々へのいけにえとしてささげる儀礼。アステカ王国では太陽の運行を保つために必要とされ、捕虜などがいけにえにされた。",region: "america",cat: "思想・宗教",rank: 1,course: ["tankyu"],related: ["アステカ王国","太陽信仰","テノチティトラン"]},
  {term: "人間不平等起源論",yomi: "にんげんふびょうどうきげんろん",def: "ルソーが1755年に著した書物。人間は自然状態では自由で平等であったが、私有財産の発生によって不平等が生まれたと論じ、文明社会を批判した。",year: 1755,region: "europe",cat: "文化・学問",rank: 2,course: ["tankyu"],related: ["ルソー","社会契約論","啓蒙思想"]},
  {term: "仏典結集",yomi: "ぶってんけつじゅう",def: "ブッダの教えを確認し、経典にまとめる編集事業。ブッダの死後まもなく第1回が行われ、マウリヤ朝のアショーカ王のもとでも結集が行われたと伝えられる。",region: "south",cat: "思想・宗教",rank: 2,course: ["tankyu"],related: ["アショーカ王","マウリヤ朝","仏教"]},
  {term: "仏国寺",yomi: "ぶっこくじ",def: "新羅の都慶州に建てられた仏教寺院。8世紀半ばに大規模に造営され、近くの石窟庵とともに、仏教を保護した新羅の仏教文化を代表する建築である。",year: 751,region: "east",cat: "文化・学問",rank: 2,course: ["tankyu"],related: ["新羅","慶州","仏教"]},
  {term: "仏国記",yomi: "ぶっこくき",def: "東晋の僧法顕が著した旅行記。陸路でグプタ朝のインドに行き、海路で帰国した体験を記し、当時のインドや東南アジアの様子を伝える。",region: "south",cat: "文化・学問",rank: 2,course: ["tankyu"],related: ["法顕","グプタ朝","東晋"]},
  {term: "仏教",yomi: "ぶっきょう",def: "前5世紀ごろ、ガウタマ=シッダールタ（ブッダ）がインドで開いた宗教。ヴァルナ制を否定し、八正道の実践による解脱を説いた。のち上座部仏教と大乗仏教に分かれ、アジア各地に広まった。",region: "south",cat: "思想・宗教",rank: 3,course: ["sogo","tankyu"],related: ["ガウタマ=シッダールタ","大乗仏教","上座部仏教","アショーカ王"]},
  {term: "仏教の伝来",yomi: "ぶっきょうのでんらい",def: "仏教が中国から朝鮮半島、さらに日本へ伝えられたこと。4世紀に高句麗・百済に伝わり、6世紀には百済から倭（日本）へ伝えられたとされる。",year: 538,region: "east",cat: "思想・宗教",rank: 1,course: ["tankyu"],related: ["百済","大乗仏教","倭"]},
  {term: "代数学",yomi: "だいすうがく",def: "文字式や方程式を扱う数学の分野。9世紀、アッバース朝のフワーリズミーがインドの数学を取りいれて体系化し、のちヨーロッパにも伝わった。",region: "west",cat: "文化・学問",rank: 2,course: ["tankyu"],related: ["フワーリズミー","アラビア数字","イスラーム文化"]},
  {term: "代理戦争",yomi: "だいりせんそう",def: "大国が直接戦うのではなく、他国の内戦や紛争の各勢力を支援して戦わせること。冷戦期にはアメリカとソ連が各地で東西陣営の勢力を支援し、アンゴラ内戦などが代理戦争となった。",region: "europe",cat: "事件・戦争",rank: 2,course: ["sogo","tankyu"],related: ["冷戦","朝鮮戦争","ベトナム戦争","アンゴラ"]},
  {term: "代表なくして課税なし",yomi: "だいひょうなくしてかぜいなし",def: "印紙法に反対した北アメリカ植民地側のスローガン。植民地はイギリス議会に代表を送っていないので、議会は植民地に課税できないと主張した。",year: 1765,region: "america",cat: "条約・宣言",rank: 3,course: ["sogo","tankyu"],related: ["印紙法","アメリカ独立戦争","13植民地"]},
  {term: "伊藤博文",yomi: "いとうひろぶみ",def: "明治時代の政治家。初代内閣総理大臣となり、大日本帝国憲法の制定に中心的な役割を果たした。初代韓国統監を務め、1909年にハルビンで安重根に暗殺された。",year: 1841,end: 1909,region: "east",cat: "人物",rank: 3,course: ["sogo"],related: ["大日本帝国憲法","内閣制度","安重根","韓国統監府"]},
  {term: "休戦協定",yomi: "きゅうせんきょうてい",def: "1953年、板門店で結ばれた朝鮮戦争の休戦協定。北緯38度線付近を軍事境界線とし、南北の分断が固定された。平和条約は結ばれていない。",year: 1953,region: "east",cat: "条約・宣言",rank: 2,course: ["sogo","tankyu"],related: ["朝鮮戦争","北緯38度線","板門店"]},
  {term: "会稽",yomi: "かいけい",def: "現在の中国浙江省紹興付近の古い地名。春秋時代の越の都があり、越王勾践が呉に敗れて屈辱を受けたことから「会稽の恥」という故事が生まれた。",region: "east",cat: "地名・地域",rank: 1,course: ["tankyu"],related: ["越","勾践","呉越の争い"]},
  {term: "伯・巡察使",yomi: "はく・じゅんさつし",def: "カール大帝が整えた地方統治の制度。全国を州に分けて地方の有力者を伯に任命して治めさせ、中央から巡察使を派遣して伯を監督させた。",region: "europe",cat: "制度・政策",rank: 2,course: ["tankyu"],related: ["カール大帝","フランク王国"]},
  {term: "住民投票",yomi: "じゅうみんとうひょう",def: "ある地域の住民が投票によって重要な問題を決めること。冷戦後には東ティモール・モンテネグロ・南スーダンなどで独立の是非を問う住民投票が行われた。",region: "europe",cat: "制度・政策",rank: 1,course: ["sogo","tankyu"],related: ["分離独立","東ティモール","南スーダン"]},
  {term: "価格革命",yomi: "かかくかくめい",def: "16世紀、アメリカ大陸から大量の銀がヨーロッパに流入したことで起こった物価の急上昇。固定地代に頼る領主層が打撃を受け、商工業者が台頭した。",region: "europe",cat: "経済・社会",rank: 3,course: ["tankyu"],related: ["大航海時代","商業革命","ポトシ銀山"]},
  {term: "侯景の乱",yomi: "こうけいのらん",def: "548年、東魏から梁に降った武将侯景が起こした反乱。都の建康を攻め落とし、梁の武帝を死に追いやって南朝を大きく衰退させた。",year: 548,end: 552,region: "east",cat: "事件・戦争",rank: 1,course: ["tankyu"],related: ["梁","南朝","武帝（梁）"]},
  {term: "保守党",yomi: "ほしゅとう",def: "イギリスの政党で、トーリー党から発展した。19世紀に自由党と二大政党制をつくり、ディズレーリ、チャーチル、サッチャーらが党首・首相を務めた。",region: "europe",cat: "組織・運動",rank: 2,course: ["sogo","tankyu"],related: ["トーリー党","チャーチル","自由党","二大政党制"]},
  {term: "保甲法",yomi: "ほこうほう",def: "北宋の王安石の新法の一つ。農家を組織して治安維持にあたらせ、農閑期に軍事訓練をおこなって兵力を確保し、募兵の費用の削減をめざした。",year: 1070,region: "east",cat: "制度・政策",rank: 2,course: ["tankyu"],related: ["王安石","新法","北宋"]},
  {term: "保護国",yomi: "ほごこく",def: "条約などにより外交権を他国にゆだねた国。帝国主義の時代、列強は形式上は現地の君主を残しながら実質的に支配した。フランスによるチュニジア・モロッコ、日本による韓国などがその例である。",region: "europe",cat: "制度・政策",rank: 2,course: ["sogo","tankyu"],related: ["帝国主義","保護領","チュニジア","モロッコ"]},
  {term: "保護領",yomi: "ほごりょう",def: "宗主国の保護下に置かれ、外交権などを奪われた地域。帝国主義の時代、イギリスはアフリカやアラビア半島南部などに多くの保護領を設けた。",region: "africa",cat: "制度・政策",rank: 1,course: ["sogo","tankyu"],related: ["保護国","帝国主義","アフリカ分割"]},
  {term: "信仰義認",yomi: "しんこうぎにん",def: "人は善行ではなく信仰によってのみ神から正しい者と認められる（救われる）とするルターの教え。聖書のみを信仰の根拠とし、贖宥状や教皇の権威を否定した。",region: "europe",cat: "思想・宗教",rank: 2,course: ["tankyu"],related: ["ルター","宗教改革","贖宥状"]},
  {term: "信託統治",yomi: "しんたくとうち",def: "国際連合の監督のもとで、特定の国に未独立地域の統治をゆだねる制度。国際連盟の委任統治を受けついだもので、旧イタリア領ソマリアなどが対象となり、多くは独立した。",region: "africa",cat: "制度・政策",rank: 2,course: ["sogo","tankyu"],related: ["国際連合","委任統治","ソマリア"]},
  {term: "修道院",yomi: "しゅうどういん",def: "修道士・修道女が共同生活を送りながら修行する施設。6世紀にベネディクトゥスがモンテ=カシノに建てた修道院が西欧修道院の模範となり、学問の保存や開墾にも貢献した。",region: "europe",cat: "思想・宗教",rank: 2,course: ["tankyu"],related: ["ベネディクトゥス","モンテ=カシノ","クリュニー修道院"]},
  {term: "修道院の解散",yomi: "しゅうどういんのかいさん",def: "イギリス国教会を創設したヘンリ8世が、修道院を解散させてその土地・財産を没収したこと。没収した土地は貴族やジェントリに売られた。",year: 1536,region: "europe",cat: "制度・政策",rank: 1,course: ["tankyu"],related: ["ヘンリ8世","イギリス国教会","首長法"]},
  {term: "倭の五王",yomi: "わのごおう",def: "5世紀、中国の南朝の宋に使いを送った倭の5人の王（讃・珍・済・興・武）。冊封を受けて朝鮮半島での立場を有利にしようとした。",year: 421,end: 478,region: "east",cat: "人物",rank: 2,course: ["tankyu"],related: ["宋（南朝）","冊封","前方後円墳"]},
  {term: "倭寇",yomi: "わこう",def: "14〜16世紀に朝鮮半島や中国沿岸で活動した海賊・密貿易集団。前期は日本人が中心だったが、16世紀の後期倭寇は中国人が多かった。明は海禁政策で対処した。",region: "east",cat: "組織・運動",rank: 3,course: ["tankyu"],related: ["北虜南倭","勘合貿易","海禁"]},
  {term: "儒学の官学化",yomi: "じゅがくのかんがくか",def: "前漢の武帝のとき、董仲舒の献策で儒学が国家の正統な学問とされたこと。五経博士が置かれ、儒学の教養が官吏となる条件となった。",year: -136,region: "east",cat: "制度・政策",rank: 3,course: ["tankyu"],related: ["武帝","董仲舒","五経博士"]},
  {term: "儒家",yomi: "じゅか",def: "孔子を祖とする諸子百家の一つ。仁と礼による徳治主義をとなえ、孟子・荀子らが発展させた。漢代に官学とされ、儒教として中国の政治と社会の正統思想となった。",region: "east",cat: "思想・宗教",rank: 3,course: ["tankyu"],related: ["孔子","孟子","荀子","諸子百家"]},
  {term: "儒家（儒教）",yomi: "じゅか",def: "孔子の教えにもとづく思想・教学。家族道徳を重視し、仁による徳治主義を説いた。前漢の武帝以後は国家の正統な教学となり、東アジア全体に大きな影響をあたえた。",region: "east",cat: "思想・宗教",rank: 2,course: ["tankyu"],related: ["孔子","儒家","朱子学"]},
  {term: "元の侵攻",yomi: "げんのしんこう",def: "13世紀後半、元のクビライが東南アジアに軍を送ったこと。ビルマのパガン朝は元軍の侵攻を受けて大きく衰え、まもなく滅亡した。",year: 1287,region: "sea",cat: "事件・戦争",rank: 1,course: ["tankyu"],related: ["パガン朝","クビライ","元寇"]},
  {term: "元の撃退",yomi: "げんのげきたい",def: "13世紀後半、ベトナムの陳朝がクビライの元軍の侵攻を3度にわたって撃退したこと。白藤江の戦いなどで勝利し、民族意識が高まった。",year: 1288,region: "sea",cat: "事件・戦争",rank: 1,course: ["tankyu"],related: ["陳朝","大越","元寇"]},
  {term: "元の遠征",yomi: "げんのえんせい",def: "1292年、クビライがジャワに軍を送ったこと。シンガサリ朝は内乱で滅んでいたが、その混乱のなかでマジャパヒト王国が成立し、元軍は撤退した。",year: 1292,region: "sea",cat: "事件・戦争",rank: 1,course: ["tankyu"],related: ["シンガサリ朝","マジャパヒト王国","クビライ"]},
  {term: "元寇",yomi: "げんこう",def: "元のクビライによる2度の日本遠征（1274年の文永の役、1281年の弘安の役）。高麗軍も動員されたが、鎌倉幕府の防戦や暴風雨によって失敗した。",year: 1274,end: 1281,region: "east",cat: "事件・戦争",rank: 3,course: ["sogo","tankyu"],related: ["クビライ","文永の役","弘安の役"]},
  {term: "元老院",yomi: "げんろういん",def: "古代ローマの統治機関。貴族（パトリキ）出身の終身議員で構成され、共和政期には国政の実権をにぎった。帝政期にも存続したが、しだいに権限は形式的になった。",region: "europe",cat: "組織・運動",rank: 3,course: ["tankyu"],related: ["共和政","コンスル","パトリキ","属州"]},
  {term: "元首政",yomi: "げんしゅせい",def: "アウグストゥスが始めたローマ帝政前期の政治体制（プリンキパトゥス）。共和政の制度を尊重する形をとり、皇帝は「市民の第一人者（プリンケプス）」と称したが、実質的には全権をにぎった。",year: -27,region: "europe",cat: "制度・政策",rank: 3,course: ["tankyu"],related: ["アウグストゥス","プリンケプス","専制君主政"]},
  {term: "元首政（プリンキパトゥス）",yomi: "げんしゅせい",def: "アウグストゥスに始まるローマ帝政前期の体制。元老院など共和政の形を残しつつ、プリンケプス（元首）が実権をにぎった。ディオクレティアヌス帝の専制君主政にかわった。",year: -27,end: 284,region: "europe",cat: "制度・政策",rank: 2,course: ["tankyu"],related: ["元首政","アウグストゥス","専制君主政（ドミナトゥス）"]},
  {term: "先住民",yomi: "せんじゅうみん",def: "ある地域に古くから住んでいた人々。アメリカ大陸の先住民はスペインの征服やエンコミエンダ制での酷使、伝染病で激減し、ラス=カサスはその保護を訴えた。",region: "america",cat: "経済・社会",rank: 2,course: ["sogo","tankyu"],related: ["ラス=カサス","エンコミエンダ制","先住民強制移住法"]},
  {term: "先住民強制移住法",yomi: "せんじゅうみんきょうせいいじゅうほう",def: "1830年、ジャクソン大統領のもとで制定された法律。ミシシッピ川以東の先住民をその西方の保留地へ強制的に移住させ、多くの犠牲者を出した（涙の旅路）。",year: 1830,region: "america",cat: "制度・政策",rank: 2,course: ["tankyu"],related: ["ジャクソン","涙の旅路","西部開拓"]},
  {term: "先占権",yomi: "せんせんけん",def: "1884〜85年のベルリン会議で確認された、どの国にも属していない地域を先に実効支配した国が領有できるとする原則。アフリカ分割を加速させた。",year: 1885,region: "africa",cat: "制度・政策",rank: 1,course: ["tankyu"],related: ["ベルリン会議（1884〜85）","アフリカ分割","コンゴ自由国"]},
  {term: "光武帝",yomi: "こうぶてい",def: "後漢の初代皇帝（劉秀）。赤眉の乱などの混乱のなかで王莽の新を倒し、25年に漢を復興して都を洛陽とした。倭の奴国王に金印を授けたとされる。",year: 25,end: 57,region: "east",cat: "人物",rank: 3,course: ["tankyu"],related: ["後漢","赤眉の乱","劉秀"]},
  {term: "光緒帝",yomi: "こうしょてい",def: "清の第11代皇帝。日清戦争後、康有為らを登用して戊戌の変法とよばれる改革をおこなったが、西太后ら保守派のクーデタで幽閉された。",year: 1875,end: 1908,region: "east",cat: "人物",rank: 2,course: ["tankyu"],related: ["戊戌の変法","康有為","西太后"]},
  {term: "光緒新政",yomi: "こうしょしんせい",def: "義和団事件後、清朝が進めた近代化改革。科挙の廃止、新軍の編制、憲法大綱の発表と国会開設の公約などをおこなったが、清朝の延命策とみなされた。",year: 1901,region: "east",cat: "制度・政策",rank: 2,course: ["tankyu"],related: ["西太后","科挙の廃止","憲法大綱"]},
  {term: "党錮の禁",yomi: "とうこのきん",def: "後漢末、宦官が、自分たちを批判する官僚や学者（党人）を弾圧し、官職から追放した事件。政治の混乱が深まり、黄巾の乱へとつながった。",year: 166,region: "east",cat: "事件・戦争",rank: 2,course: ["tankyu"],related: ["後漢","宦官","黄巾の乱"]},
  {term: "入植者（コロン）",yomi: "にゅうしょくしゃ",def: "フランス領アルジェリアに移住したヨーロッパ系入植者。土地や政治的権利を独占し、アルジェリア独立戦争では独立に強く反対した。",region: "africa",cat: "経済・社会",rank: 1,course: ["tankyu"],related: ["アルジェリア","アルジェリア戦争","フランス"]},
  {term: "全インド=ムスリム連盟",yomi: "ぜんいんど=むすりむれんめい",def: "1906年、イギリスの支援のもとで結成されたインドのムスリムの政治団体。のちジンナーの指導でパキスタンの分離独立を要求し、1947年のインド・パキスタン分離独立を実現した。",year: 1906,region: "south",cat: "組織・運動",rank: 3,course: ["sogo","tankyu"],related: ["ジンナー","インド国民会議","パキスタン"]},
  {term: "全国水平社",yomi: "ぜんこくすいへいしゃ",def: "1922年、被差別部落の人々が自らの力で差別からの解放をめざして結成した団体。「水平社宣言」を発表し、全国に運動を広げた。",year: 1922,region: "east",cat: "組織・運動",rank: 2,course: ["sogo"],related: ["大正デモクラシー","社会運動"]},
  {term: "全権委任法",yomi: "ぜんけんいにんほう",def: "1933年、ヒトラー内閣が成立させた法律。政府に立法権をあたえ、議会の承認なしに法律を定めることを可能にした。ヴァイマル憲法は事実上停止され、ナチスの一党独裁が確立した。",year: 1933,region: "europe",cat: "制度・政策",rank: 3,course: ["sogo","tankyu"],related: ["ヒトラー","ナチス","ヴァイマル憲法"]},
  {term: "八旗",yomi: "はっき",def: "ヌルハチが創設した女真の軍事・行政組織。全軍を8つの旗に分けて組織した。清では満洲人のほかモンゴル人・漢人の八旗も設けられ、中国支配の中核となった。",year: 1615,region: "east",cat: "制度・政策",rank: 3,course: ["tankyu"],related: ["ヌルハチ","後金","緑営"]},
  {term: "八正道",yomi: "はっしょうどう",def: "ブッダが説いた、苦しみから解脱するための8つの正しい修行法。正しい見方・考え方・言葉・行いなどからなり、四諦の教えと並ぶ仏教の基本である。",region: "south",cat: "思想・宗教",rank: 1,course: ["tankyu"],related: ["仏教","四諦","ガウタマ=シッダールタ"]},
  {term: "八王の乱",yomi: "はちおうのらん",def: "西晋で皇族の8人の王が帝位をめぐって争った内乱。各王が遊牧民の兵を動員したため五胡が勢力をのばし、西晋滅亡の原因となった。",year: 290,end: 306,region: "east",cat: "事件・戦争",rank: 2,course: ["tankyu"],related: ["西晋","五胡","永嘉の乱"]},
  {term: "公安委員会",yomi: "こうあんいいんかい",def: "フランス革命中の1793年、国民公会内に設置された機関。ロベスピエールらジャコバン派が中心となり、反対派を処刑する恐怖政治をおこなった。",year: 1793,region: "europe",cat: "組織・運動",rank: 3,course: ["tankyu"],related: ["ロベスピエール","ジャコバン派","恐怖政治"]},
  {term: "公民権法",yomi: "こうみんけんほう",def: "1964年、ジョンソン政権のもとで制定されたアメリカの法律。公共施設などでの人種差別を禁止した。ケネディが提案し、公民権運動の成果として成立した。",year: 1964,region: "america",cat: "制度・政策",rank: 3,course: ["sogo","tankyu"],related: ["公民権運動","キング牧師","ジョンソン"]},
  {term: "公民権運動",yomi: "こうみんけんうんどう",def: "1950〜60年代にアメリカで黒人が人種差別の撤廃と権利の平等を求めた運動。キング牧師の非暴力主義のもとで広がり、1964年の公民権法制定を実現した。",year: 1955,end: 1968,region: "america",cat: "組織・運動",rank: 3,course: ["sogo","tankyu"],related: ["キング牧師","公民権法","ワシントン大行進"]},
  {term: "公行",yomi: "こうこう",def: "清代、広州で対外貿易を独占した特許商人の組合。ヨーロッパ商人との貿易を管理し、その不自由さがイギリスの不満をまねいた。南京条約で廃止された。",year: 1757,region: "east",cat: "組織・運動",rank: 3,course: ["sogo","tankyu"],related: ["広州","乾隆帝","南京条約"]},
  {term: "六朝文化",yomi: "りくちょうぶんか",def: "江南の建康を都とした呉・東晋・南朝の宋・斉・梁・陳の六朝時代に栄えた貴族文化。王羲之の書や顧愷之の絵画、陶淵明の詩などが代表である。",region: "east",cat: "文化・学問",rank: 2,course: ["tankyu"],related: ["東晋","南朝","陶淵明","王羲之"]},
  {term: "六諭",yomi: "りくゆ",def: "明の洪武帝が民衆の教化のために定めた6か条の教訓。父母への孝行や目上の人への尊敬などを説き、里甲制のもとで村々に広めさせた。",year: 1397,region: "east",cat: "制度・政策",rank: 1,course: ["tankyu"],related: ["洪武帝","里甲制","明"]},
  {term: "共和党",yomi: "きょうわとう",def: "1854年、奴隷制の拡大に反対する人々が結成したアメリカの政党。1860年にリンカンが大統領に当選し、南北戦争をまねいた。民主党とともに二大政党の一つである。",year: 1854,region: "america",cat: "組織・運動",rank: 2,course: ["sogo","tankyu"],related: ["リンカン","南北戦争","民主党"]},
  {term: "共和政",yomi: "きょうわせい",def: "君主をおかず、国民の選んだ代表などによって政治をおこなう政体。古代ローマの共和政や、清教徒革命後のイギリス共和政、フランス革命での第一共和政などがある。",region: "europe",cat: "制度・政策",rank: 2,course: ["sogo","tankyu"],related: ["元老院","クロムウェル","王政"]},
  {term: "共産党宣言",yomi: "きょうさんとうせんげん",def: "1848年、マルクスとエンゲルスが発表した文書。階級闘争による歴史の発展を説き、「万国の労働者よ、団結せよ」と呼びかけて社会主義運動に大きな影響をあたえた。",year: 1848,region: "europe",cat: "文化・学問",rank: 3,course: ["tankyu"],related: ["マルクス","エンゲルス","社会主義"]},
  {term: "兵馬俑",yomi: "へいばよう",def: "秦の始皇帝陵の近くから発見された、兵士や馬をかたどった多数の陶製の像。実物大で一体ずつ表情が異なり、秦の軍隊の姿を伝える。",region: "east",cat: "文化・学問",rank: 2,course: ["tankyu"],related: ["始皇帝","秦"]},
  {term: "典礼問題",yomi: "てんれいもんだい",def: "中国人信者の孔子崇拝や祖先祭祀を認めるかをめぐる論争。イエズス会は容認したが、他の修道会や教皇はこれを否定した。康熙帝はイエズス会以外の布教を禁じ、雍正帝はキリスト教布教を全面禁止した。",region: "east",cat: "思想・宗教",rank: 2,course: ["tankyu"],related: ["イエズス会","康熙帝","雍正帝","キリスト教"]},
  {term: "内モンゴル",yomi: "うちもんごる",def: "ゴビ砂漠の南側のモンゴル地域。17世紀前半にホンタイジがチャハル部を降して清の支配下に入った。現在は中国の内モンゴル自治区となっている。",region: "inner",cat: "地名・地域",rank: 1,course: ["tankyu"],related: ["ホンタイジ","外モンゴル","チャハル"]},
  {term: "内戦",yomi: "ないせん",def: "一つの国のなかで、政府と反政府勢力、あるいは対立する勢力どうしが武力で争うこと。冷戦期や冷戦後には、アフリカやアジアで民族・宗教の対立による内戦が多く起こった。",region: "africa",cat: "事件・戦争",rank: 1,course: ["sogo","tankyu"],related: ["民族紛争","代理戦争","難民"]},
  {term: "内閣制度",yomi: "ないかくせいど",def: "1885年に日本で創設された、内閣を中心とする行政制度。太政官制を廃止して設けられ、伊藤博文が初代内閣総理大臣となった。",year: 1885,region: "east",cat: "制度・政策",rank: 2,course: ["sogo"],related: ["伊藤博文","大日本帝国憲法"]},
  {term: "内閣大学士",yomi: "ないかくだいがくし",def: "明の永楽帝のころから置かれた、皇帝を補佐する官職。洪武帝が中書省を廃止して皇帝が六部を直接統轄したのち、内閣大学士が政治の実務を担うようになった。",year: 1402,region: "east",cat: "制度・政策",rank: 1,course: ["tankyu"],related: ["永楽帝","明","中書省"]},
  {term: "内陸貿易",yomi: "ないりくぼうえき",def: "陸路による遠隔地間の交易。前1200年ごろからアラム人がダマスクスを中心にシリアの内陸貿易で活躍し、アラム語は国際商業語となった。",region: "west",cat: "経済・社会",rank: 1,course: ["tankyu"],related: ["アラム人","アラム文字","フェニキア人"]},
  {term: "冊封",yomi: "さくほう",def: "中国の皇帝が周辺諸国の君主に官位や称号をあたえて君臣関係を結ぶこと。朝貢と結びついて冊封体制とよばれる東アジアの国際秩序をつくった。",region: "east",cat: "制度・政策",rank: 3,course: ["tankyu"],related: ["朝貢","冊封体制","朝貢貿易"]},
  {term: "冒頓単于",yomi: "ぼくとつぜんう",def: "匈奴の君主（単于）。前3世紀末に即位して周辺の遊牧民を統合し、月氏を破った。前200年には漢の劉邦を破り、漢に貢物を出させる和親を結ばせた。",year: -209,end: -174,region: "inner",cat: "人物",rank: 3,course: ["tankyu"],related: ["匈奴","劉邦","月氏"]},
  {term: "冬戦争",yomi: "ふゆせんそう",def: "1939〜40年、ソ連がフィンランドに侵攻した戦争。フィンランドは激しく抵抗したが領土の一部を割譲した。ソ連はこの侵攻により国際連盟から除名された。",year: 1939,end: 1940,region: "europe",cat: "事件・戦争",rank: 1,course: ["tankyu"],related: ["フィンランド","ソ連","国際連盟"]},
  {term: "冷戦",yomi: "れいせん",def: "第二次世界大戦後、アメリカを中心とする資本主義陣営とソ連を中心とする社会主義陣営の対立。直接の戦争には至らなかったが、軍拡競争や各地での代理戦争が起こった。1989年に終結が宣言された。",year: 1947,end: 1989,region: "europe",cat: "事件・戦争",rank: 3,course: ["sogo","tankyu"],related: ["トルーマン=ドクトリン","封じ込め政策","北大西洋条約機構（NATO）","ワルシャワ条約機構"]},
  {term: "冷戦の終結",yomi: "れいせんのしゅうけつ",def: "1989年、アメリカのブッシュ大統領とソ連のゴルバチョフ書記長がマルタ会談で冷戦の終結を宣言したこと。同年に東欧革命が起こり、1990年にドイツ統一、1991年にソ連が解体した。",year: 1989,region: "europe",cat: "事件・戦争",rank: 3,course: ["sogo","tankyu"],related: ["ゴルバチョフ","マルタ会談","ベルリンの壁崩壊"]},
  {term: "分割占領",yomi: "ぶんかつせんりょう",def: "第二次世界大戦後、ドイツとベルリンがアメリカ・イギリス・フランス・ソ連の4か国によって分割占領されたこと。冷戦の進行で1949年に東西ドイツが分立した。",year: 1945,region: "europe",cat: "制度・政策",rank: 2,course: ["sogo","tankyu"],related: ["ポツダム会談","ベルリン封鎖","東西ドイツ"]},
  {term: "分離独立",yomi: "ぶんりどくりつ",def: "ある地域が既存の国家から分かれて独立すること。1947年、インドはヒンドゥー教徒中心のインドとムスリム中心のパキスタンに分かれて独立した。",year: 1947,region: "south",cat: "事件・戦争",rank: 2,course: ["sogo","tankyu"],related: ["ジンナー","インド=パキスタン分離独立","全インド=ムスリム連盟"]},
  {term: "初代大統領",yomi: "しょだいだいとうりょう",def: "アメリカ合衆国の初代大統領ワシントンのこと。独立戦争で総司令官を務め、合衆国憲法のもとで1789年に就任し、2期務めて退いた。",year: 1789,region: "america",cat: "人物",rank: 1,course: ["sogo","tankyu"],related: ["ワシントン","合衆国憲法"]},
  {term: "前方後円墳",yomi: "ぜんぽうこうえんふん",def: "3世紀後半から7世紀ごろ、日本列島で造られた方形と円形を組み合わせた形の古墳。ヤマト政権の勢力の広がりを示し、大仙陵古墳などの巨大なものもある。",region: "east",cat: "文化・学問",rank: 1,course: ["sogo","tankyu"],related: ["ヤマト政権","倭の五王"]},
  {term: "前漢",yomi: "ぜんかん",def: "前202年、劉邦が建てた王朝。都は長安。郡国制を採用し、武帝の時代に最盛期をむかえて匈奴の討伐や儒学の官学化が進んだ。8年に外戚の王莽に帝位を奪われた。",year: -202,end: 8,region: "east",cat: "国家・王朝",rank: 3,course: ["tankyu"],related: ["劉邦","武帝","郡国制","王莽"]},
  {term: "創氏改名",yomi: "そうしかいめい",def: "日本の朝鮮支配のもとで、1940年に朝鮮の人々に日本式の氏をつくらせ、名を改めることを認めた政策。皇民化政策の一環として実質的に強制された。",year: 1940,region: "east",cat: "制度・政策",rank: 2,course: ["sogo","tankyu"],related: ["皇民化政策","朝鮮総督府","日本語の強制"]},
  {term: "劉備",yomi: "りゅうび",def: "三国時代の蜀の建国者。漢の皇族の子孫と称し、諸葛亮を軍師に迎えて勢力を広げた。孫権と結んで赤壁の戦いで曹操を破り、221年に成都で皇帝に即位した。",year: 161,end: 223,region: "east",cat: "人物",rank: 2,course: ["tankyu"],related: ["蜀","三国時代","諸葛亮"]},
  {term: "劉裕",yomi: "りゅうゆう",def: "南朝の宋の建国者。東晋の武将として反乱の鎮圧や北伐で活躍して実権をにぎり、420年に東晋の帝位を奪って宋を建てた。これにより南朝が始まった。",year: 420,end: 422,region: "east",cat: "人物",rank: 1,course: ["tankyu"],related: ["宋（南朝）","東晋","南朝"]},
  {term: "劉邦",yomi: "りゅうほう",def: "前漢の初代皇帝（高祖）。農民出身で秦末の反乱に加わり、項羽を破って前202年に漢を建てた。郡県制と封建制を併用する郡国制を採用した。",year: -202,end: -195,region: "east",cat: "人物",rank: 3,course: ["tankyu"],related: ["前漢","項羽","四面楚歌","郡国制"]},
  {term: "勘合貿易",yomi: "かんごうぼうえき",def: "室町幕府が明との間でおこなった朝貢形式の貿易。倭寇と区別するため、勘合とよばれる証明書を使った。足利義満が明の冊封を受けて始めた。",year: 1404,region: "east",cat: "経済・社会",rank: 2,course: ["sogo","tankyu"],related: ["永楽帝","朝貢貿易","倭寇"]},
  {term: "募兵制",yomi: "ぼへいせい",def: "兵士を給与で雇い入れる兵制。唐の玄宗のとき府兵制にかわって採用され、辺境で募兵を指揮する節度使が強い力をもつようになった。",region: "east",cat: "制度・政策",rank: 2,course: ["tankyu"],related: ["府兵制","節度使","玄宗"]},
  {term: "募役法",yomi: "ぼえきほう",def: "北宋の王安石の新法の一つ。各戸から免役銭を納めさせ、それを財源に希望者を雇って職役を担当させ、農民の重い負担を軽くしようとした。",region: "east",cat: "制度・政策",rank: 1,course: ["tankyu"],related: ["王安石","新法","北宋"]},
  {term: "勢力均衡",yomi: "せいりょくきんこう",def: "一国が強大になるのを防ぐため、諸国の力のつりあいを保とうとする考え方や外交政策。ウィーン会議以後、メッテルニヒのもとで大国の協調による勢力均衡がはかられた。",region: "europe",cat: "制度・政策",rank: 2,course: ["tankyu"],related: ["メッテルニヒ","ウィーン体制","四国同盟"]},
  {term: "勾践",yomi: "こうせん",def: "春秋時代の越の王。呉王夫差に会稽で敗れたが、復讐を誓って国力を回復し、のちに呉を滅ぼした。「臥薪嘗胆」の故事で知られる。",region: "east",cat: "人物",rank: 1,course: ["tankyu"],related: ["越","呉越の争い","会稽","臥薪嘗胆"]},
  {term: "匈奴",yomi: "きょうど",def: "前3世紀末にモンゴル高原で強大になった遊牧国家。冒頓単于のもとで漢を圧迫したが、武帝の攻撃で衰え、のち東西、さらに南北に分裂した。南匈奴は五胡の一つとして華北に進出した。",region: "inner",cat: "国家・王朝",rank: 3,course: ["sogo","tankyu"],related: ["冒頓単于","武帝","張騫","五胡"]},
  {term: "北アイルランド問題",yomi: "きたあいるらんどもんだい",def: "イギリス領北アイルランドでのプロテスタント系住民とカトリック系住民の対立。1960年代末から武力衝突やテロが続いたが、1998年に和平合意（ベルファスト合意）が成立した。",year: 1969,end: 1998,region: "europe",cat: "事件・戦争",rank: 2,course: ["tankyu"],related: ["アイルランド","イギリス","ベルファスト合意"]},
  {term: "北イタリア都市",yomi: "きたいたりあとし",def: "中世に商業で繁栄したヴェネツィア・ジェノヴァ・ミラノ・フィレンツェなど北イタリアの都市。地中海での東方貿易で富を築き、自治権をもつ都市共和国としてルネサンスの舞台となった。",region: "europe",cat: "地名・地域",rank: 1,course: ["tankyu"],related: ["ヴェネツィア","ジェノヴァ","東方貿易","ロンバルディア同盟"]},
  {term: "北インド侵入",yomi: "きたいんどしんにゅう",def: "10世紀末からガズナ朝・ゴール朝などのイスラーム勢力がアフガニスタン方面から北インドへくり返し侵入したこと。これを機にインドのイスラーム化が進み、デリー=スルタン朝が成立した。",region: "south",cat: "事件・戦争",rank: 1,course: ["tankyu"],related: ["ガズナ朝","ゴール朝","奴隷王朝"]},
  {term: "北ドイツ連邦",yomi: "きたどいつれんぽう",def: "1867年、プロイセン=オーストリア戦争に勝ったプロイセンが中心となり、マイン川以北の諸邦で結成した連邦。1871年のドイツ帝国成立の基礎となった。",year: 1867,end: 1871,region: "europe",cat: "国家・王朝",rank: 2,course: ["tankyu"],related: ["プロイセン=オーストリア戦争","ビスマルク","ドイツ帝国"]},
  {term: "北京議定書",yomi: "ぺきんぎていしょ",def: "1901年、義和団事件の後、清と列強11か国との間で結ばれた条約（辛丑和約）。清は巨額の賠償金の支払いと北京などへの外国軍隊の駐留を認め、半植民地化が進んだ。",year: 1901,region: "east",cat: "条約・宣言",rank: 3,course: ["sogo","tankyu"],related: ["義和団事件","8か国連合軍","李鴻章"]},
  {term: "北京遷都",yomi: "ぺきんせんと",def: "明の永楽帝が都を南京から北京に移したこと。永楽帝はもと北平に拠点をもつ燕王であり、モンゴルへの防衛も考慮した。紫禁城が造営された。",year: 1421,region: "east",cat: "事件・戦争",rank: 2,course: ["tankyu"],related: ["永楽帝","靖難の役","紫禁城"]},
  {term: "北伐",yomi: "ほくばつ",def: "1926〜28年、蔣介石の率いる国民革命軍が北方の軍閥を打倒して中国統一をめざした軍事行動。途中で上海クーデタを起こして共産党を弾圧し、1928年に北京に入り統一をほぼ達成した。",year: 1926,end: 1928,region: "east",cat: "事件・戦争",rank: 3,course: ["sogo","tankyu"],related: ["蔣介石","国民革命軍","上海クーデタ","張作霖"]},
  {term: "北宋",yomi: "ほくそう",def: "960年、趙匡胤が開封を都に建てた王朝。文治主義をとり、科挙を整備して皇帝独裁を確立した。王安石の新法などで財政再建をはかったが、1127年の靖康の変で金に滅ぼされた。",year: 960,end: 1127,region: "east",cat: "国家・王朝",rank: 3,course: ["tankyu"],related: ["趙匡胤","王安石","文治主義","靖康の変"]},
  {term: "北方戦争",yomi: "ほっぽうせんそう",def: "1700〜21年、ロシアのピョートル1世がスウェーデンのカール12世と戦った戦争。ロシアはバルト海沿岸を得て、ペテルブルクを建設し、北ヨーロッパの大国となった。",year: 1700,end: 1721,region: "europe",cat: "事件・戦争",rank: 3,course: ["tankyu"],related: ["ピョートル1世","スウェーデン","ペテルブルク"]},
  {term: "北朝",yomi: "ほくちょう",def: "439年に北魏が華北を統一してから隋の統一までの華北の王朝。北魏・東魏・西魏・北斉・北周をさす。均田制・府兵制など、隋・唐に受けつがれる制度が生まれた。",year: 439,end: 589,region: "east",cat: "国家・王朝",rank: 3,course: ["tankyu"],related: ["北魏","東魏","西魏","南朝"]},
  {term: "北洋艦隊",yomi: "ほくようかんたい",def: "洋務運動のなかで李鴻章が建設した清の近代海軍。ドイツ製の甲鉄艦をそろえてアジア有数の海軍となったが、日清戦争で日本海軍に敗れて壊滅した。",year: 1888,region: "east",cat: "組織・運動",rank: 1,course: ["tankyu"],related: ["李鴻章","洋務運動","日清戦争"]},
  {term: "北洋軍",yomi: "ほくようぐん",def: "袁世凱が李鴻章の淮軍を受けついで育成した清末の新式陸軍。袁世凱の権力基盤となり、中華民国初期には北洋軍閥として政治を左右した。",region: "east",cat: "組織・運動",rank: 1,course: ["tankyu"],related: ["袁世凱","李鴻章","軍閥"]},
  {term: "北緯38度線",yomi: "ほくいさんじゅうはちどせん",def: "第二次世界大戦後、朝鮮半島をアメリカとソ連が分割占領した際の境界線。1948年に南北に別々の国家が成立し、朝鮮戦争の休戦後はほぼこの線付近が軍事境界線となった。",year: 1945,region: "east",cat: "地名・地域",rank: 3,course: ["sogo","tankyu"],related: ["朝鮮戦争","大韓民国","朝鮮民主主義人民共和国"]},
  {term: "北虜",yomi: "ほくりょ",def: "明代に北方から侵入をくり返したモンゴル系の勢力をさす呼び名。15世紀のオイラト、16世紀のタタールのアルタンが明を苦しめた。",region: "inner",cat: "組織・運動",rank: 1,course: ["tankyu"],related: ["北虜南倭","オイラト","タタール"]},
  {term: "北虜南倭",yomi: "ほくりょなんわ",def: "明を苦しめた北方のモンゴル勢力（北虜）と東南沿岸の倭寇（南倭）による外患。16世紀にはアルタンが北京を包囲し、後期倭寇が沿岸をおそって明の財政を圧迫した。",region: "east",cat: "事件・戦争",rank: 3,course: ["tankyu"],related: ["アルタン","倭寇","土木の変","庚戌の変"]},
  {term: "北魏",yomi: "ほくぎ",def: "鮮卑の拓跋氏が建てた王朝。439年に太武帝が華北を統一した。孝文帝が均田制を実施し、洛陽に遷都して漢化政策を進めたが、のち東魏と西魏に分裂した。",year: 386,end: 534,region: "east",cat: "国家・王朝",rank: 3,course: ["tankyu"],related: ["鮮卑","拓跋氏","孝文帝","均田制"]},
  {term: "医学典範",yomi: "いがくてんぱん",def: "イブン=シーナーが著した医学書。ギリシア医学とイスラーム世界の医学を集大成したもので、ラテン語に翻訳され、ヨーロッパでも長く医学の教科書として使われた。",region: "west",cat: "文化・学問",rank: 3,course: ["tankyu"],related: ["イブン=シーナー","イスラーム文化","ギリシア医学"]},
  {term: "十全老人",yomi: "じゅうぜんろうじん",def: "清の乾隆帝が晩年に自らを称した号。ジュンガル平定などの生涯10回の遠征（十全武功）をすべて成功させたと誇ったことによる。",region: "east",cat: "人物",rank: 1,course: ["tankyu"],related: ["乾隆帝","清","ジュンガル"]},
  {term: "十六大国",yomi: "じゅうろくたいこく",def: "前6世紀ごろ、北インドのガンジス川流域を中心に成立した16の国々。このなかからコーサラ国とマガダ国が有力となり、やがてマガダ国が北インドの統一を進めた。",region: "south",cat: "国家・王朝",rank: 1,course: ["tankyu"],related: ["マガダ国","コーサラ国","ガンジス川"]},
  {term: "十四か条",yomi: "じゅうよんかじょう",def: "1918年、アメリカ大統領ウィルソンが発表した第一次世界大戦の講和原則。秘密外交の廃止、海洋の自由、軍備縮小、民族自決、国際平和機構の設立などを掲げ、パリ講和会議の基礎となった。",year: 1918,region: "america",cat: "条約・宣言",rank: 3,course: ["sogo","tankyu"],related: ["ウィルソン","国際連盟","民族自決","パリ講和会議"]},
  {term: "十字軍",yomi: "じゅうじぐん",def: "聖地イェルサレムの奪回を目的に、西ヨーロッパのキリスト教徒が組織した遠征軍。1095年のクレルモン宗教会議でウルバヌス2世が提唱し、第1回でイェルサレム王国を建てたが、最終的には失敗した。",year: 1096,end: 1270,region: "europe",cat: "事件・戦争",rank: 3,course: ["tankyu"],related: ["ウルバヌス2世","クレルモン宗教会議","セルジューク朝","イェルサレム"]},
  {term: "十月革命",yomi: "じゅうがつかくめい",def: "1917年11月（ロシア暦10月）、レーニンとトロツキーの指導するボリシェヴィキが武装蜂起して臨時政府を倒した革命。ソヴィエト政権が成立し、「平和に関する布告」などを発した。",year: 1917,region: "europe",cat: "事件・戦争",rank: 3,course: ["sogo","tankyu"],related: ["レーニン","トロツキー","ボリシェヴィキ","ロシア革命"]},
  {term: "千人隊",yomi: "せんにんたい",def: "1860年、ガリバルディが組織した義勇軍。赤シャツを着ていたことから赤シャツ隊ともよばれる。シチリア島と南イタリアの両シチリア王国を征服した。",year: 1860,region: "europe",cat: "組織・運動",rank: 2,course: ["tankyu"],related: ["ガリバルディ","両シチリア王国","イタリア統一"]},
  {term: "千人隊（赤シャツ隊）",yomi: "せんにんたい",def: "ガリバルディが率いた約千人の義勇軍。1860年に両シチリア王国を征服し、その占領地をサルデーニャ王ヴィットーリオ=エマヌエーレ2世に献上して、イタリア統一を前進させた。",year: 1860,region: "europe",cat: "組織・運動",rank: 2,course: ["tankyu"],related: ["ガリバルディ","両シチリア王国","ヴィットーリオ=エマヌエーレ2世"]},
  {term: "千夜一夜物語",yomi: "せんやいちやものがたり",def: "インド・イラン・アラビアなどの説話を集めたアラビア語の物語集（『アラビアン=ナイト』）。アッバース朝のハールーン=アッラシードの時代を舞台にした話も多く、16世紀ごろ現在の形にまとまった。",region: "west",cat: "文化・学問",rank: 2,course: ["tankyu"],related: ["ハールーン=アッラシード","アッバース朝","イスラーム文化"]},
  {term: "千戸制",yomi: "せんこせい",def: "チンギス=カンが創設したモンゴル帝国の軍事・行政制度。遊牧民を千戸単位の集団に編成し、それぞれ一定数の兵士を出させた。千戸の長には功臣を任命した。",year: 1206,region: "inner",cat: "制度・政策",rank: 3,course: ["tankyu"],related: ["チンギス=カン","モンゴル帝国","クリルタイ"]},
  {term: "半両銭",yomi: "はんりょうせん",def: "秦の始皇帝が全国に統一した円形方孔の銅銭。それまで各国で異なっていた貨幣を統一し、この形式は後の中国の貨幣の基本となった。",region: "east",cat: "経済・社会",rank: 2,course: ["tankyu"],related: ["始皇帝","度量衡の統一","秦"]},
  {term: "南アフリカ共和国",yomi: "みなみあふりかきょうわこく",def: "1961年、南アフリカ連邦がイギリス連邦を離脱して成立した共和国。白人政権がアパルトヘイトを推進したが、国際的批判を受けて1991年に撤廃され、1994年にマンデラが大統領となった。",year: 1961,region: "africa",cat: "国家・王朝",rank: 3,course: ["sogo","tankyu"],related: ["アパルトヘイト","マンデラ","南アフリカ連邦"]},
  {term: "南アフリカ戦争",yomi: "みなみあふりかせんそう",def: "1899〜1902年、イギリスがブール人（アフリカーナー）のトランスヴァール共和国・オレンジ自由国を攻撃した戦争。金・ダイヤモンドの産地を得たが、苦戦し国際的に孤立した。",year: 1899,end: 1902,region: "africa",cat: "事件・戦争",rank: 3,course: ["sogo","tankyu"],related: ["ブール人","セシル=ローズ","ジョゼフ=チェンバレン","南アフリカ連邦"]},
  {term: "南スラヴ人",yomi: "みなみすらゔじん",def: "バルカン半島に住むスラヴ人。セルビア人・クロアティア人・スロヴェニア人などをさし、ギリシア正教を受けいれた人々とカトリックを受けいれた人々に分かれた。第一次世界大戦後、ユーゴスラヴィアを建てた。",region: "europe",cat: "経済・社会",rank: 2,course: ["tankyu"],related: ["セルビア","ユーゴスラヴィア","パン=スラヴ主義"]},
  {term: "南スーダン",yomi: "みなみすーだん",def: "2011年、住民投票の結果スーダンから分離独立したアフリカの国。北部との長い内戦をへて独立したが、独立後も国内で内戦が起こった。",year: 2011,region: "africa",cat: "国家・王朝",rank: 1,course: ["sogo","tankyu"],related: ["住民投票","スーダン","内戦"]},
  {term: "南ベトナム解放民族戦線",yomi: "みなみべとなむかいほうみんぞくせんせん",def: "1960年、南ベトナムのゴ=ディン=ジエム政権とアメリカの介入に反対して結成された組織。北ベトナムの支援を受けてゲリラ戦を展開し、ベトナム戦争の主要な勢力となった。",year: 1960,region: "sea",cat: "組織・運動",rank: 3,course: ["tankyu"],related: ["ベトナム戦争","ベトナム共和国","ベトナム民主共和国"]},
  {term: "南下政策",yomi: "なんかせいさく",def: "不凍港を求め、黒海・地中海、中央アジア・東アジア方面へ進出しようとしたロシアの対外政策。クリミア戦争やロシア=トルコ戦争で英仏などと対立し、東アジアでは日露戦争をまねいた。",region: "europe",cat: "制度・政策",rank: 3,course: ["sogo","tankyu"],related: ["ロシア=トルコ戦争","クリミア戦争","東方問題"]},
  {term: "南京事件",yomi: "なんきんじけん",def: "1937年、日中戦争で日本軍が南京を占領した際に、捕虜や民間人を多数殺害し、略奪や暴行を行った事件。国際的な非難を受けた。",year: 1937,region: "east",cat: "事件・戦争",rank: 3,course: ["sogo","tankyu"],related: ["日中戦争","国家総動員法","重慶"]},
  {term: "南京国民政府",yomi: "なんきんこくみんせいふ",def: "1927年、上海クーデタ後に蔣介石が南京に建てた国民党の政府。北伐を完成して中国をほぼ統一し、関税自主権の回復や通貨統一などを進めた。",year: 1927,end: 1937,region: "east",cat: "国家・王朝",rank: 3,course: ["sogo","tankyu"],related: ["蔣介石","北伐","上海クーデタ","中国国民党"]},
  {term: "南京条約",yomi: "なんきんじょうやく",def: "1842年、アヘン戦争の講和条約。清は香港島をイギリスに割譲し、上海・広州など5港を開港し、公行の廃止と賠償金の支払いを認めた。翌年の追加条約で領事裁判権なども認めた。",year: 1842,region: "east",cat: "条約・宣言",rank: 3,course: ["sogo","tankyu"],related: ["アヘン戦争","林則徐","公行","不平等条約"]},
  {term: "南北分裂",yomi: "なんぼくぶんれつ",def: "1世紀半ば、匈奴が南北に分裂したこと。南匈奴は後漢に服属して長城内に移住し、のちの五胡の一つとなった。北匈奴は後漢に攻撃されて西方へ移動した。",year: 48,region: "inner",cat: "事件・戦争",rank: 1,course: ["tankyu"],related: ["匈奴","後漢","五胡"]},
  {term: "南北問題",yomi: "なんぼくもんだい",def: "北半球に多い先進工業国と、南半球に多い発展途上国との間の経済格差の問題。1960年代から注目され、国連貿易開発会議（UNCTAD）などで是正がはかられた。",year: 1960,region: "africa",cat: "経済・社会",rank: 3,course: ["sogo","tankyu"],related: ["南南問題","国連貿易開発会議（UNCTAD）","第三世界"]},
  {term: "南北戦争",yomi: "なんぼくせんそう",def: "1861〜65年、奴隷制や貿易政策をめぐって対立したアメリカの北部と南部の内戦。南部はアメリカ連合国をつくったが、リンカン大統領の指導する北部が勝利し、奴隷制が廃止された。",year: 1861,end: 1865,region: "america",cat: "事件・戦争",rank: 3,course: ["sogo","tankyu"],related: ["リンカン","奴隷解放宣言","共和党","アメリカ連合国"]},
  {term: "南北統一",yomi: "なんぼくとういつ",def: "1975年のサイゴン陥落でベトナム戦争が終わった後、1976年に南北ベトナムが統一され、ベトナム社会主義共和国が成立したこと。",year: 1976,region: "sea",cat: "事件・戦争",rank: 1,course: ["tankyu"],related: ["ベトナム戦争","ベトナム社会主義共和国","サイゴン陥落"]},
  {term: "南宋",yomi: "なんそう",def: "1127年、靖康の変で北宋が滅んだのち、高宗が江南に再建した宋の王朝。都は臨安（杭州）。金と和議を結んで淮河を国境とした。江南の開発が進んだが、1276年に元に臨安を占領された。",year: 1127,end: 1276,region: "east",cat: "国家・王朝",rank: 3,course: ["tankyu"],related: ["靖康の変","臨安","朱子学","金"]},
  {term: "南宋の滅亡",yomi: "なんそうのめつぼう",def: "1276年に元のクビライの軍が臨安を占領し、1279年に南宋の残存勢力が厓山の戦いで滅んだこと。これにより元が中国全土を支配した。",year: 1279,region: "east",cat: "事件・戦争",rank: 1,course: ["tankyu"],related: ["クビライ","元","南宋"]},
  {term: "南巡講話",yomi: "なんじゅんこうわ",def: "1992年、鄧小平が深圳などの南方を視察して改革・開放の加速を呼びかけた談話。天安門事件後に停滞していた経済改革が再び進み、社会主義市場経済の路線が確立した。",year: 1992,region: "east",cat: "事件・戦争",rank: 2,course: ["tankyu"],related: ["鄧小平","改革・開放政策","社会主義市場経済"]},
  {term: "南朝",yomi: "なんちょう",def: "東晋の後に江南で興亡した宋・斉・梁・陳の4王朝。都はいずれも建康。貴族が政治・文化の担い手となり、六朝文化が栄えた。589年に隋に滅ぼされた。",year: 420,end: 589,region: "east",cat: "国家・王朝",rank: 3,course: ["tankyu"],related: ["宋（南朝）","建康","六朝文化","北朝"]},
  {term: "南海遠征",yomi: "なんかいえんせい",def: "明の永楽帝の命で、鄭和が7回にわたっておこなった大艦隊の遠征。東南アジア・インド洋からアフリカ東岸まで達し、多くの国に朝貢をうながした。",year: 1405,end: 1433,region: "east",cat: "事件・戦争",rank: 3,course: ["tankyu"],related: ["鄭和","永楽帝","宝船"]},
  {term: "南海郡",yomi: "なんかいぐん",def: "秦の始皇帝が華南を征服して置いた郡の一つ。現在の広州付近が中心で、秦末の混乱のなかでこの地の役人趙佗が自立し、南越国を建てた。",year: -214,region: "east",cat: "地名・地域",rank: 1,course: ["tankyu"],related: ["秦","南越","始皇帝"]},
  {term: "南詔",yomi: "なんしょう",def: "8世紀、雲南地方にチベット=ビルマ系の人々が建てた国。唐の冊封を受け、吐蕃と唐の間で勢力を保った。仏教が栄え、のちに大理国にかわった。",year: 738,end: 902,region: "east",cat: "国家・王朝",rank: 2,course: ["tankyu"],related: ["吐蕃","唐","大理"]},
  {term: "南進",yomi: "なんしん",def: "ベトナムの諸王朝が南へ領土を広げていったこと。黎朝は15世紀にチャンパーを攻撃して領土を拡大し、のち阮氏がメコン=デルタまで進出した。",region: "sea",cat: "事件・戦争",rank: 1,course: ["tankyu"],related: ["黎朝","チャンパー","大越"]},
  {term: "占城",yomi: "せんじょう",def: "チャンパーに対する中国側の呼び名。ベトナム中南部に栄えたチャム人の国で、ここから伝わった早稲種の占城稲は宋代の江南の稲作を発展させた。",region: "sea",cat: "国家・王朝",rank: 1,course: ["tankyu"],related: ["チャンパー","占城稲","大越"]},
  {term: "占田・課田法",yomi: "せんでん・かでんほう",def: "西晋の司馬炎（武帝）が実施したとされる土地制度。土地の所有に限度を設け、それに応じて課税したと考えられる。豪族の大土地所有を抑えるのが目的であった。",year: 280,region: "east",cat: "制度・政策",rank: 2,course: ["tankyu"],related: ["西晋","司馬炎","均田制"]},
  {term: "占領",yomi: "せんりょう",def: "第二次世界大戦後、日本が連合国軍に占領されたこと。マッカーサーを最高司令官とする GHQ のもとで、非軍事化と民主化の改革が進められ、1952年のサンフランシスコ平和条約発効で終わった。",year: 1945,end: 1952,region: "east",cat: "制度・政策",rank: 2,course: ["sogo"],related: ["GHQ","マッカーサー","サンフランシスコ平和条約"]},
  {term: "印パ分離独立",yomi: "いんぱぶんりどくりつ",def: "1947年、インドがヒンドゥー教徒中心のインド連邦とムスリム中心のパキスタンに分かれて独立したこと。宗教対立で多数の死者と難民が出て、カシミールの帰属問題も残った。",year: 1947,region: "south",cat: "事件・戦争",rank: 3,course: ["sogo","tankyu"],related: ["ジンナー","ガンディー","カシミール"]},
  {term: "印紙法",yomi: "いんしほう",def: "1765年、イギリスが北アメリカ植民地に新聞・証書などへの印紙の貼付を義務づけた法律。七年戦争後の財政難が背景にあった。植民地は「代表なくして課税なし」と反対し、翌年撤廃された。",year: 1765,region: "america",cat: "制度・政策",rank: 3,course: ["sogo","tankyu"],related: ["代表なくして課税なし","七年戦争","13植民地"]},
  {term: "原子爆弾",yomi: "げんしばくだん",def: "核分裂の膨大なエネルギーを利用した兵器。アメリカがマンハッタン計画で開発し、1945年8月、トルーマン大統領のもとで広島と長崎に投下され、多くの市民が犠牲となった。",year: 1945,region: "east",cat: "文化・学問",rank: 3,course: ["sogo","tankyu"],related: ["トルーマン","広島","長崎","核兵器"]},
  {term: "原敬",yomi: "はらたかし",def: "大正時代の政治家。米騒動の後の1918年、立憲政友会の総裁として初の本格的な政党内閣を組織した。「平民宰相」とよばれたが、1921年に暗殺された。",year: 1918,region: "east",cat: "人物",rank: 2,course: ["sogo"],related: ["政党内閣","大正デモクラシー","米騒動"]},
  {term: "反ファシスト人民自由連盟",yomi: "はんふぁしすとじんみんじゆうれんめい",def: "1944年、アウン=サンらがビルマで結成した抗日の統一組織。戦後はイギリスからの独立運動を主導し、1948年にビルマは独立した。",year: 1944,region: "sea",cat: "組織・運動",rank: 1,course: ["tankyu"],related: ["アウン=サン","ビルマ","タキン党"]},
  {term: "反清復明",yomi: "はんしんふくみん",def: "清に抵抗し、明の復興をめざす運動のスローガン。鄭成功は台湾を拠点にこれを掲げて清に抵抗した。のちの秘密結社にも受けつがれた。",region: "east",cat: "思想・宗教",rank: 1,course: ["tankyu"],related: ["鄭成功","台湾","清"]},
  {term: "叙任権闘争",yomi: "じょにんけんとうそう",def: "聖職者を任命する権利（叙任権）をめぐる、ローマ教皇と神聖ローマ皇帝の争い。グレゴリウス7世とハインリヒ4世の対立ではカノッサの屈辱が起こり、1122年のヴォルムス協約で妥協が成立した。",year: 1075,end: 1122,region: "europe",cat: "事件・戦争",rank: 3,course: ["tankyu"],related: ["グレゴリウス7世","ハインリヒ4世","カノッサの屈辱","ヴォルムス協約"]},
  {term: "古典派経済学",yomi: "こてんはけいざいがく",def: "アダム=スミスに始まる経済学。重商主義を批判し、自由な経済活動が社会全体の富を増大させると説いた。マルサス・リカードらが発展させた。",region: "europe",cat: "文化・学問",rank: 2,course: ["tankyu"],related: ["アダム=スミス","国富論","自由放任"]},
  {term: "可汗",yomi: "かかん",def: "柔然・突厥・ウイグルなど北方の遊牧国家の君主の称号。5世紀の柔然が用いたのが最初とされ、モンゴル帝国でも「ハン」「カン」として用いられた。",region: "inner",cat: "制度・政策",rank: 2,course: ["tankyu"],related: ["柔然","突厥","ウイグル","天可汗"]},
  {term: "台湾",yomi: "たいわん",def: "中国大陸の東南沖の島。17世紀にオランダ、ついで鄭成功が拠点とし、1683年に清が領有した。下関条約で日本領となり、第二次世界大戦後は国共内戦に敗れた国民党政府が移った。",region: "east",cat: "地名・地域",rank: 3,course: ["sogo","tankyu"],related: ["鄭成功","康熙帝","下関条約","中華民国"]},
  {term: "台湾総督府",yomi: "たいわんそうとくふ",def: "下関条約で台湾を得た日本が、1895年に台北に置いた統治機関。抵抗運動を鎮圧し、土地調査や鉄道建設などを進めて植民地支配をおこなった。",year: 1895,end: 1945,region: "east",cat: "組織・運動",rank: 2,course: ["sogo","tankyu"],related: ["下関条約","植民地","台湾"]},
  {term: "史記",yomi: "しき",def: "前漢の司馬遷が著した歴史書。伝説の黄帝から武帝の時代までを、本紀・列伝などからなる紀伝体で記した。以後、中国の正史の模範となった。",region: "east",cat: "文化・学問",rank: 3,course: ["tankyu"],related: ["司馬遷","紀伝体","前漢"]},
  {term: "司馬光",yomi: "しばこう",def: "北宋の政治家・歴史家。旧法党の中心として王安石の新法に反対し、のち宰相となって新法を廃止した。編年体の歴史書『資治通鑑』を著した。",year: 1019,end: 1086,region: "east",cat: "人物",rank: 2,course: ["tankyu"],related: ["資治通鑑","王安石","旧法党"]},
  {term: "司馬炎",yomi: "しばえん",def: "西晋の初代皇帝（武帝）。265年に魏の帝位を奪って晋を建て、280年に呉を滅ぼして中国を統一した。占田・課田法を定めたとされる。",year: 265,end: 290,region: "east",cat: "人物",rank: 2,course: ["tankyu"],related: ["西晋","魏","占田・課田法"]},
  {term: "司馬睿",yomi: "しばえい",def: "東晋の初代皇帝（元帝）。西晋の皇族で、西晋が匈奴に滅ぼされた後、江南の豪族や華北からの亡命貴族の支持を得て、317年に建康で晋を再興した。",year: 317,region: "east",cat: "人物",rank: 1,course: ["tankyu"],related: ["東晋","建康","西晋"]},
  {term: "合理論",yomi: "ごうりろん",def: "理性による推論を重視し、確実な原理から演繹的に真理を導こうとする哲学の立場。デカルトに始まり、スピノザ・ライプニッツらが受けついだ。イギリスの経験論と対比される。",region: "europe",cat: "思想・宗教",rank: 2,course: ["tankyu"],related: ["デカルト","演繹法","経験論"]},
  {term: "合衆国憲法",yomi: "がっしゅうこくけんぽう",def: "1787年、フィラデルフィアの憲法制定会議で制定されたアメリカ合衆国の憲法。人民主権・連邦主義・三権分立を原則とし、成文憲法として世界の近代憲法に影響をあたえた。",year: 1787,region: "america",cat: "条約・宣言",rank: 3,course: ["sogo","tankyu"],related: ["三権分立","連邦主義","ワシントン"]},
  {term: "同君連合",yomi: "どうくんれんごう",def: "別々の国家が同一の君主をいただくこと。14世紀のポーランド・リトアニア、カルマル同盟による北欧3国、1603年以降のイングランドとスコットランドなどがその例である。",region: "europe",cat: "制度・政策",rank: 1,course: ["tankyu"],related: ["ポーランド","リトアニア","スコットランド"]},
  {term: "同害復讐",yomi: "どうがいふくしゅう",def: "「目には目を、歯には歯を」とする刑罰の原則。ハンムラビ法典にみられ、受けた害と同じ程度の報復を認めたが、身分によって刑罰に差があった。",region: "west",cat: "思想・宗教",rank: 2,course: ["tankyu"],related: ["ハンムラビ法典","ハンムラビ王"]},
  {term: "同時多発テロ事件",yomi: "どうじたはつてろじけん",def: "2001年9月11日、ハイジャックされた旅客機がニューヨークの世界貿易センタービルなどに突入したテロ事件。アメリカは対テロ戦争を掲げ、アフガニスタンを攻撃した。",year: 2001,region: "america",cat: "事件・戦争",rank: 3,course: ["sogo","tankyu"],related: ["アフガニスタン攻撃","イラク戦争","対テロ戦争"]},
  {term: "同治帝",yomi: "どうちてい",def: "清の第10代皇帝。幼くして即位し、母の西太后が実権をにぎった。この時期は太平天国の鎮圧や洋務運動による「同治の中興」とよばれる。",year: 1861,end: 1875,region: "east",cat: "人物",rank: 1,course: ["tankyu"],related: ["西太后","同治の中興","洋務運動"]},
  {term: "名誉革命",yomi: "めいよかくめい",def: "1688〜89年、イギリス議会がジェームズ2世を追放し、ウィリアム3世とメアリ2世を王に迎えた革命。流血なく進み、権利の章典の制定により立憲君主政の基礎が確立した。",year: 1688,region: "europe",cat: "事件・戦争",rank: 3,course: ["sogo","tankyu"],related: ["権利の章典","ウィリアム3世","メアリ2世","ロック"]},
  {term: "吐蕃",yomi: "とばん",def: "7世紀にソンツェン=ガンポが建てたチベットの統一国家。都はラサ。インド系の文字をもとにチベット文字をつくり、仏教とボン教が融合したチベット仏教が成立した。唐と争った。",region: "inner",cat: "国家・王朝",rank: 3,course: ["tankyu"],related: ["ソンツェン=ガンポ","ラサ","チベット仏教"]},
  {term: "呉越の争い",yomi: "ごえつのあらそい",def: "春秋時代末期、長江下流域の呉と越が覇権を争ったこと。越王勾践が呉に敗れたのち国力を回復し、前473年に呉を滅ぼした。「呉越同舟」「臥薪嘗胆」の語源となった。",region: "east",cat: "事件・戦争",rank: 1,course: ["tankyu"],related: ["勾践","会稽","臥薪嘗胆"]},
  {term: "周（武周）",yomi: "しゅう",def: "則天武后が唐にかわって建てた王朝。690年に自ら皇帝となり国号を周とした。中国史上唯一の女帝の王朝で、705年に唐が復活した。",year: 690,end: 705,region: "east",cat: "国家・王朝",rank: 2,course: ["tankyu"],related: ["則天武后","唐","女帝"]},
  {term: "咸臨丸",yomi: "かんりんまる",def: "江戸幕府の軍艦。1860年、日米修好通商条約の批准書交換のための使節に随行して太平洋を横断した。勝海舟が艦長格で、福沢諭吉も乗船した。",year: 1860,region: "east",cat: "文化・学問",rank: 1,course: ["sogo"],related: ["福沢諭吉","日米修好通商条約","勝海舟"]},
  {term: "咸陽",yomi: "かんよう",def: "戦国時代の秦と、統一王朝秦の都。商鞅の改革期に遷都され、始皇帝は阿房宮などの宮殿を造営した。秦の滅亡時に項羽によって焼かれた。",region: "east",cat: "地名・地域",rank: 2,course: ["tankyu"],related: ["秦","始皇帝","商鞅"]},
  {term: "哲人政治",yomi: "てつじんせいじ",def: "プラトンが『国家』で理想とした政治。善のイデアを認識した哲学者が統治者となるか、統治者が哲学を学ぶべきだと説き、衆愚政治を批判した。",region: "europe",cat: "思想・宗教",rank: 1,course: ["tankyu"],related: ["プラトン","国家","イデア"]},
  {term: "哲学書簡",yomi: "てつがくしょかん",def: "ヴォルテールがイギリス滞在の経験をもとに著した書物（『イギリス便り』）。イギリスの政治的自由や宗教的寛容を紹介し、フランスの絶対王政と教会を批判した。",year: 1734,region: "europe",cat: "文化・学問",rank: 1,course: ["tankyu"],related: ["ヴォルテール","啓蒙思想"]},
  {term: "唐の太宗",yomi: "とうのたいそう",def: "唐の第2代皇帝（李世民）。父李淵を助けて唐を建国し、律令や三省六部などの制度を整えた。東突厥を服属させて「天可汗」とよばれ、その治世は「貞観の治」とたたえられた。",year: 626,end: 649,region: "east",cat: "人物",rank: 3,course: ["tankyu"],related: ["貞観の治","李世民","三省六部","東突厥"]},
  {term: "唐招提寺",yomi: "とうしょうだいじ",def: "奈良にある寺院。唐から6度目の渡航で来日した僧鑑真が、759年に戒律を学ぶ道場として創建した。金堂は奈良時代の建築を伝える。",year: 759,region: "east",cat: "文化・学問",rank: 1,course: ["sogo","tankyu"],related: ["鑑真","奈良時代","仏教"]},
  {term: "唐詩",yomi: "とうし",def: "唐代に盛んになった漢詩。盛唐の李白・杜甫、中唐の白居易らが代表的な詩人で、律詩・絶句などの形式が完成し、中国文学の黄金期を築いた。",region: "east",cat: "文化・学問",rank: 3,course: ["tankyu"],related: ["李白","杜甫","白居易"]},
  {term: "商業革命",yomi: "しょうぎょうかくめい",def: "大航海時代により、ヨーロッパの商業の中心が地中海から大西洋岸に移ったこと。北イタリア諸都市にかわり、リスボンやアントウェルペンが繁栄し、世界的な商業圏が形成された。",region: "europe",cat: "経済・社会",rank: 3,course: ["tankyu"],related: ["大航海時代","価格革命","リスボン","アントウェルペン"]},
  {term: "商鞅",yomi: "しょうおう",def: "戦国時代の秦の政治家で法家。孝公に仕えて法による厳しい統治や郡県制などの改革（変法）を進め、秦の富国強兵の基礎を築いた。",year: -338,region: "east",cat: "人物",rank: 3,course: ["tankyu"],related: ["秦","法家","咸陽","郡県制"]},
  {term: "問答法",yomi: "もんどうほう",def: "ソクラテスが真理を探究するために用いた方法。対話を通じて相手に自分の無知を自覚させ（無知の知）、普遍的な真理に導こうとした。",region: "europe",cat: "思想・宗教",rank: 1,course: ["tankyu"],related: ["ソクラテス","無知の知","ソフィスト"]},
  {term: "啓蒙専制君主",yomi: "けいもうせんせいくんしゅ",def: "18世紀、啓蒙思想の影響を受けて、上からの改革で国の近代化をはかった君主。プロイセンのフリードリヒ2世、ロシアのエカチェリーナ2世、オーストリアのヨーゼフ2世らが代表である。",region: "europe",cat: "人物",rank: 3,course: ["tankyu"],related: ["フリードリヒ2世","エカチェリーナ2世","ヨーゼフ2世"]},
  {term: "啓蒙思想",yomi: "けいもうしそう",def: "理性を重んじ、旧来の偏見や迷信、絶対王政などの不合理な制度を批判した18世紀ヨーロッパの思想。モンテスキュー・ヴォルテール・ルソーらが代表で、アメリカ独立革命やフランス革命に影響をあたえた。",region: "europe",cat: "思想・宗教",rank: 3,course: ["sogo","tankyu"],related: ["モンテスキュー","ヴォルテール","ルソー","百科全書"]},
  {term: "善隣外交",yomi: "ぜんりんがいこう",def: "フランクリン=ローズヴェルト大統領がとった、ラテンアメリカ諸国に対する外交政策。武力干渉をひかえ、キューバの独立を承認するなど友好関係を深めて経済的結びつきを強めた。",year: 1933,region: "america",cat: "制度・政策",rank: 2,course: ["tankyu"],related: ["フランクリン=ローズヴェルト","ニューディール","ラテンアメリカ"]},
  {term: "喜望峰",yomi: "きぼうほう",def: "アフリカ大陸南端近くの岬。1488年にポルトガルのバルトロメウ=ディアスが到達し、1498年にはヴァスコ=ダ=ガマがここを回ってインドに達した。",year: 1488,region: "africa",cat: "地名・地域",rank: 3,course: ["tankyu"],related: ["バルトロメウ=ディアス","ヴァスコ=ダ=ガマ","インド航路"]},
  {term: "四つの口",yomi: "よっつのくち",def: "江戸時代、幕府が外交・貿易の窓口とした4つの場所。長崎（オランダ・中国）、対馬（朝鮮）、薩摩（琉球）、松前（アイヌ）をさす。",region: "east",cat: "制度・政策",rank: 1,course: ["sogo"],related: ["鎖国","長崎","対馬","薩摩"]},
  {term: "四国同盟",yomi: "しこくどうめい",def: "1815年、イギリス・ロシア・オーストリア・プロイセンが結んだ同盟。ウィーン体制を維持するためのもので、1818年にフランスが加わり五国同盟となった。",year: 1815,region: "europe",cat: "条約・宣言",rank: 2,course: ["tankyu"],related: ["メッテルニヒ","ウィーン体制","神聖同盟"]},
  {term: "四帝分治制",yomi: "していぶんちせい",def: "ディオクレティアヌス帝が導入した統治体制（テトラルキア）。帝国を東西に分け、それぞれに正帝と副帝を置いて4人の皇帝が分担して統治した。",year: 293,region: "europe",cat: "制度・政策",rank: 2,course: ["tankyu"],related: ["ディオクレティアヌス帝","専制君主政","ローマ帝国の東西分裂"]},
  {term: "四庫全書",yomi: "しこぜんしょ",def: "清の乾隆帝の命で編纂された叢書。中国の古今の書物を経・史・子・集の4部に分類して集めた。同時に清に不都合な書物は禁書とされた。",year: 1782,region: "east",cat: "文化・学問",rank: 3,course: ["tankyu"],related: ["乾隆帝","文字の獄","康熙字典"]},
  {term: "四書",yomi: "ししょ",def: "儒学の基本経典である『大学』『中庸』『論語』『孟子』。南宋の朱熹（朱子）が重視して注釈をつけ、のち科挙の基本テキストとなった。",region: "east",cat: "文化・学問",rank: 2,course: ["tankyu"],related: ["朱熹","朱子学","五経"]},
  {term: "四諦",yomi: "したい",def: "ブッダが説いた4つの真理（苦・集・滅・道）。人生は苦であり、その原因は執着にあり、執着をなくせば苦は消え、そのためには八正道を実践すべきだとする。",region: "south",cat: "思想・宗教",rank: 1,course: ["tankyu"],related: ["仏教","八正道","ガウタマ=シッダールタ"]},
  {term: "四面楚歌",yomi: "しめんそか",def: "前202年、垓下の戦いで劉邦の軍に包囲された項羽が、四方から楚の歌が聞こえるのを聞いて楚の人々も降伏したと嘆いた故事。周りが敵ばかりで孤立することのたとえとなった。",year: -202,region: "east",cat: "事件・戦争",rank: 1,course: ["tankyu"],related: ["劉邦","項羽","前漢"]},
  {term: "囲い込み",yomi: "かこいこみ",def: "イギリスで開放耕地などを垣根で囲い、私有地とした動き。16世紀には牧羊のため、18世紀には議会の承認のもとで穀物増産のため行われた。土地を失った農民は都市の労働者となった。",region: "europe",cat: "経済・社会",rank: 3,course: ["tankyu"],related: ["第2次囲い込み","農業革命","産業革命","毛織物"]},
  {term: "国共内戦",yomi: "こっきょうないせん",def: "第二次世界大戦後の1946年から始まった、国民党と共産党の内戦。農民の支持を得た共産党が勝利し、1949年に中華人民共和国が成立した。国民党は台湾に逃れた。",year: 1946,end: 1949,region: "east",cat: "事件・戦争",rank: 3,course: ["sogo","tankyu"],related: ["中国国民党","中国共産党","中華人民共和国"]},
  {term: "国共合作",yomi: "こっきょうがっさく",def: "中国国民党と中国共産党の協力関係。1924年の第1次国共合作は上海クーデタで崩壊した。1937年に西安事件をきっかけに第2次国共合作が成立し、抗日民族統一戦線がつくられた。",year: 1924,region: "east",cat: "制度・政策",rank: 3,course: ["sogo","tankyu"],related: ["孫文","蔣介石","西安事件","抗日民族統一戦線"]},
  {term: "国家",yomi: "こっか",def: "プラトンの主著の一つ。正義とは何かをソクラテスの対話の形で問い、善のイデアを知る哲学者が統治する哲人政治を理想の国家として論じた。",region: "europe",cat: "文化・学問",rank: 1,course: ["tankyu"],related: ["プラトン","哲人政治","イデア"]},
  {term: "国家総動員法",yomi: "こっかそうどういんほう",def: "1938年、日中戦争の長期化を受けて日本で制定された法律。政府が議会の承認なしに、戦争遂行のために国民や物資を動員できるようにした。",year: 1938,region: "east",cat: "制度・政策",rank: 3,course: ["sogo"],related: ["日中戦争","総力戦","大政翼賛会"]},
  {term: "国富論",yomi: "こくふろん",def: "アダム=スミスが1776年に著した経済学書（『諸国民の富』）。重商主義を批判し、自由な経済活動によって国の富が増大すると説いて、古典派経済学の基礎となった。",year: 1776,region: "europe",cat: "文化・学問",rank: 3,course: ["tankyu"],related: ["アダム=スミス","古典派経済学","自由放任"]},
  {term: "国民主権",yomi: "こくみんしゅけん",def: "国の政治のあり方を最終的に決める権力（主権）は国民にあるとする原理。アメリカ独立宣言やフランス人権宣言で示され、近代憲法の基本原理となった。",region: "europe",cat: "思想・宗教",rank: 3,course: ["sogo","tankyu"],related: ["人権宣言","人民主権","合衆国憲法"]},
  {term: "国民保険法",yomi: "こくみんほけんほう",def: "1911年、イギリスの自由党政権の財務大臣ロイド=ジョージのもとで制定された法律。労働者のための健康保険と失業保険を導入し、社会保障制度の基礎となった。",year: 1911,region: "europe",cat: "制度・政策",rank: 2,course: ["tankyu"],related: ["ロイド=ジョージ","自由党","社会保障"]},
  {term: "国民党",yomi: "こくみんとう",def: "1912年、中国同盟会を中心に宋教仁らが結成した政党。国会選挙で第一党となったが、袁世凱によって解散させられた。のち孫文が中国国民党として再建した。",year: 1912,region: "east",cat: "組織・運動",rank: 2,course: ["sogo","tankyu"],related: ["中国国民党","孫文","宋教仁"]},
  {term: "国民公会",yomi: "こくみんこうかい",def: "1792年、男子普通選挙によって成立したフランス革命期の議会。王政を廃止して第一共和政を宣言し、ルイ16世を処刑した。ジャコバン派の恐怖政治をへて、1795年に総裁政府にかわった。",year: 1792,end: 1795,region: "europe",cat: "組織・運動",rank: 3,course: ["tankyu"],related: ["ロベスピエール","第一共和政","ジャコバン派"]},
  {term: "国民国家",yomi: "こくみんこっか",def: "国民としての一体感を共有する人々によって構成される国家。フランス革命以降に形成が進み、学校教育や徴兵制、国語の普及などを通じて国民意識がつくられた。",region: "europe",cat: "制度・政策",rank: 3,course: ["sogo","tankyu"],related: ["ナショナリズム","主権国家","学校教育"]},
  {term: "国王派",yomi: "こくおうは",def: "アメリカ独立戦争の際、イギリス本国に忠誠を誓い、独立に反対した植民地の人々（ロイヤリスト）。戦後、その多くはカナダなどに移住した。",region: "america",cat: "組織・運動",rank: 1,course: ["sogo","tankyu"],related: ["国王派（ロイヤリスト）","アメリカ独立戦争","愛国派"]},
  {term: "国際分業",yomi: "こくさいぶんぎょう",def: "各国が得意な産業に特化し、貿易によって製品を交換し合うこと。19世紀にはイギリスが工業製品を、ほかの地域が原料・食料を供給する国際分業体制がつくられた。",region: "europe",cat: "経済・社会",rank: 2,course: ["tankyu"],related: ["世界市場","自由貿易","産業革命"]},
  {term: "国際協調",yomi: "こくさいきょうちょう",def: "第一次世界大戦後の1920年代、国際連盟を中心に軍縮や紛争の平和的解決をめざした動き。ワシントン会議、ロカルノ条約、不戦条約などがその例で、世界恐慌後にくずれた。",year: 1920,region: "europe",cat: "制度・政策",rank: 2,course: ["sogo"],related: ["国際連盟","ワシントン会議","不戦条約","ロカルノ条約"]},
  {term: "国際連合",yomi: "こくさいれんごう",def: "1945年、国際連合憲章にもとづき51か国で発足した国際平和機構。本部はニューヨーク。安全保障理事会の常任理事国に拒否権をあたえ、軍事制裁も可能とするなど、国際連盟の反省に立った。",year: 1945,region: "america",cat: "組織・運動",rank: 3,course: ["sogo","tankyu"],related: ["大西洋憲章","安全保障理事会","国際連合憲章","国際連盟"]},
  {term: "国際連合加盟",yomi: "こくさいれんごうかめい",def: "日本が1956年に国際連合に加盟したこと。それまではソ連の拒否権で阻まれていたが、日ソ共同宣言でソ連と国交を回復したことで実現した。",year: 1956,region: "east",cat: "事件・戦争",rank: 2,course: ["sogo"],related: ["日ソ共同宣言","国際連合","鳩山一郎"]},
  {term: "国際連盟",yomi: "こくさいれんめい",def: "1920年、ウィルソンの提唱にもとづき発足した初の国際平和機構。本部はジュネーヴ。アメリカは不参加で、制裁手段も経済制裁に限られたため、紛争の防止に十分な力をもたなかった。",year: 1920,end: 1946,region: "europe",cat: "組織・運動",rank: 3,course: ["sogo","tankyu"],related: ["ウィルソン","十四か条","ヴェルサイユ条約","国際連合"]},
  {term: "国際連盟脱退",yomi: "こくさいれんめいだったい",def: "1933年、国際連盟が満州国を承認せず日本軍の撤退を勧告したことに反発し、日本が連盟を脱退したこと。同年にはドイツも脱退した。",year: 1933,region: "east",cat: "事件・戦争",rank: 3,course: ["sogo","tankyu"],related: ["リットン調査団","満州国","松岡洋右"]},
  {term: "国風文化",yomi: "こくふうぶんか",def: "10〜11世紀、平安時代の日本で栄えた、日本の風土や生活に合った貴族文化。遣唐使の停止後も大陸の影響を消化しつつ、かな文字や『源氏物語』などが生まれた。",region: "east",cat: "文化・学問",rank: 1,course: ["sogo"],related: ["かな文字","遣唐使","平安時代"]},
  {term: "土木の変",yomi: "どぼくのへん",def: "1449年、オイラトのエセンが明に侵入し、土木堡で明の正統帝を捕虜とした事件。以後、明は北方で守勢に転じ、長城を修築した。",year: 1449,region: "east",cat: "事件・戦争",rank: 3,course: ["tankyu"],related: ["エセン","オイラト","正統帝","北虜南倭"]},
  {term: "地動説",yomi: "ちどうせつ",def: "地球が太陽のまわりを回っているとする説。コペルニクスがとなえ、ケプラーやガリレイが支持・発展させた。教会の支持する天動説と対立した。",year: 1543,region: "europe",cat: "文化・学問",rank: 3,course: ["tankyu"],related: ["コペルニクス","ガリレイ","天動説","科学革命"]},
  {term: "地域の歴史",yomi: "ちいきのれきし",def: "身近な地域の歴史。地域に残る建物・史料・地名・言い伝えなどから、世界や日本の大きな歴史とのつながりを考える手がかりとなる。",region: "east",cat: "文化・学問",rank: 1,course: ["sogo"],related: ["一次資料","二次資料"]},
  {term: "地球サミット",yomi: "ちきゅうさみっと",def: "1992年、ブラジルのリオデジャネイロで開かれた国連環境開発会議。「持続可能な開発」を理念とし、気候変動枠組条約や生物多様性条約が調印された。",year: 1992,region: "america",cat: "事件・戦争",rank: 2,course: ["sogo","tankyu"],related: ["持続可能な開発","地球温暖化","京都議定書"]},
  {term: "地球温暖化",yomi: "ちきゅうおんだんか",def: "二酸化炭素などの温室効果ガスの増加によって地球の平均気温が上昇すること。海面上昇や異常気象をもたらすとされ、京都議定書やパリ協定などで国際的な対策が進められている。",region: "europe",cat: "経済・社会",rank: 3,course: ["sogo","tankyu"],related: ["京都議定書","パリ協定","地球サミット"]},
  {term: "地球環境",yomi: "ちきゅうかんきょう",def: "地球全体にかかわる自然環境。工業化や人口増加による大気汚染・温暖化・森林破壊などが国境を越える問題となり、国際的な取り組みが求められている。",region: "europe",cat: "経済・社会",rank: 1,course: ["sogo"],related: ["地球温暖化","地球サミット","持続可能な開発"]},
  {term: "地租改正",yomi: "ちそかいせい",def: "1873年から明治政府が実施した税制改革。土地の所有者に地券を発行し、地価の3％を地租として現金で納めさせ、政府の財政を安定させた。",year: 1873,region: "east",cat: "制度・政策",rank: 3,course: ["sogo"],related: ["明治維新","廃藩置県","殖産興業"]},
  {term: "均田制",yomi: "きんでんせい",def: "北魏の孝文帝が始め、隋・唐に受けつがれた土地制度。国家が農民に土地を割りあて、税（租調庸）と兵役を負担させた。唐の中期以後にくずれ、両税法にかわった。",year: 485,end: 780,region: "east",cat: "制度・政策",rank: 3,course: ["tankyu"],related: ["北魏","孝文帝","租調庸制","府兵制"]},
  {term: "均輸・平準",yomi: "きんゆ・へいじゅん",def: "前漢の武帝が財政再建のために実施した経済政策。均輸は特産物を不足地に運んで売り、平準は物価が安いときに買い、高いときに売って物価を調整した。",year: -115,region: "east",cat: "制度・政策",rank: 2,course: ["tankyu"],related: ["武帝","塩・鉄の専売","前漢"]},
  {term: "坤輿万国全図",yomi: "こんよばんこくぜんず",def: "イエズス会のマテオ=リッチが明で作成した漢文による世界地図。中国人に世界の地理を紹介して中華思想に影響をあたえ、日本にも伝わった。",year: 1602,region: "east",cat: "文化・学問",rank: 2,course: ["tankyu"],related: ["マテオ=リッチ","イエズス会","幾何原本"]},
  {term: "垂簾聴政",yomi: "すいれんちょうせい",def: "幼い皇帝にかわって皇太后が御簾（すだれ）の後ろから政治をおこなうこと。清末の西太后は同治帝・光緒帝の時代にこの形で実権をにぎった。",year: 1861,region: "east",cat: "制度・政策",rank: 1,course: ["tankyu"],related: ["西太后","同治帝","光緒帝"]},
  {term: "塩の行進",yomi: "しおのこうしん",def: "1930年、ガンディーがイギリスの塩の専売に抗議して、海岸まで約360kmを行進し自ら塩をつくった運動。非暴力・不服従による第2次の反英運動の象徴となった。",year: 1930,region: "south",cat: "事件・戦争",rank: 3,course: ["sogo","tankyu"],related: ["ガンディー","非暴力・不服従","プールナ=スワラージ"]},
  {term: "塩・鉄の専売",yomi: "えん・てつのせんばい",def: "前漢の武帝が、匈奴遠征などで悪化した財政を立て直すために実施した政策。塩と鉄の生産・販売を国家が独占し、その利益を財源とした。",year: -119,region: "east",cat: "制度・政策",rank: 3,course: ["tankyu"],related: ["武帝","均輸・平準","前漢"]},
  {term: "壬辰・丁酉倭乱",yomi: "じんしん・ていゆうわらん",def: "1592年と97年、豊臣秀吉が朝鮮に出兵した戦争（文禄・慶長の役）。朝鮮は李舜臣の水軍や義兵の抵抗と明の援軍によって対抗し、秀吉の死で日本軍は撤退した。",year: 1592,end: 1598,region: "east",cat: "事件・戦争",rank: 3,course: ["sogo","tankyu"],related: ["豊臣秀吉","李舜臣","亀甲船","朝鮮王朝"]},
  {term: "外モンゴル",yomi: "そともんごる",def: "ゴビ砂漠の北側のモンゴル地域。17世紀末にハルハ部が清に服属した。辛亥革命後に独立を宣言し、1924年にモンゴル人民共和国が成立した。",region: "inner",cat: "地名・地域",rank: 1,course: ["tankyu"],related: ["内モンゴル","モンゴル人民共和国","ハルハ"]},
  {term: "外交革命",yomi: "がいこうかくめい",def: "1756年、長く対立していたオーストリアとフランスが同盟を結んだこと。マリア=テレジアがプロイセンへの対抗のため推進した。七年戦争の背景となった。",year: 1756,region: "europe",cat: "事件・戦争",rank: 3,course: ["tankyu"],related: ["七年戦争","マリア=テレジア","カウニッツ"]},
  {term: "外戚",yomi: "がいせき",def: "皇帝の母や皇后の一族。中国ではしばしば政治の実権をにぎり、前漢末には外戚の王莽が帝位を奪って新を建てた。後漢では宦官と権力を争った。",region: "east",cat: "制度・政策",rank: 2,course: ["tankyu"],related: ["王莽","宦官","後漢"]},
  {term: "多文化主義",yomi: "たぶんかしゅぎ",def: "国内の多様な民族・文化を尊重し、共存をはかろうとする考え方や政策。オーストラリアは1970年代に白豪主義を廃止して多文化主義に転じ、カナダでも採用された。",year: 1970,region: "oceania",cat: "制度・政策",rank: 2,course: ["sogo","tankyu"],related: ["オーストラリア","白豪主義","移民"]},
  {term: "多文化共生",yomi: "たぶんかきょうせい",def: "国籍や民族などの異なる人々が、互いの文化的な違いを認め合い、対等な関係を築きながら、地域社会の一員としてともに生きていくこと。",region: "east",cat: "制度・政策",rank: 1,course: ["sogo","tankyu"],related: ["多文化主義","移民","グローバル化"]},
  {term: "大アミール",yomi: "だいあみーる",def: "946年にバグダードに入城したブワイフ朝の君主が、アッバース朝カリフから授かった称号。イスラーム法を施行する政治・軍事の実権がカリフから大アミールに移った。",year: 946,region: "west",cat: "制度・政策",rank: 2,course: ["tankyu"],related: ["ブワイフ朝","アッバース朝","スルタン"]},
  {term: "大コロンビア",yomi: "だいころんびあ",def: "1819年、シモン=ボリバルの指導でスペインから独立した共和国。現在のコロンビア・ベネズエラ・エクアドル・パナマなどの地域をふくんだが、1830年に分裂した。",year: 1819,end: 1830,region: "america",cat: "国家・王朝",rank: 1,course: ["tankyu"],related: ["シモン=ボリバル","ラテンアメリカの独立","コロンビア"]},
  {term: "大ジンバブエ",yomi: "だいじんばぶえ",def: "ジンバブエにある巨大な石造建築の遺跡。11〜15世紀ごろ、インド洋交易で金などを輸出して栄えたショナ人の国の中心であったと考えられている。",region: "africa",cat: "文化・学問",rank: 2,course: ["tankyu"],related: ["モノモタパ王国","ジンバブエ","インド洋交易"]},
  {term: "大乗仏教",yomi: "だいじょうぶっきょう",def: "紀元前後に起こった仏教の一派。菩薩信仰を中心に、出家者だけでなく広く衆生の救済をめざした。ナーガールジュナが理論化し、中央アジアから中国・朝鮮・日本に伝わった。",region: "south",cat: "思想・宗教",rank: 3,course: ["tankyu"],related: ["ナーガールジュナ","クシャーナ朝","上座部仏教","ガンダーラ美術"]},
  {term: "大化の改新",yomi: "たいかのかいしん",def: "645年、中大兄皇子や中臣鎌足らが蘇我氏を倒して始めた政治改革。唐の律令制にならい、天皇を中心とする中央集権国家の建設をめざした。",year: 645,region: "east",cat: "事件・戦争",rank: 2,course: ["sogo","tankyu"],related: ["中大兄皇子","律令","大宝律令"]},
  {term: "大唐西域記",yomi: "だいとうさいいきき",def: "唐の僧玄奘が、インドへの往復の旅で見聞したことをまとめた地誌。中央アジア諸国やヴァルダナ朝時代のインドの様子を伝える貴重な史料である。",year: 646,region: "east",cat: "文化・学問",rank: 3,course: ["tankyu"],related: ["玄奘","ヴァルダナ朝","ナーランダー僧院"]},
  {term: "大宛（フェルガナ）",yomi: "だいえん",def: "中央アジアのフェルガナ地方にあった国の中国名。張騫の報告で知られ、良馬（汗血馬）を求めた前漢の武帝は李広利を派遣してこれを攻めた。",region: "inner",cat: "地名・地域",rank: 2,course: ["tankyu"],related: ["張騫","武帝","汗血馬"]},
  {term: "大宝律令",yomi: "たいほうりつりょう",def: "701年に制定された日本の律令。唐の律令にならって刑部親王・藤原不比等らが編纂し、中央集権的な律令国家の仕組みを整えた。",year: 701,region: "east",cat: "制度・政策",rank: 2,course: ["sogo","tankyu"],related: ["律令","唐","大化の改新"]},
  {term: "大憲章（マグナ=カルタ）",yomi: "だいけんしょう",def: "1215年、イングランドの貴族がジョン王に認めさせた文書。課税には貴族らの同意を必要とすることなどを定め、王権を制限した。イギリス立憲政治の基礎となった。",year: 1215,region: "europe",cat: "条約・宣言",rank: 3,course: ["sogo","tankyu"],related: ["ジョン王","議会","権利の章典"]},
  {term: "大戦景気",yomi: "たいせんけいき",def: "第一次世界大戦中の日本の好景気。ヨーロッパからの輸入がとだえ、アジア市場への輸出が伸びて重化学工業も発達した。一方で物価が上がり、米騒動の原因となった。",year: 1915,end: 1918,region: "east",cat: "経済・社会",rank: 2,course: ["sogo"],related: ["第一次世界大戦","成金","米騒動"]},
  {term: "大政奉還",yomi: "たいせいほうかん",def: "1867年、江戸幕府15代将軍徳川慶喜が政権を朝廷に返したこと。これに対し倒幕派は王政復古の大号令を出して新政府を樹立した。",year: 1867,region: "east",cat: "事件・戦争",rank: 3,course: ["sogo"],related: ["徳川慶喜","王政復古の大号令","明治維新"]},
  {term: "大旅行記",yomi: "だいりょこうき",def: "モロッコ出身のイブン=バットゥータが口述した旅行記（『三大陸周遊記』）。14世紀、アフリカ・西アジア・インド・中国の元などイスラーム世界を中心に旅した見聞を記す。",region: "west",cat: "文化・学問",rank: 3,course: ["tankyu"],related: ["イブン=バットゥータ","マリ王国","元"]},
  {term: "大日本帝国憲法",yomi: "だいにっぽんていこくけんぽう",def: "1889年に発布された日本の憲法。伊藤博文らがプロイセン憲法を参考に起草した。天皇主権を原則とし、議会を設けて立憲政治の基礎をつくった。アジアで最初の本格的な近代憲法である。",year: 1889,region: "east",cat: "条約・宣言",rank: 3,course: ["sogo"],related: ["伊藤博文","内閣制度","帝国議会","プロイセン"]},
  {term: "大月氏",yomi: "だいげっし",def: "匈奴に追われて中央アジアのアム川流域に移った月氏の国。前漢の武帝は張騫を派遣して匈奴挟撃の同盟を求めたが失敗した。のちその支配下からクシャーナ朝が興った。",region: "inner",cat: "国家・王朝",rank: 2,course: ["tankyu"],related: ["張騫","匈奴","クシャーナ朝","バクトリア"]},
  {term: "大梁",yomi: "たいりょう",def: "戦国時代の魏の都。現在の河南省開封市にあたる。黄河と運河を結ぶ交通の要地で、のちに開封（汴州）は五代や北宋の都として大いに繁栄した。",region: "east",cat: "地名・地域",rank: 1,course: ["tankyu"],related: ["魏（戦国）","開封","戦国時代"]},
  {term: "大祚栄",yomi: "だいそえい",def: "渤海の建国者。高句麗の遺民や靺鞨人を率いて698年に震国を建て、713年に唐から渤海郡王に冊封されて、国号を渤海と改めた。",year: 698,region: "east",cat: "人物",rank: 1,course: ["tankyu"],related: ["渤海","高句麗","唐"]},
  {term: "大秦",yomi: "だいしん",def: "中国でのローマ帝国の呼び名。後漢の西域都護班超は97年に部下の甘英を大秦に派遣したが、甘英は途中の海を前にして引き返した。",region: "europe",cat: "地名・地域",rank: 2,course: ["tankyu"],related: ["ローマ帝国","甘英","班超"]},
  {term: "大秦王安敦",yomi: "だいしんおうあんとん",def: "166年、後漢の日南郡に使者を送ったと記録される大秦（ローマ）の王。五賢帝の一人マルクス=アウレリウス=アントニヌス帝のこととされる。",year: 166,region: "europe",cat: "人物",rank: 2,course: ["tankyu"],related: ["マルクス=アウレリウス=アントニヌス","後漢","日南郡"]},
  {term: "大粛清",yomi: "だいしゅくせい",def: "1930年代後半、スターリンが反対派とみなした党幹部・軍人・知識人などを大量に処刑・投獄したこと。スターリンの独裁体制が確立した。",year: 1936,end: 1938,region: "europe",cat: "事件・戦争",rank: 2,course: ["tankyu"],related: ["スターリン","一国社会主義","秘密警察"]},
  {term: "大総統",yomi: "だいそうとう",def: "中華民国の元首の称号。孫文が臨時大総統となったが、まもなく袁世凱に地位をゆずった。袁世凱は正式な大総統となって独裁を強め、のち帝政復活をはかった。",year: 1912,region: "east",cat: "制度・政策",rank: 1,course: ["tankyu"],related: ["袁世凱","孫文","中華民国"]},
  {term: "大義名分論",yomi: "たいぎめいぶんろん",def: "君臣・父子などの身分秩序や名分を重んじる儒学の考え方。南宋の朱熹が強調し、中華と夷狄を区別する華夷の区別とともに、朱子学の特色となった。",region: "east",cat: "思想・宗教",rank: 2,course: ["tankyu"],related: ["朱子学","朱熹","華夷の区別"]},
  {term: "大航海時代",yomi: "だいこうかいじだい",def: "15世紀末から17世紀前半、ポルトガルやスペインなどヨーロッパ諸国が新航路の開拓や海外進出を進めた時代。アジアやアメリカとヨーロッパが直接結ばれ、商業革命や価格革命を引き起こした。",region: "europe",cat: "事件・戦争",rank: 3,course: ["sogo","tankyu"],related: ["ヴァスコ=ダ=ガマ","コロンブス","マゼラン","商業革命"]},
  {term: "大英帝国",yomi: "だいえいていこく",def: "世界各地に植民地や自治領をもったイギリスの帝国の呼び名。19世紀のヴィクトリア時代に最盛期をむかえ、「太陽の沈まぬ帝国」とよばれた。",region: "europe",cat: "国家・王朝",rank: 2,course: ["sogo","tankyu"],related: ["ヴィクトリア女王","インド帝国","パクス=ブリタニカ"]},
  {term: "大蔵経",yomi: "だいぞうきょう",def: "仏教の経典を集大成したもの。高麗ではモンゴルの侵入を仏の力で退けようと大蔵経が木版で刊行され、その版木は今も海印寺に残る。",region: "east",cat: "文化・学問",rank: 2,course: ["tankyu"],related: ["高麗","仏教","木版印刷"]},
  {term: "大衆化",yomi: "たいしゅうか",def: "20世紀に入り、多くの人々が政治・経済・文化の担い手となったこと。普通選挙の実現、大量生産・大量消費、新聞・ラジオ・映画などのマスメディアの普及がこれを進めた。",region: "europe",cat: "経済・社会",rank: 2,course: ["sogo"],related: ["大衆社会","大量生産","普通選挙"]},
  {term: "大西洋三角貿易",yomi: "たいせいようさんかくぼうえき",def: "17〜18世紀、ヨーロッパ・西アフリカ・アメリカ大陸を結んだ貿易。ヨーロッパの武器・雑貨をアフリカへ、黒人奴隷をアメリカへ、砂糖・綿花などをヨーロッパへ運んだ。",region: "europe",cat: "経済・社会",rank: 3,course: ["sogo","tankyu"],related: ["奴隷貿易","リヴァプール","プランテーション","砂糖"]},
  {term: "大西洋憲章",yomi: "たいせいようけんしょう",def: "1941年、フランクリン=ローズヴェルトとチャーチルが大西洋上で会談して発表した共同宣言。領土不拡大、民族自決、国際平和機構の再建などを掲げ、のちの国際連合憲章の基礎となった。",year: 1941,region: "europe",cat: "条約・宣言",rank: 3,course: ["sogo","tankyu"],related: ["フランクリン=ローズヴェルト","チャーチル","国際連合"]},
  {term: "大越",yomi: "だいえつ",def: "11世紀以後のベトナムの国号。李朝が用い、陳朝・黎朝に受けつがれた。中国の制度や儒学を取りいれて国家体制を整え、中国の侵攻に抵抗した。",region: "sea",cat: "国家・王朝",rank: 2,course: ["tankyu"],related: ["李朝","陳朝","黎朝","ベトナム"]},
  {term: "大躍進",yomi: "だいやくしん",def: "1958年、毛沢東が開始した急激な経済建設運動。人民公社を設立し、土法製鉄などで農工業の飛躍的発展をめざしたが、大失敗して数千万人の餓死者を出した。",year: 1958,region: "east",cat: "制度・政策",rank: 3,course: ["tankyu"],related: ["毛沢東","人民公社","プロレタリア文化大革命"]},
  {term: "大運河",yomi: "だいうんが",def: "隋の文帝が着工し、煬帝が完成させた運河。華北と江南を結び、江南の物資を北方へ運ぶ南北の大動脈となった。工事への動員は民衆を苦しめた。",year: 610,region: "east",cat: "文化・学問",rank: 3,course: ["tankyu"],related: ["煬帝","隋","江南"]},
  {term: "大都",yomi: "だいと",def: "元のクビライが現在の北京に造営した都。モンゴル語でカンバリクとよばれ、大運河や海運で物資が運ばれ、世界的な大都市として繁栄した。",year: 1267,region: "east",cat: "地名・地域",rank: 3,course: ["tankyu"],related: ["クビライ","元","北京"]},
  {term: "大量生産",yomi: "たいりょうせいさん",def: "規格化された製品を機械や流れ作業で大量につくること。20世紀初めにアメリカのフォード社が自動車の生産で導入し、製品の価格を下げて大衆消費社会を生んだ。",region: "america",cat: "経済・社会",rank: 2,course: ["sogo"],related: ["大量生産・大量消費","フォード","大衆化"]},
  {term: "大量生産・大量消費",yomi: "たいりょうせいさん・たいりょうしょうひ",def: "大量に生産された商品を多くの人々が購入・消費する社会のあり方。1920年代のアメリカで成立し、自動車や家庭電化製品が普及した。",year: 1920,region: "america",cat: "経済・社会",rank: 2,course: ["sogo"],related: ["大量生産","大衆化","世界恐慌"]},
  {term: "大陸会議",yomi: "たいりくかいぎ",def: "13植民地の代表が集まって開いた会議。1774年に始まり、第2回大陸会議でワシントンを総司令官に任命し、1776年に独立宣言を採択した。",year: 1774,region: "america",cat: "組織・運動",rank: 2,course: ["sogo","tankyu"],related: ["アメリカ独立戦争","独立宣言","ワシントン"]},
  {term: "大陸封鎖令",yomi: "たいりくふうされい",def: "1806年、ナポレオンがベルリンで発した勅令。イギリスとヨーロッパ大陸諸国との通商を禁止してイギリスに経済的打撃をあたえようとしたが、大陸諸国も苦しんだ。",year: 1806,region: "europe",cat: "制度・政策",rank: 3,course: ["sogo","tankyu"],related: ["ナポレオン","ロシア遠征","トラファルガーの海戦"]},
  {term: "大陸軍",yomi: "たいりくぐん",def: "アメリカ独立戦争で、大陸会議によって組織された植民地側の軍隊。ワシントンが総司令官となり、フランスの支援も得てイギリス軍と戦った。",year: 1775,region: "america",cat: "組織・運動",rank: 1,course: ["sogo","tankyu"],related: ["ワシントン","大陸会議","アメリカ独立戦争"]},
  {term: "大雁塔",yomi: "だいがんとう",def: "唐の長安の慈恩寺にある塔。玄奘がインドから持ち帰った経典や仏像を保存するために建てられ、玄奘はここで経典の翻訳にあたった。",year: 652,region: "east",cat: "文化・学問",rank: 1,course: ["tankyu"],related: ["玄奘","長安","唐"]},
  {term: "大韓民国",yomi: "だいかんみんこく",def: "1948年、朝鮮半島の南部にアメリカの支持を得て成立した国家。李承晩が初代大統領となった。1950年に朝鮮戦争が起こり、1965年に日韓基本条約で日本と国交を結んだ。",year: 1948,region: "east",cat: "国家・王朝",rank: 3,course: ["sogo","tankyu"],related: ["李承晩","北緯38度線","朝鮮戦争"]},
  {term: "大黒屋光太夫",yomi: "だいこくやこうだゆう",def: "江戸時代の伊勢の船頭。漂流してロシアに渡り、エカチェリーナ2世に謁見して帰国を許された。1792年にラクスマンに伴われて根室に帰国した。",year: 1792,region: "east",cat: "人物",rank: 1,course: ["sogo","tankyu"],related: ["ラクスマン","エカチェリーナ2世"]},
  {term: "天体の回転について",yomi: "てんたいのかいてんについて",def: "コペルニクスが1543年に出版した書物。天動説を否定し、地球が太陽のまわりを回るとする地動説を数学的に論じた。近代天文学の出発点となった。",year: 1543,region: "europe",cat: "文化・学問",rank: 2,course: ["tankyu"],related: ["コペルニクス","地動説","科学革命"]},
  {term: "天可汗",yomi: "てんかかん",def: "唐の太宗が東突厥を服属させた後、北方の遊牧諸民族からおくられた称号。中国皇帝が遊牧世界の君主（可汗）としても認められたことを示す。",year: 630,region: "east",cat: "制度・政策",rank: 2,course: ["tankyu"],related: ["唐の太宗","東突厥","可汗"]},
  {term: "天命",yomi: "てんめい",def: "天が有徳者にあたえる、天下を治める命令。周は殷を倒した正統性をこれで説明した。天命が改まると王朝の姓がかわるという易姓革命の思想を生んだ。",region: "east",cat: "思想・宗教",rank: 2,course: ["tankyu"],related: ["周","易姓革命","徳治主義"]},
  {term: "天安門事件",yomi: "てんあんもんじけん",def: "1989年、北京の天安門広場で民主化を求めて集まった学生・市民を、中国政府が軍隊で武力鎮圧した事件。政府は改革・開放政策を続けたが、政治の民主化はおさえられた。",year: 1989,region: "east",cat: "事件・戦争",rank: 3,course: ["sogo","tankyu"],related: ["鄧小平","改革・開放政策","民主化運動"]},
  {term: "天文台",yomi: "てんもんだい",def: "天体を観測する施設。15世紀、ティムール朝の君主ウルグ=ベクは都サマルカンドに大規模な天文台を建て、精密な天文表を作成した。",year: 1420,region: "inner",cat: "文化・学問",rank: 1,course: ["tankyu"],related: ["ウルグ=ベク","サマルカンド","ティムール朝"]},
  {term: "天朝田畝制度",yomi: "てんちょうでんぽせいど",def: "太平天国が発表した土地制度。土地を男女の別なく均等に分配し、余った生産物を国庫に納めさせる理想をかかげたが、実施されなかった。",year: 1853,region: "east",cat: "制度・政策",rank: 2,course: ["tankyu"],related: ["太平天国","洪秀全","滅満興漢"]},
  {term: "天然ガス",yomi: "てんねんがす",def: "地下から産出する可燃性のガス。石油とならぶ重要なエネルギー資源で、ペルシア湾岸のカタールなどは天然ガスの輸出で豊かになった。",region: "west",cat: "経済・社会",rank: 1,course: ["sogo","tankyu"],related: ["石油","カタール","エネルギー革命"]},
  {term: "太平天国",yomi: "たいへいてんごく",def: "1851年、洪秀全が上帝会を率いて建てた国。「滅満興漢」を唱えて南京を占領し天京と称したが、曾国藩・李鴻章の郷勇や常勝軍などに攻められ、1864年に滅んだ。",year: 1851,end: 1864,region: "east",cat: "国家・王朝",rank: 3,course: ["sogo","tankyu"],related: ["洪秀全","上帝会","天朝田畝制度","常勝軍"]},
  {term: "太平洋",yomi: "たいへいよう",def: "世界最大の海洋。1520年、マゼランが南米南端の海峡をぬけてここを航海した際、波が穏やかだったことから「平和な海」と名づけた。",year: 1520,region: "oceania",cat: "地名・地域",rank: 1,course: ["sogo","tankyu"],related: ["マゼラン","世界周航","大航海時代"]},
  {term: "太武帝",yomi: "たいぶてい",def: "北魏の第3代皇帝。439年に華北を統一し、五胡十六国時代を終わらせた。道士の寇謙之を信任して道教を国教化し、仏教を弾圧した。",year: 423,end: 452,region: "east",cat: "人物",rank: 2,course: ["tankyu"],related: ["北魏","寇謙之","道教"]},
  {term: "太陽のしずまぬ国",yomi: "たいようのしずまぬくに",def: "16世紀のスペイン帝国の呼び名。フェリペ2世がポルトガル王位を兼ねたことで、世界中に領土が広がり、どこかで常に太陽が出ていることからこうよばれた。",region: "europe",cat: "制度・政策",rank: 1,course: ["tankyu"],related: ["太陽の沈まぬ帝国","フェリペ2世","スペイン"]},
  {term: "太陽のピラミッド",yomi: "たいようのぴらみっど",def: "メキシコ高原のテオティワカンにある巨大なピラミッド。高さ約60ｍにおよび、テオティワカン文明の繁栄を示す代表的な建造物である。",region: "america",cat: "文化・学問",rank: 1,course: ["tankyu"],related: ["テオティワカン文明","メキシコ高原"]},
  {term: "太陽の沈まぬ帝国",yomi: "たいようのしずまぬていこく",def: "スペインのフェリペ2世の時代の大帝国の呼び名。1580年にポルトガルを併合し、両国の世界中の植民地を支配した。19世紀の大英帝国もこうよばれた。",year: 1580,region: "europe",cat: "制度・政策",rank: 2,course: ["tankyu"],related: ["フェリペ2世","スペイン","大英帝国"]},
  {term: "太陽暦",yomi: "たいようれき",def: "地球が太陽のまわりを1周する周期をもとにした暦。古代エジプトでナイル川の増水時期を知るために発達し、ユリウス暦・グレゴリウス暦に受けつがれた。日本では明治初めに採用された。",region: "west",cat: "文化・学問",rank: 2,course: ["sogo","tankyu"],related: ["エジプト文明","ユリウス暦","太陰暦"]},
  {term: "契丹",yomi: "きったん",def: "モンゴル系の遊牧民。10世紀初めに耶律阿保機が諸部族を統一して遼を建て、936年に燕雲十六州を獲得して、のち北宋と対立した。",region: "inner",cat: "国家・王朝",rank: 3,course: ["tankyu"],related: ["耶律阿保機","遼","燕雲十六州","契丹文字"]},
  {term: "契丹文字",yomi: "きったんもじ",def: "遼で漢字やウイグル文字の影響を受けてつくられた文字。大字と小字があり、独自の文字をもとうとした契丹人の民族意識の高まりを示す。",year: 920,region: "inner",cat: "文化・学問",rank: 2,course: ["tankyu"],related: ["遼","漢字","女真文字"]},
  {term: "契約労働者",yomi: "けいやくろうどうしゃ",def: "一定期間の労働を契約して海外へ渡った労働者。奴隷制廃止後、インド系・中国系の人々が英領ギアナなどのプランテーションなどに送られた。中国人は苦力とよばれた。",region: "america",cat: "経済・社会",rank: 1,course: ["tankyu"],related: ["奴隷制廃止","苦力","移民"]},
  {term: "女帝",yomi: "じょてい",def: "女性の皇帝。中国史上では、唐の高宗の皇后であった則天武后が690年に自ら即位し、国号を周とした例が唯一の正統な女帝である。",region: "east",cat: "人物",rank: 1,course: ["tankyu"],related: ["則天武后","周（武周）"]},
  {term: "女性参政権",yomi: "じょせいさんせいけん",def: "女性が選挙に参加する権利。1893年にニュージーランドで最初に認められ、第一次世界大戦での女性の貢献を背景にイギリス・アメリカ・ドイツなどでも実現した。日本では1945年に認められた。",region: "europe",cat: "制度・政策",rank: 3,course: ["sogo","tankyu"],related: ["第一次世界大戦","総力戦","ニュージーランド","大衆化"]},
  {term: "女真",yomi: "じょしん",def: "中国東北地方に住んだツングース系の民族。12世紀に完顔阿骨打が金を建て、17世紀にはヌルハチが後金（清）を建てた。のちに満洲とよばれた。",region: "inner",cat: "国家・王朝",rank: 3,course: ["tankyu"],related: ["完顔阿骨打","金","後金","ヌルハチ"]},
  {term: "女真文字",yomi: "じょしんもじ",def: "金で漢字や契丹文字をもとにつくられた文字。完顔阿骨打の命で作成された。征服王朝が民族の独自性を保とうとしたことを示している。",year: 1119,region: "inner",cat: "文化・学問",rank: 2,course: ["tankyu"],related: ["金","契丹文字","女真"]},
  {term: "奴隷制廃止",yomi: "どれいせいはいし",def: "奴隷制度を法的に廃止すること。イギリスは1833年に植民地での奴隷制を廃止し、アメリカでは南北戦争後に、ブラジルでは1888年に廃止された。",region: "europe",cat: "制度・政策",rank: 2,course: ["sogo","tankyu"],related: ["奴隷貿易廃止","奴隷解放宣言","ブラジル"]},
  {term: "奴隷王朝",yomi: "どれいおうちょう",def: "1206年、ゴール朝の奴隷出身の武将アイバクがデリーで建てた王朝。インド初のイスラーム王朝で、デリー=スルタン朝の最初の王朝である。",year: 1206,end: 1290,region: "south",cat: "国家・王朝",rank: 3,course: ["tankyu"],related: ["アイバク","デリー=スルタン朝","ゴール朝"]},
  {term: "奴隷解放",yomi: "どれいかいほう",def: "奴隷の身分から人々を解放すること。ハイチではトゥサン=ルヴェルチュールらの指導した革命で奴隷が解放され、1804年に黒人共和国として独立した。",region: "america",cat: "制度・政策",rank: 2,course: ["sogo","tankyu"],related: ["トゥサン=ルヴェルチュール","奴隷解放宣言","ハイチ革命"]},
  {term: "奴隷解放宣言",yomi: "どれいかいほうせんげん",def: "1863年、南北戦争中にリンカン大統領が発した宣言。反乱州の奴隷の解放を宣言し、内外の世論を北部に引きつけた。奴隷制は1865年の憲法修正第13条で廃止された。",year: 1863,region: "america",cat: "条約・宣言",rank: 3,course: ["sogo","tankyu"],related: ["リンカン","南北戦争","奴隷制廃止"]},
  {term: "奴隷貿易",yomi: "どれいぼうえき",def: "アフリカの人々を奴隷として売買した貿易。16〜19世紀、大西洋三角貿易のなかで約1千万人がアメリカ大陸へ運ばれた。ダホメ王国などは奴隷を供給して栄えたが、アフリカ社会は大きな打撃を受けた。",region: "africa",cat: "経済・社会",rank: 3,course: ["sogo","tankyu"],related: ["大西洋三角貿易","ダホメ王国","ベニン王国","プランテーション"]},
  {term: "奴隷貿易廃止",yomi: "どれいぼうえきはいし",def: "奴隷の売買を禁止すること。イギリスでは人道主義者の運動により1807年に奴隷貿易が廃止された。解放奴隷の入植地としてシエラレオネがつくられた。",year: 1807,region: "europe",cat: "制度・政策",rank: 2,course: ["sogo","tankyu"],related: ["奴隷制廃止","シエラレオネ","ウィルバーフォース"]},
  {term: "始皇帝",yomi: "しこうてい",def: "秦の王で、前221年に中国を統一し、初めて「皇帝」の称号を用いた。郡県制を全国に施行し、度量衡・貨幣・文字を統一した。焚書・坑儒で思想を統制し、万里の長城を修築した。",year: -221,end: -210,region: "east",cat: "人物",rank: 3,course: ["sogo","tankyu"],related: ["秦","郡県制","焚書・坑儒","万里の長城"]},
  {term: "委任統治",yomi: "いにんとうち",def: "第一次世界大戦後、国際連盟がドイツの旧植民地やオスマン帝国の旧領を、イギリス・フランス・日本などに統治させた制度。実質的には植民地支配と変わらなかった。",year: 1920,region: "west",cat: "制度・政策",rank: 3,course: ["sogo","tankyu"],related: ["国際連盟","ヴェルサイユ条約","信託統治"]},
  {term: "字喃（チュノム）",yomi: "ちゅのむ",def: "漢字をもとにつくられたベトナム独自の文字。陳朝のころから用いられ、ベトナム語の文学作品が書かれるなど、民族意識の高まりを示す。",region: "sea",cat: "文化・学問",rank: 2,course: ["tankyu"],related: ["陳朝","大越","漢字"]},
  {term: "孝文帝",yomi: "こうぶんてい",def: "北魏の皇帝。均田制や三長制を実施して税制を整え、都を平城から洛陽に移した。鮮卑の服装や言語を禁止するなどの漢化政策を進めた。",year: 471,end: 499,region: "east",cat: "人物",rank: 3,course: ["tankyu"],related: ["北魏","均田制","漢化政策","洛陽"]},
  {term: "季節風貿易",yomi: "きせつふうぼうえき",def: "インド洋で、夏と冬に風向きが変わる季節風を利用しておこなわれた海上交易。1世紀ごろからローマとインドを結ぶ交易が盛んとなり、のちダウ船による交易に発展した。",region: "south",cat: "経済・社会",rank: 2,course: ["tankyu"],related: ["ローマとの交易","エリュトゥラー海案内記","インド洋交易"]},
  {term: "学制",yomi: "がくせい",def: "1872年、明治政府が公布した近代的な学校制度。フランスの制度にならって全国に小学校を設け、身分や性別に関係なく国民皆学をめざした。",year: 1872,region: "east",cat: "制度・政策",rank: 2,course: ["sogo"],related: ["学校教育","明治維新","国民国家"]},
  {term: "学問のすゝめ",yomi: "がくもんのすすめ",def: "福沢諭吉が1872年から刊行した書物。「天は人の上に人を造らず」の言葉で始まり、学問による個人の独立と国の独立を説いて、広く読まれた。",year: 1872,region: "east",cat: "文化・学問",rank: 2,course: ["sogo"],related: ["福沢諭吉","文明開化"]},
  {term: "学校教育",yomi: "がっこうきょういく",def: "国家が学校を整備して国民に教育をおこなうこと。19世紀には各国で義務教育が普及し、共通の言語や歴史を教えることで国民意識の形成に大きな役割を果たした。",region: "europe",cat: "制度・政策",rank: 1,course: ["sogo"],related: ["国民国家","学制","国民意識"]},
  {term: "孫文",yomi: "そんぶん",def: "中国の革命家。1905年に中国同盟会を結成して三民主義を掲げ、辛亥革命後に中華民国の臨時大総統となった。のち中国国民党を組織し、第1次国共合作を実現した。",year: 1866,end: 1925,region: "east",cat: "人物",rank: 3,course: ["sogo","tankyu"],related: ["三民主義","中国同盟会","辛亥革命","中国国民党"]},
  {term: "孫権",yomi: "そんけん",def: "三国時代の呉の建国者。劉備と結んで赤壁の戦いで曹操を破り、江南に勢力を確立した。229年に皇帝を称し、建業（現在の南京）を都とした。",year: 222,end: 252,region: "east",cat: "人物",rank: 2,course: ["tankyu"],related: ["呉","赤壁の戦い","三国時代"]},
  {term: "宇文泰",yomi: "うぶんたい",def: "西魏の実力者。府兵制を創設するなど、のちの北周・隋・唐に受けつがれる国家体制の基礎を築いた。その子が西魏にかわって北周を建てた。",region: "east",cat: "人物",rank: 1,course: ["tankyu"],related: ["西魏","府兵制","北周"]},
  {term: "安全保障理事会",yomi: "あんぜんほしょうりじかい",def: "国際連合の主要機関。国際平和と安全の維持に主要な責任を負う。米・英・仏・ソ（ロシア）・中の5常任理事国が拒否権をもつため、冷戦期には機能しないこともあった。",year: 1945,region: "america",cat: "組織・運動",rank: 3,course: ["sogo","tankyu"],related: ["国際連合","拒否権","常任理事国"]},
  {term: "安史の乱",yomi: "あんしのらん",def: "755年、節度使の安禄山とその部下の史思明が起こした反乱。ウイグルの援軍を得て鎮圧したが、唐は衰え、節度使が各地で自立するようになった。",year: 755,end: 763,region: "east",cat: "事件・戦争",rank: 3,course: ["tankyu"],related: ["玄宗","安禄山","節度使","ウイグル"]},
  {term: "安息",yomi: "あんそく",def: "イラン系のパルティアの中国での呼び名。建国者アルサケスの名に由来するとされる。シルク=ロードの東西交易の中継で利益を得た。",region: "west",cat: "国家・王朝",rank: 1,course: ["tankyu"],related: ["パルティア","張騫","シルク=ロード"]},
  {term: "安重根",yomi: "あんじゅうこん",def: "朝鮮の独立運動家。義兵闘争に参加し、1909年にハルビン駅で前韓国統監の伊藤博文を暗殺した。翌年、日本は韓国を併合した。",year: 1909,region: "east",cat: "人物",rank: 2,course: ["sogo","tankyu"],related: ["伊藤博文","韓国併合","義兵闘争"]},
  {term: "宋学",yomi: "そうがく",def: "宋代に起こった新しい儒学。経典の字句の解釈より、宇宙の原理や人間の本性を哲学的に探究した。北宋の周敦頤に始まり、南宋の朱熹が集大成して朱子学となった。",region: "east",cat: "思想・宗教",rank: 2,course: ["tankyu"],related: ["朱熹","朱子学","周敦頤","性即理"]},
  {term: "完新世",yomi: "かんしんせい",def: "約1万年前に最後の氷期が終わってから現在までの地質時代。気候が温暖化し、西アジアなど各地で農耕・牧畜が始まり、新石器時代へ移った。",year: -10000,region: "africa",cat: "文化・学問",rank: 1,course: ["tankyu"],related: ["更新世","農耕・牧畜","新石器時代"]},
  {term: "完顔阿骨打",yomi: "わんやんあぐだ",def: "女真の完顔部の首長。1115年に金を建てて皇帝となり、猛安・謀克の制度をととのえた。宋と結んで遼を攻撃し、遼の滅亡に道を開いた。",year: 1115,end: 1123,region: "inner",cat: "人物",rank: 3,course: ["tankyu"],related: ["金","女真","猛安・謀克","女真文字"]},
  {term: "宗教改革",yomi: "しゅうきょうかいかく",def: "16世紀、ローマ=カトリック教会の腐敗を批判して起こった改革運動。1517年のルターの九十五か条の論題に始まり、カルヴァンらが続いて、プロテスタント諸派が成立した。",year: 1517,region: "europe",cat: "事件・戦争",rank: 3,course: ["sogo","tankyu"],related: ["ルター","カルヴァン","九十五か条の論題","対抗宗教改革"]},
  {term: "宗教裁判",yomi: "しゅうきょうさいばん",def: "カトリック教会が異端とみなした人を取り調べ、処罰した裁判（異端審問）。ジャンヌ=ダルクは魔女として処刑され、ガリレイは地動説の撤回を求められた。",region: "europe",cat: "制度・政策",rank: 2,course: ["tankyu"],related: ["異端","ガリレイ","ジャンヌ=ダルク","対抗宗教改革"]},
  {term: "宗法",yomi: "そうほう",def: "周代の同姓の一族（宗族）の秩序を定めた規範。本家（大宗）と分家（小宗）の関係や祖先祭祀のあり方を定め、周の封建制を支えた。",region: "east",cat: "制度・政策",rank: 2,course: ["tankyu"],related: ["周","封建制","宗族"]},
  {term: "宗派",yomi: "しゅうは",def: "同じ宗教のなかで、教義や儀礼の違いによって分かれた集団。レバノンでは宗派ごとに議席や公職を配分する体制がとられたが、対立は内戦の原因となった。",region: "west",cat: "思想・宗教",rank: 1,course: ["sogo","tankyu"],related: ["レバノン内戦","スンナ派","シーア派"]},
  {term: "官渡の戦い",yomi: "かんとのたたかい",def: "200年、後漢末に曹操が華北の有力者袁紹を破った戦い。兵力で劣った曹操が勝利し、華北の支配を固めて三国時代の魏の基礎を築いた。",year: 200,region: "east",cat: "事件・戦争",rank: 1,course: ["tankyu"],related: ["曹操","袁紹","赤壁の戦い"]},
  {term: "宝船",yomi: "ほうせん",def: "明の鄭和の南海遠征で用いられた大型船。大きなものは長さ100ｍをこえたといわれ、多くの財宝を積んで各地の国々に朝貢をうながした。",year: 1405,region: "east",cat: "文化・学問",rank: 1,course: ["tankyu"],related: ["鄭和","南海遠征","永楽帝"]},
  {term: "宣統帝（溥儀）",yomi: "せんとうてい",def: "清の最後の皇帝。幼くして即位したが、辛亥革命の結果、1912年に退位して清は滅んだ。のち日本により満州国の執政、ついで皇帝とされた。",year: 1908,end: 1912,region: "east",cat: "人物",rank: 3,course: ["sogo","tankyu"],related: ["辛亥革命","袁世凱","満州国"]},
  {term: "宥和政策",yomi: "ゆうわせいさく",def: "1930年代、イギリスのネヴィル=チェンバレン首相らがドイツなどの要求に譲歩して戦争を避けようとした政策。1938年のミュンヘン会談でズデーテン地方の割譲を認めたが、侵略を止められなかった。",year: 1938,region: "europe",cat: "制度・政策",rank: 3,course: ["sogo","tankyu"],related: ["ミュンヘン会談","チェンバレン","ヒトラー"]},
  {term: "寛容",yomi: "かんよう",def: "異なる宗教や意見の存在を認めること。ヴォルテールは新教徒が冤罪で処刑された事件を機に『寛容論』を著し、宗教的寛容を訴えた。",region: "europe",cat: "思想・宗教",rank: 1,course: ["tankyu"],related: ["ヴォルテール","啓蒙思想","宗教戦争"]},
  {term: "対ソ干渉戦争",yomi: "たいそかんしょうせんそう",def: "ロシア革命後、イギリス・フランス・アメリカ・日本などがソヴィエト政権を倒すために軍事干渉した戦争。日本などのシベリア出兵もその一部である。ソヴィエト政権は赤軍を組織して対抗した。",year: 1918,end: 1922,region: "europe",cat: "事件・戦争",rank: 3,course: ["sogo","tankyu"],related: ["シベリア出兵","ロシア革命","戦時共産主義"]},
  {term: "対抗宗教改革",yomi: "たいこうしゅうきょうかいかく",def: "宗教改革に対抗して、カトリック教会がおこなった自己改革（反宗教改革）。トリエント公会議で教義を確認し、イエズス会が海外布教などで勢力の回復をはかった。",year: 1545,region: "europe",cat: "事件・戦争",rank: 3,course: ["tankyu"],related: ["イグナティウス=ロヨラ","イエズス会","トリエント公会議"]},
  {term: "対立・協調",yomi: "たいりつ・きょうちょう",def: "歴史総合で近代化や国際秩序の変化を考える視点の一つ。国家や集団どうしが争う側面と、協力しあう側面の両方から、歴史の動きをとらえる。",region: "europe",cat: "経済・社会",rank: 1,course: ["sogo"],related: ["国際協調","冷戦","帝国主義"]},
  {term: "封じ込め政策",yomi: "ふうじこめせいさく",def: "ソ連と共産主義の勢力拡大を防ぐためのアメリカの政策。1947年のトルーマン=ドクトリンで示され、マーシャル=プランや北大西洋条約機構の結成などに具体化された。",year: 1947,region: "america",cat: "制度・政策",rank: 3,course: ["sogo","tankyu"],related: ["トルーマン=ドクトリン","マーシャル=プラン","冷戦"]},
  {term: "封建制",yomi: "ほうけんせい",def: "周では王が一族や功臣に封土をあたえて諸侯とし、貢納と軍役を課した制度をさす。中世ヨーロッパでは、主君が家臣に封土をあたえて保護し、家臣が軍役で奉仕する主従関係をさす。",region: "europe",cat: "制度・政策",rank: 3,course: ["tankyu"],related: ["周","宗法","荘園","主従関係"]},
  {term: "専制君主政",yomi: "せんせいくんしゅせい",def: "ディオクレティアヌス帝が始めたローマ帝政後期の政治体制（ドミナトゥス）。皇帝を神として崇拝させ、元老院の権威を無視して専制的な支配をおこなった。",year: 284,region: "europe",cat: "制度・政策",rank: 3,course: ["tankyu"],related: ["ディオクレティアヌス帝","四帝分治制","元首政"]},
  {term: "尊王攘夷",yomi: "そんのうじょうい",def: "周王を尊び、異民族をうち払うこと。春秋時代、斉の桓公らの覇者がこれを掲げて諸侯を指導した。幕末の日本では天皇を尊び外国勢力を排斥する思想として用いられた。",region: "east",cat: "思想・宗教",rank: 2,course: ["sogo","tankyu"],related: ["春秋の五覇","周","幕末"]},
  {term: "小さな政府",yomi: "ちいさなせいふ",def: "政府の経済への介入や社会保障支出をおさえ、市場の働きを重んじる政策。1980年前後、イギリスのサッチャー、アメリカのレーガンらが新自由主義の立場から進めた。",year: 1979,region: "europe",cat: "制度・政策",rank: 2,course: ["sogo","tankyu"],related: ["サッチャー","レーガン","新自由主義"]},
  {term: "少子高齢化",yomi: "しょうしこうれいか",def: "子どもの数が減り、高齢者の割合が増えること。日本など先進国で進み、労働力の不足や年金・医療など社会保障制度の維持が課題となっている。",region: "east",cat: "経済・社会",rank: 2,course: ["sogo"],related: ["人口問題","社会保障"]},
  {term: "尚巴志",yomi: "しょうはし",def: "琉球の中山王。1429年に北山・中山・南山の三山を統一して琉球王国を建てた。明に朝貢し、東アジアと東南アジアを結ぶ中継貿易で繁栄した。",year: 1429,region: "east",cat: "人物",rank: 2,course: ["tankyu"],related: ["琉球王国","中山","中継貿易"]},
  {term: "屈原",yomi: "くつげん",def: "戦国時代の楚の政治家・詩人。秦に対抗することを主張したが受けいれられず、汨羅に身を投げたと伝えられる。『楚辞』に作品が収められている。",region: "east",cat: "人物",rank: 1,course: ["tankyu"],related: ["楚","楚辞","戦国時代"]},
  {term: "属州",yomi: "ぞくしゅう",def: "ローマがイタリア半島以外に獲得した海外領土。第1次ポエニ戦争後のシチリアが最初で、総督が派遣された。属州からの富で有力者が大土地所有（ラティフンディア）を広げた。",region: "europe",cat: "制度・政策",rank: 3,course: ["tankyu"],related: ["ポエニ戦争","シチリア","元老院","騎士"]},
  {term: "屯田制",yomi: "とんでんせい",def: "兵士や流民に土地を耕作させ、軍の食料や財源を確保する制度。後漢末に曹操が実施して魏の国力を支え、のちの均田制にも影響をあたえた。",year: 196,region: "east",cat: "制度・政策",rank: 2,course: ["tankyu"],related: ["曹操","魏","均田制"]},
  {term: "山東",yomi: "さんとう",def: "中国北東部の半島地域。1898年にドイツが膠州湾を租借して勢力範囲とした。第一次世界大戦で日本がこれを奪い、その返還問題が五・四運動の原因となった。",region: "east",cat: "地名・地域",rank: 2,course: ["sogo","tankyu"],related: ["膠州湾","二十一か条の要求","五・四運動","九か国条約"]},
  {term: "岩倉使節団",yomi: "いわくらしせつだん",def: "1871年、岩倉具視を全権大使として欧米に派遣された使節団。不平等条約の改正交渉はできなかったが、欧米の制度や産業を視察し、日本の近代化に影響をあたえた。",year: 1871,end: 1873,region: "east",cat: "事件・戦争",rank: 2,course: ["sogo"],related: ["岩倉具視","伊藤博文","不平等条約"]},
  {term: "岩塩",yomi: "がんえん",def: "地中で塩分が結晶したもの。西アフリカでは、サハラ砂漠の岩塩とニジェール川流域の金を交換するサハラ交易が盛んで、ガーナ王国はこれで繁栄した。",region: "africa",cat: "経済・社会",rank: 2,course: ["tankyu"],related: ["ガーナ王国","サハラ交易","金"]},
  {term: "工場法",yomi: "こうじょうほう",def: "イギリスで労働者を保護するために制定された法律。1833年の工場法は、繊維工場での9歳未満の児童の労働を禁止し、年少者の労働時間を制限した。",year: 1833,region: "europe",cat: "制度・政策",rank: 3,course: ["tankyu"],related: ["産業革命","労働問題","児童労働"]},
  {term: "工業化",yomi: "こうぎょうか",def: "機械を使った工場生産が経済の中心となること。18世紀後半のイギリスの産業革命に始まり、19世紀にはヨーロッパ大陸・アメリカ・日本へ広がった。",region: "europe",cat: "経済・社会",rank: 2,course: ["sogo"],related: ["産業革命","世界の工場","国民国家"]},
  {term: "巨石人頭像",yomi: "きょせきじんとうぞう",def: "メキシコ湾岸のオルメカ文明がつくった巨大な石の頭像。高さ2〜3ｍにおよび、遠くから運んだ玄武岩を彫ったもので、オルメカ文明を代表する遺物である。",region: "america",cat: "文化・学問",rank: 1,course: ["tankyu"],related: ["オルメカ文明","メキシコ湾岸"]},
  {term: "市場経済",yomi: "しじょうけいざい",def: "商品の価格や生産量が市場での需要と供給によって決まる経済のしくみ。冷戦後、ソ連・東欧諸国やモンゴルなどが計画経済から市場経済に移行した。",region: "europe",cat: "経済・社会",rank: 2,course: ["sogo","tankyu"],related: ["計画経済","改革・開放政策","社会主義市場経済"]},
  {term: "帝国主義",yomi: "ていこくしゅぎ",def: "19世紀末から列強が軍事力を背景に植民地や勢力範囲を広げようとした政策。第2次産業革命による資本の輸出先や市場を求めて、アフリカ分割や中国分割が進んだ。",year: 1880,region: "europe",cat: "制度・政策",rank: 3,course: ["sogo","tankyu"],related: ["アフリカ分割","中国分割","第2次産業革命","世界政策"]},
  {term: "帝政",yomi: "ていせい",def: "皇帝が統治する政体。中華民国では大総統の袁世凱が1915年に帝政の復活をはかったが、各地で反対運動が起こり、翌年取り消した。",region: "east",cat: "制度・政策",rank: 1,course: ["sogo","tankyu"],related: ["袁世凱","皇帝","共和政"]},
  {term: "常勝軍",yomi: "じょうしょうぐん",def: "太平天国の鎮圧のため、外国人の指揮のもとで組織された洋式の軍隊。アメリカ人ウォード、ついでイギリス人ゴードンが指揮し、李鴻章の淮軍と協力した。",year: 1860,region: "east",cat: "組織・運動",rank: 2,course: ["tankyu"],related: ["太平天国","ゴードン","李鴻章"]},
  {term: "平和に関する布告",yomi: "へいわにかんするふこく",def: "1917年、十月革命直後にレーニンが発表した布告。無併合・無賠償・民族自決にもとづく即時講和を、すべての交戦国に呼びかけた。",year: 1917,region: "europe",cat: "条約・宣言",rank: 3,course: ["sogo","tankyu"],related: ["レーニン","十月革命","十四か条"]},
  {term: "平和五原則",yomi: "へいわごげんそく",def: "1954年、中国の周恩来とインドのネルーの会談で確認された原則。領土・主権の尊重、相互不可侵、内政不干渉、平等互恵、平和共存からなる。",year: 1954,region: "south",cat: "条約・宣言",rank: 3,course: ["sogo","tankyu"],related: ["ネルー","周恩来","平和十原則","アジア=アフリカ会議"]},
  {term: "平和共存",yomi: "へいわきょうぞん",def: "資本主義国と社会主義国の平和的な共存をめざす考え方。1956年、ソ連のフルシチョフがスターリン批判とともに打ち出し、冷戦の「雪どけ」が進んだ。",year: 1956,region: "europe",cat: "制度・政策",rank: 2,course: ["sogo","tankyu"],related: ["フルシチョフ","スターリン批判","雪どけ"]},
  {term: "平和十原則",yomi: "へいわじゅうげんそく",def: "1955年、インドネシアのバンドンで開かれたアジア=アフリカ会議で採択された原則。平和五原則を発展させ、反植民地主義・平和共存などを掲げた。",year: 1955,region: "sea",cat: "条約・宣言",rank: 3,course: ["sogo","tankyu"],related: ["アジア=アフリカ会議","平和五原則","スカルノ","バンドン"]},
  {term: "平和維持活動（PKO）",yomi: "へいわいじかつどう",def: "国際連合が紛争地域に部隊を派遣して、停戦の監視や治安維持などをおこなう活動。冷戦後に活動が増え、日本も1992年から参加している。",region: "europe",cat: "制度・政策",rank: 2,course: ["sogo","tankyu"],related: ["国際連合","安全保障理事会","冷戦の終結"]},
  {term: "平壌",yomi: "へいじょう",def: "朝鮮半島北西部の都市。前漢の楽浪郡の中心地域で、427年には高句麗が都を移した。現在は朝鮮民主主義人民共和国の首都である。",year: 427,region: "east",cat: "地名・地域",rank: 1,course: ["tankyu"],related: ["高句麗","楽浪郡","朝鮮民主主義人民共和国"]},
  {term: "平等・格差",yomi: "びょうどう・かくさ",def: "歴史総合で近代化や大衆化を考える視点の一つ。人々の平等を求める動きと、地域・身分・性別・民族などによる格差の両面から歴史を見る。",region: "europe",cat: "経済・社会",rank: 1,course: ["sogo"],related: ["対立・協調","南北問題"]},
  {term: "幾何原本",yomi: "きかげんぽん",def: "マテオ=リッチと徐光啓が、古代ギリシアのエウクレイデスの幾何学書を漢訳したもの。1607年に刊行され、西洋の数学を中国に紹介した。",year: 1607,region: "east",cat: "文化・学問",rank: 2,course: ["tankyu"],related: ["マテオ=リッチ","徐光啓","エウクレイデス"]},
  {term: "広州",yomi: "こうしゅう",def: "中国南部の港市。唐代に市舶司が置かれた。清は1757年にヨーロッパ船の来航を広州に限り、公行に貿易を独占させた。南京条約で開港された5港の一つである。",region: "east",cat: "地名・地域",rank: 3,course: ["sogo","tankyu"],related: ["公行","広州一港","南京条約","三角貿易"]},
  {term: "広州一港",yomi: "こうしゅういっこう",def: "1757年、清の乾隆帝がヨーロッパ船の来航を広州一港に限ったこと。特許商人の公行が貿易を独占した。イギリスはマカートニーを派遣して貿易の拡大を求めたが拒否された。",year: 1757,region: "east",cat: "制度・政策",rank: 2,course: ["tankyu"],related: ["乾隆帝","公行","マカートニー"]},
  {term: "広州湾",yomi: "こうしゅうわん",def: "中国広東省西部の湾。日清戦争後の中国分割のなかで、1899年にフランスが租借し、フランス領インドシナの一部として統治した。",year: 1899,region: "east",cat: "地名・地域",rank: 1,course: ["tankyu"],related: ["中国分割","フランス","租借地"]},
  {term: "広開土王（好太王）碑",yomi: "こうかいどおうひ",def: "高句麗の広開土王（好太王）の業績をたたえて414年に建てられた石碑。4世紀末から5世紀初めに倭が朝鮮半島に進出し、高句麗と戦ったことが記されている。",year: 414,region: "east",cat: "文化・学問",rank: 2,course: ["tankyu"],related: ["高句麗","倭","百済"]},
  {term: "庚戌の変",yomi: "こうじゅつのへん",def: "1550年、モンゴルのアルタン=ハンが明に侵入し、北京を包囲した事件。明は北虜に苦しめられ、のち和議を結んで交易を認めた。",year: 1550,region: "east",cat: "事件・戦争",rank: 2,course: ["tankyu"],related: ["アルタン","北虜南倭","明"]},
  {term: "府兵制",yomi: "ふへいせい",def: "西魏に始まり、隋・唐に受けつがれた兵制。均田制で土地を受けた農民から兵士を徴発し、首都の警備や辺境の防衛にあたらせた。唐の中期に崩れ、募兵制にかわった。",region: "east",cat: "制度・政策",rank: 3,course: ["tankyu"],related: ["西魏","均田制","募兵制","唐"]},
  {term: "度量衡の統一",yomi: "どりょうこうのとういつ",def: "秦の始皇帝が中国統一後に、それまで国ごとに異なっていた長さ・容積・重さの基準を統一したこと。貨幣や文字の統一とともに、全国の一体化を進めた。",year: -221,region: "east",cat: "制度・政策",rank: 2,course: ["tankyu"],related: ["始皇帝","半両銭","郡県制"]},
  {term: "康熙字典",yomi: "こうきじてん",def: "清の康熙帝の命で編纂された漢字の字典。1716年に完成し、約4万7千字を部首別・画数順に配列して、以後の漢字字典の模範となった。",year: 1716,region: "east",cat: "文化・学問",rank: 2,course: ["tankyu"],related: ["康熙帝","四庫全書","清"]},
  {term: "康熙帝",yomi: "こうきてい",def: "清の第4代皇帝。三藩の乱を鎮圧し、台湾の鄭氏を降して中国を統一した。1689年にロシアとネルチンスク条約を結んだ。『康熙字典』を編纂させるなど文化事業も進めた。",year: 1661,end: 1722,region: "east",cat: "人物",rank: 3,course: ["sogo","tankyu"],related: ["三藩の乱","ネルチンスク条約","典礼問題","清"]},
  {term: "廃藩置県",yomi: "はいはんちけん",def: "1871年、明治政府が藩を廃止して全国に府県を置いた改革。中央から府知事・県令を派遣して地方を治めさせ、中央集権体制を確立した。",year: 1871,region: "east",cat: "制度・政策",rank: 3,course: ["sogo"],related: ["明治維新","版籍奉還","地租改正"]},
  {term: "建康",yomi: "けんこう",def: "現在の南京。三国時代の呉の都建業がのちに改称されたもので、東晋や南朝の宋・斉・梁・陳の都となり、六朝文化の中心として栄えた。",region: "east",cat: "地名・地域",rank: 2,course: ["tankyu"],related: ["東晋","南朝","六朝文化","建業"]},
  {term: "建業",yomi: "けんぎょう",def: "三国時代の呉の都。孫権が都とした。現在の南京で、のちに建康と改められ、東晋や南朝の宋・斉・梁・陳の都として六朝文化の中心となった。",region: "east",cat: "地名・地域",rank: 1,course: ["tankyu"],related: ["呉","孫権","建康"]},
  {term: "弁韓",yomi: "べんかん",def: "古代朝鮮半島南部の三韓（馬韓・辰韓・弁韓）の一つ。小国の連合で、鉄の産地として知られ、のちの加耶（加羅）諸国の母体となった。",region: "east",cat: "国家・王朝",rank: 1,course: ["tankyu"],related: ["馬韓","辰韓","加耶"]},
  {term: "張作霖",yomi: "ちょうさくりん",def: "中国東北地方（満州）の軍閥。日本の支援を受けて北京政府の実権をにぎったが、北伐に敗れて東北へ退く途中、1928年に日本の関東軍に爆殺された。",year: 1928,region: "east",cat: "人物",rank: 2,course: ["sogo","tankyu"],related: ["北伐","張学良","満州事変"]},
  {term: "張騫",yomi: "ちょうけん",def: "前漢の武帝の命で、匈奴を挟みうちにする同盟を結ぶために大月氏へ派遣された人物。同盟は実現しなかったが、西域の事情が中国に伝わり、東西交流が盛んになった。",year: -139,region: "east",cat: "人物",rank: 3,course: ["tankyu"],related: ["武帝","大月氏","匈奴","大宛（フェルガナ）"]},
  {term: "強いアメリカ",yomi: "つよいあめりか",def: "1980年代、レーガン大統領が掲げたスローガン。ソ連に対抗して軍備を拡大し、国内では減税や規制緩和などの新自由主義的政策を進めた。",year: 1981,region: "america",cat: "制度・政策",rank: 1,course: ["sogo","tankyu"],related: ["レーガン","新自由主義","冷戦"]},
  {term: "強制栽培制度",yomi: "きょうせいさいばいせいど",def: "1830年からオランダがジャワで実施した制度。コーヒー・サトウキビ・藍などの輸出用作物を住民に強制的に栽培させ、安く買い上げてオランダの財政を立て直した。",year: 1830,region: "sea",cat: "制度・政策",rank: 3,course: ["tankyu"],related: ["オランダ領東インド","ジャワ","コーヒー"]},
  {term: "律令",yomi: "りつりょう",def: "律は刑法、令は行政法などの法典。隋・唐で整備され、これにもとづく中央集権体制は律令体制とよばれた。日本や新羅などの東アジア諸国にも影響をあたえた。",region: "east",cat: "制度・政策",rank: 3,course: ["tankyu"],related: ["唐","三省六部","大宝律令","均田制"]},
  {term: "後ウマイヤ朝",yomi: "こううまいやちょう",def: "756年、ウマイヤ家のアブド=アッラフマーン1世がイベリア半島に建てた王朝。都はコルドバ。10世紀にはカリフを称し、イスラーム文化の中心として繁栄した。",year: 756,end: 1031,region: "europe",cat: "国家・王朝",rank: 3,course: ["tankyu"],related: ["アブド=アッラフマーン1世","コルドバ","アッバース朝"]},
  {term: "後三国時代",yomi: "ごさんごくじだい",def: "9世紀末から10世紀前半、新羅が衰えて後百済・後高句麗（泰封）が分立した朝鮮半島の時代。936年に高麗の王建が統一した。",year: 892,end: 936,region: "east",cat: "国家・王朝",rank: 1,course: ["tankyu"],related: ["新羅","高麗","王建"]},
  {term: "後漢",yomi: "ごかん",def: "25年、光武帝（劉秀）が漢を再興して建てた王朝。都は洛陽。外戚と宦官の争いや党錮の禁で政治が乱れ、184年の黄巾の乱を経て、220年に滅んだ。",year: 25,end: 220,region: "east",cat: "国家・王朝",rank: 3,course: ["tankyu"],related: ["光武帝","党錮の禁","黄巾の乱","洛陽"]},
  {term: "後金",yomi: "こうきん",def: "1616年、女真のヌルハチが建てた国。八旗を組織し、満洲文字をつくらせた。1636年、子のホンタイジが国号を清と改めた。",year: 1616,end: 1636,region: "east",cat: "国家・王朝",rank: 3,course: ["tankyu"],related: ["ヌルハチ","女真","八旗","清"]},
  {term: "徐光啓",yomi: "じょこうけい",def: "明末の政治家・学者。マテオ=リッチと親交をもちキリスト教徒となった。『幾何原本』を共訳し、『農政全書』を著して西洋の学問を紹介した。",year: 1562,end: 1633,region: "east",cat: "人物",rank: 2,course: ["tankyu"],related: ["マテオ=リッチ","幾何原本","農政全書"]},
  {term: "微分積分",yomi: "びぶんせきぶん",def: "変化する量を扱う数学の分野。17世紀にニュートンとライプニッツがそれぞれ独自に考案し、物理学など近代科学の発展に大きく貢献した。",region: "europe",cat: "文化・学問",rank: 1,course: ["tankyu"],related: ["ニュートン","ライプニッツ","科学革命"]},
  {term: "徳治主義",yomi: "とくちしゅぎ",def: "為政者が自らの徳によって民衆を教え導き、国を治めるべきだとする儒家の考え方。法や刑罰による統治を重んじる法家の法治主義と対立した。",region: "east",cat: "思想・宗教",rank: 2,course: ["tankyu"],related: ["孔子","儒家","法家"]},
  {term: "徴兵令",yomi: "ちょうへいれい",def: "1873年、明治政府が公布した法令。満20歳以上の男子に兵役の義務を課し、士族にかわって国民からなる近代的な軍隊をつくった。",year: 1873,region: "east",cat: "制度・政策",rank: 2,course: ["sogo"],related: ["明治維新","国民国家","学制"]},
  {term: "心即理",yomi: "しんそくり",def: "明の王守仁（王陽明）がとなえた陽明学の根本思想。人の心そのものが理であるとし、知行合一と実践を重んじた。朱子学の性即理を批判した。",region: "east",cat: "思想・宗教",rank: 2,course: ["tankyu"],related: ["王守仁（王陽明）","陽明学","性即理"]},
  {term: "性即理",yomi: "せいそくり",def: "南宋の朱熹がとなえた朱子学の根本思想。人間の本性は天の理と同じであるとし、学問によって理を窮めること（格物致知）を説いた。",region: "east",cat: "思想・宗教",rank: 2,course: ["tankyu"],related: ["朱熹","朱子学","心即理"]}
]);
